-- One Cuadrao baseline (#1890). It replaces every file now in
-- supabase/migrations_archive/. Generated by
-- docs/reports/evidence/1890-baseline/build_baseline.py. Never edit it; change the
-- schema with a new migration.
set local lock_timeout = '5s';
set local statement_timeout = '60s';
set local check_function_bodies = false;
select pg_catalog.set_config('search_path', '', true);

create extension if not exists "uuid-ossp" with schema extensions;
create extension if not exists pg_stat_statements with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create extension if not exists pgcrypto with schema extensions;
create extension if not exists supabase_vault with schema vault;
create extension if not exists vector with schema public;

alter default privileges for role postgres in schema public revoke all on tables from postgres, anon, authenticated, service_role;
alter default privileges for role postgres in schema public revoke all on sequences from postgres, anon, authenticated, service_role;
alter default privileges for role postgres in schema public revoke all on functions from postgres, anon, authenticated, service_role;

CREATE SCHEMA argus_private;

CREATE TYPE public.avatar_theme AS ENUM (
    'ocean',
    'plum',
    'teal',
    'ember',
    'gold',
    'indigo',
    'slate'
);

SET default_tablespace = '';

SET default_table_access_method = heap;

CREATE TABLE public.backtest_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    conversation_id uuid,
    request_message_id uuid,
    confirmation_message_id uuid,
    idempotency_key text,
    payload_hash text NOT NULL,
    launch_payload jsonb NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    priority text DEFAULT 'normal'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 1 NOT NULL,
    queued_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    result_run_id uuid,
    failure_code text,
    failure_detail text,
    retryable boolean DEFAULT false NOT NULL,
    execution_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    operation_scope text DEFAULT 'chat.run_backtest'::text NOT NULL,
    identity_hash text,
    CONSTRAINT backtest_jobs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT backtest_jobs_max_attempts_check CHECK ((max_attempts >= 1)),
    CONSTRAINT backtest_jobs_operation_scope_check CHECK ((operation_scope = ANY (ARRAY['chat.run_backtest'::text, 'backtests.run'::text, 'chat.research'::text, 'workflows.proof'::text]))),
    CONSTRAINT backtest_jobs_priority_check CHECK ((priority = 'normal'::text)),
    CONSTRAINT backtest_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'canceled'::text, 'expired'::text])))
);

CREATE FUNCTION argus_private.backtest_job_result_hydrateable(j public.backtest_jobs) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $_$
  select (
    j.status = 'succeeded'
    and (
      exists (
        select 1
        from public.backtest_runs as r
        join public.evidence_artifacts as e
          on e.source_run_id = r.id
         and e.user_id = r.user_id
         and e.source_conversation_id = r.conversation_id
        where r.id = j.result_run_id
          and r.user_id = j.user_id
          and r.conversation_id = j.conversation_id
          and r.status = 'completed'
          and r.conversation_result_card
            ->> 'evidence_artifact_id' = e.id::text
          and r.conversation_result_card
            ->> 'idea_id' = e.idea_id::text
          and r.conversation_result_card
            ->> 'idea_version_id' = e.idea_version_id::text
      )
      or (
        j.operation_scope = 'chat.research'
        and exists (
          select 1
          from public.messages as rm
          where rm.user_id = j.user_id
            and rm.conversation_id = j.conversation_id
            and rm.role = 'assistant'
            and rm.id = (
              case
                when (j.execution_metadata ->> 'research_result_message_id')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                then (j.execution_metadata ->> 'research_result_message_id')::uuid
              end
            )
        )
      )
    )
  )
$_$;

CREATE FUNCTION argus_private.bind_guest_signup_handoff() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_marker jsonb := new.raw_user_meta_data -> 'argus_guest_signup';
  v_key text;
  v_handoff_id uuid;
  v_proof text;
  v_handoff public.guest_workspace_handoffs%rowtype;
  v_workspace public.guest_workspaces%rowtype;
  v_source_is_anonymous boolean;
  v_destination_email_hash text;
begin
  if v_marker is null then
    return new;
  end if;

  if jsonb_typeof(v_marker) <> 'object' then
    raise exception 'guest_signup_handoff_invalid' using errcode = '22023';
  end if;
  for v_key in select jsonb_object_keys(v_marker)
  loop
    if v_key not in ('handoff_id', 'proof') then
      raise exception 'guest_signup_handoff_invalid' using errcode = '22023';
    end if;
  end loop;

  begin
    v_handoff_id := nullif(v_marker ->> 'handoff_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'guest_signup_handoff_invalid' using errcode = '22023';
  end;
  v_proof := nullif(v_marker ->> 'proof', '');

  if v_handoff_id is null
     or v_proof is null
     or v_proof !~ '^[0-9a-f]{64}$'
     or coalesce(new.is_anonymous, false)
     or nullif(btrim(new.email), '') is null then
    raise exception 'guest_signup_handoff_invalid' using errcode = '22023';
  end if;

  select *
    into v_handoff
    from public.guest_workspace_handoffs
   where id = v_handoff_id
   for update;
  if not found
     or v_handoff.secret_hash is distinct from v_proof
     or v_handoff.handoff_kind <> 'new_account_signup'
     or v_handoff.status <> 'pending'
     or v_handoff.expires_at <= now()
     or v_handoff.destination_user_id is not null then
    raise exception 'guest_signup_handoff_invalid' using errcode = 'P0001';
  end if;

  v_destination_email_hash := encode(
    extensions.digest(
      convert_to(lower(btrim(new.email)), 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  if v_destination_email_hash is distinct from v_handoff.destination_email_hash then
    raise exception 'guest_signup_handoff_wrong_email' using errcode = 'P0001';
  end if;

  select coalesce(is_anonymous, false)
    into v_source_is_anonymous
    from auth.users
   where auth.users.id = v_handoff.source_user_id
   for update;
  if not found or v_source_is_anonymous is not true then
    raise exception 'guest_handoff_source_not_anonymous' using errcode = 'P0001';
  end if;

  select *
    into v_workspace
    from public.guest_workspaces
   where user_id = v_handoff.source_user_id
   for update;
  if not found
     or v_workspace.status <> 'active'
     or v_workspace.expires_at <= now()
     or v_workspace.expires_at is distinct from v_handoff.expires_at
     or v_workspace.conversation_id is distinct from v_handoff.source_conversation_id then
    raise exception 'guest_handoff_workspace_unavailable' using errcode = 'P0001';
  end if;

  update public.guest_workspace_handoffs
     set destination_user_id = new.id
   where id = v_handoff.id;

  -- raw_user_meta_data is user-editable and must never become durable proof.
  -- The marker has served its one purpose once the destination is bound.
  update auth.users
     set raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb)
       - 'argus_guest_signup'
   where id = new.id;

  return new;
end;
$_$;

CREATE FUNCTION argus_private.business_ai_consent_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if current_user='postgres' and tg_op='UPDATE' then
        if argus_private.business_custody_identity_change(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new; end if;
    end if;
    if tg_op = 'DELETE' then
        if exists (select 1 from public.spaces where id = old.space_id) then
            raise exception 'business_ai_consent_original_immutable' using errcode = '23514';
        end if;
        return old;
    elsif tg_op = 'UPDATE' then
        if (to_jsonb(new) - 'revoked_at' - 'revoked_by' - 'invalidated_by_transfer_id')
            is distinct from (to_jsonb(old) - 'revoked_at' - 'revoked_by' - 'invalidated_by_transfer_id')
            or (old.revoked_at is not null and
                (new.revoked_at, new.revoked_by, new.invalidated_by_transfer_id) is distinct from (old.revoked_at, old.revoked_by, old.invalidated_by_transfer_id)) then
            raise exception 'business_ai_consent_original_immutable' using errcode = '23514';
        end if;
    else
        perform 1 from public.spaces s
        join auth.users u on u.id = new.owner_id
        join public.business_client_grants g on g.id = new.grant_id
            and g.space_id = s.id and g.grantee_id = u.id and g.issuer_id = new.issuer_id
        where s.id = new.space_id and g.business_role = 'owner'
            and s.kind = 'business' and s.closed_at is null
            and coalesce(u.is_anonymous, false) = false
            and g.revoked_at is null and (g.expires_at is null or g.expires_at > clock_timestamp())
            and 'read' = any(g.capabilities) and 'prepare' = any(g.capabilities)
        for share of s, g;
        if not found or new.revoked_at is not null or new.invalidated_by_transfer_id is not null then
            raise exception 'business_ai_consent_owner_required' using errcode = '23514';
        end if;
        new.consented_at := clock_timestamp();
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_attachment_receipt_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if new.command->>'action' = 'prepare_attachment' and not exists (
        select 1 from public.financial_document_extractions d
        where d.connection_id=(new.command->'binding'->>'connection_id')::uuid
            and d.user_id=(new.command->'binding'->>'owner_id')::uuid
            and d.preparation_binding=new.command->'binding'
            and d.batch is not null
        for share of d
    ) then
        raise exception 'business_preparation_receipt_binding_missing' using errcode = '23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_auth_retention_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
    if exists(select 1 from public.spaces where kind='business' and (created_by=old.id or current_owner_id=old.id)) then
        raise exception 'business_custody_identity_detachment_required' using errcode='23514';
    end if;
    if exists(select 1 from public.business_turns where actor_id=old.id)
        or exists(select 1 from public.business_action_receipts where actor_id=old.id)
        or exists(select 1 from public.business_receipt_reading_consents where owner_id=old.id)
        or exists(select 1 from public.business_receipt_consent_commands where owner_id=old.id)
        or exists(select 1 from public.business_ai_consents where owner_id=old.id
            or consenting_actor_id=old.id or issuer_id=old.id or revoked_by=old.id)
        or exists(select 1 from public.business_transfer_mail_outbox where recipient_id=old.id or owner_id=old.id or target_id=old.id) then
        raise exception 'business_custody_identity_detachment_required' using errcode='23514';
    end if;
    return old;
end;
$$;

CREATE FUNCTION argus_private.business_bank_account_in_space(target_space uuid, target_account uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    select exists (
        select 1 from public.financial_accounts a
        join public.spaces s on s.id = a.owner_space_id
        where s.id = target_space and s.kind = 'business'
            and a.id = target_account and a.user_id = s.created_by
    );
$$;

CREATE FUNCTION argus_private.business_bank_account_scope_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if not argus_private.business_bank_account_in_space(new.space_id, new.account_id) then
        raise exception 'account_not_in_space' using errcode = '23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_bank_has_capability(target_space uuid, capability text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    select exists (
        select 1
        from public.business_client_grants g
        where g.space_id = target_space
            and g.grantee_id = (select auth.uid())
            and g.revoked_at is null
            and (g.expires_at is null or g.expires_at > pg_catalog.now())
            and capability = any (g.capabilities)
    );
$$;

CREATE FUNCTION argus_private.business_bank_line_outcomes_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if tg_op = 'DELETE' then
        if pg_trigger_depth() > 1 then
            return old;
        end if;
        raise exception 'business_evidence_immutable' using errcode = '23514';
    end if;
    if pg_trigger_depth() > 1
        and (to_jsonb(new) - 'created_by' - 'ended_by')
            = (to_jsonb(old) - 'created_by' - 'ended_by')
        and (new.created_by is null or new.created_by = old.created_by)
        and (new.ended_by is null or new.ended_by = old.ended_by)
    then
        return new;
    end if;
    if old.ended_at is null
        and new.ended_at is not null
        and (to_jsonb(new) - 'ended_at' - 'ended_by' - 'end_key')
            = (to_jsonb(old) - 'ended_at' - 'ended_by' - 'end_key')
    then
        return new;
    end if;
    raise exception 'business_evidence_immutable' using errcode = '23514';
end;
$$;

CREATE FUNCTION argus_private.business_bank_lines_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    raise exception 'business_bank_lines are immutable' using errcode = '55000';
end;
$$;

CREATE FUNCTION argus_private.business_bank_suggestions_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if new.space_id is distinct from old.space_id
        or new.line_id is distinct from old.line_id
        or new.target_kind is distinct from old.target_kind
        or new.target_id is distinct from old.target_id
        or new.amount_score is distinct from old.amount_score
        or new.date_score is distinct from old.date_score
        or new.merchant_score is distinct from old.merchant_score
        or new.created_at is distinct from old.created_at
    then
        raise exception 'business_bank_suggestion offer is immutable'
            using errcode = '55000';
    end if;
    if old.status <> 'pending' and new.status is distinct from old.status then
        raise exception 'business_bank_suggestion decision is final'
            using errcode = '55000';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_consent_transfer_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if new.invalidated_by_transfer_id is not null and not exists (
        select 1 from public.business_ownership_transfers t
        where t.id=new.invalidated_by_transfer_id and t.space_id=new.space_id
            and t.owner_id=new.owner_id and t.status='accepted'
    ) then
        raise exception 'business_consent_transfer_not_accepted' using errcode='23514';
    end if;
    return null;
end;
$$;

CREATE FUNCTION argus_private.business_country_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.kind = 'business' and old.country is distinct from new.country then
    raise exception 'business_country_immutable' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.business_custody_asset_actor(p_custodian uuid, p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    select p_custodian=p_actor or exists(select 1 from argus_private.business_custody_reservations
        where custodian_id=p_custodian and deleted_actor_id=p_actor);
$$;

CREATE FUNCTION argus_private.business_custody_before_fiscal_identity_change(p_table text, p_old jsonb, p_new jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare m record; expected jsonb; k text; v_actor uuid; v_issuer uuid;
begin
    if argus_private.business_custody_graph_identity_change(p_table,p_old,p_new) then return true; end if;
    if current_user<>'postgres' or coalesce(current_setting('argus.business_departure_actor',true),'')='' then
        return false;
    end if;
    v_actor:=current_setting('argus.business_departure_actor')::uuid;
    select a.*,s.created_by,s.current_owner_id into m
        from argus_private.business_departure_aliases a
        join public.spaces s on s.id=a.space_id
        join argus_private.account_deletion_runs d on d.id=a.deletion_run_id
        where a.actor_id=v_actor and a.departing_user_id=d.user_id and a.claim_id=d.claim_id
            and d.claimed_until>clock_timestamp() and d.status<>'done';
    if not found or p_old->>'space_id' is distinct from m.space_id::text
        or p_table<>all(array['business_sources','business_draft_revisions','business_draft_sources',
            'business_questions','business_turns','business_action_receipts','business_client_grants',
            'business_access_invites','business_receipt_reading_consents','business_receipt_consent_commands',
            'business_ai_consents','business_lifecycle_commands','business_ownership_transfers',
            'business_whatsapp_ai_consents']) then return false; end if;
    expected:=argus_private.business_custody_identity_json(p_old,m.departing_user_id::text,m.departing_user_id::text,m.actor_id::text);
    foreach k in array array['owner_id','target_id','historical_issuer_id'] loop
        if p_old->>k=m.departing_user_id::text then
            expected:=expected||jsonb_build_object(k,m.actor_id);
        end if;
    end loop;
    if p_table=any(array['business_client_grants','business_access_invites']) and p_old->>'issuer_id'=m.departing_user_id::text then
        v_issuer:=coalesce(m.current_owner_id,m.created_by);
        expected:=expected||jsonb_build_object('issuer_id',v_issuer,'historical_issuer_id',m.actor_id);
    elsif p_table='business_turns' and p_old->>'actor_id'=m.departing_user_id::text then
        expected:=expected||jsonb_build_object('sender_hash',encode(extensions.digest(m.actor_id::text,'sha256'),'hex'));
    elsif p_table='business_sources' and starts_with(p_old->>'source_key','web:'||m.departing_user_id::text||':') then
        expected:=expected||jsonb_build_object('source_key','web:'||m.actor_id::text||':'||substr(p_old->>'source_key',42));
    end if;
    if p_table='business_action_receipts' and p_old->'command' is distinct from expected->'command' then
        expected:=expected||jsonb_build_object('input_hash',p_new->'input_hash');
    end if;
    return expected=p_new and exists(select 1 from argus_private.business_custody_changes
        where space_id=m.space_id and table_name=p_table and old_row=p_old and new_row=p_new);
end;
$$;

CREATE FUNCTION argus_private.business_custody_client_allowed() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    select not exists(select 1 from argus_private.account_placeholders where id=(select auth.uid()));
$$;

CREATE FUNCTION argus_private.business_custody_graph_identity_change(p_table text, p_old jsonb, p_new jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_space uuid; m record; expected jsonb; prefix text; destination text;
begin
    if current_user<>'postgres' or coalesce(current_setting('argus.business_custody_space',true),'')='' then
        return false;
    end if;
    v_space:=current_setting('argus.business_custody_space')::uuid;
    select moves.departing_user_id::text as u,r.custodian_id::text as p,r.deleted_actor_id::text as a,moves.started_at
        into m from argus_private.business_custody_moves moves
        join argus_private.business_custody_reservations r on r.space_id=moves.space_id
        where moves.space_id=v_space;
    if not found then return false; end if;
    expected:=argus_private.business_custody_identity_json(p_old,m.u,m.p,m.a);
    if p_table='financial_document_extractions' then
        foreach prefix in array array['source','rebuilt'] loop
            if p_old->>(prefix||'_path') is not null then
                select destination_path into destination from argus_private.business_custody_objects
                    where space_id=v_space and source_path=p_old->>(prefix||'_path')
                        and sha256=p_old->>(prefix||'_sha256')
                        and size_bytes=(p_old->>(prefix||'_size_bytes'))::bigint
                        and media_type=p_old->>(prefix||'_media_type') and verified_at is not null
                        and destination_path=(case when prefix='source' then 'sealed/' else 'rebuilt/' end)||m.p||'/'||(p_old->'draft'->>'sha256');
                if not found then return false; end if;
                expected:=expected||jsonb_build_object(prefix||'_path',destination);
            end if;
        end loop;
        expected:=expected||'{"preparation_job":null}'::jsonb;
    elsif p_table='financial_source_connections' then
        expected:=expected||jsonb_build_object('external_ref','retained:'||(p_old->>'id'),
            'secret_ciphertext',null,'secret_key_fingerprint',null,'sync_cursor',null,'lease_holder',null,'lease_until',null);
    elsif p_table=any(array['business_receipt_reading_consents','business_receipt_consent_commands','business_ai_consents','business_lifecycle_commands','business_ownership_transfers']) then
        if p_old->>'owner_id'=m.u then expected:=expected||jsonb_build_object('owner_id',m.a); end if;
        if p_old->>'target_id'=m.u then expected:=expected||jsonb_build_object('target_id',m.a); end if;
        if p_table=any(array['business_receipt_reading_consents','business_ai_consents'])
            and p_old->>'owner_id'=m.u and p_old->>'revoked_at' is null then
            expected:=expected||jsonb_build_object('revoked_at',m.started_at);
            if p_table='business_ai_consents' then expected:=expected||jsonb_build_object('revoked_by',m.a); end if;
        end if;
    elsif p_table='business_whatsapp_ai_consents' then
        expected:=expected||jsonb_build_object('sender_hash','\x'||encode(extensions.digest(m.a,'sha256'),'hex'));
        if p_old->>'revoked_at' is null then
            expected:=expected||jsonb_build_object('revoked_at',m.started_at,'revoked_by',m.a);
        end if;
    elsif p_table='business_sources' and starts_with(p_old->>'source_key','web:'||m.u||':') then
        expected:=expected||jsonb_build_object('source_key','web:'||m.a||':'||substr(p_old->>'source_key',42));
    elsif p_table='financial_record_revisions' and p_old->>'recorded_by'=m.u then
        expected:=expected||'{"recorded_by":null}'::jsonb;
    elsif p_table='financial_asset_changes' and p_old->>'recorded_by'=m.u then
        expected:=expected||jsonb_build_object('recorded_by',m.a);
    elsif p_table='business_turns' and p_old->>'actor_id'=m.u then
        expected:=expected||jsonb_build_object('sender_hash',encode(extensions.digest(m.a,'sha256'),'hex'));
    end if;
    -- Hash uses the typed Python contract's canonical serialization. Only the
    -- identity-rewritten command may change; no amount, outcome or source edit.
    if p_table='business_action_receipts' and p_old->'command' is distinct from expected->'command' then
        expected:=expected||jsonb_build_object('input_hash',p_new->'input_hash');
    end if;
    if expected is distinct from p_new then return false; end if;
    return exists(
        select 1 from argus_private.business_custody_changes c
        join argus_private.business_custody_moves moves on moves.space_id=c.space_id
        join argus_private.account_deletion_runs d on d.id=moves.deletion_run_id
        join argus_private.business_custody_reservations r on r.space_id=moves.space_id
        join argus_private.account_placeholders p on p.id=r.custodian_id
        join auth.users u on u.id=p.id
        where c.space_id=v_space and c.table_name=p_table and c.old_row=p_old and c.new_row=p_new
            and d.user_id=moves.departing_user_id and d.claim_id=moves.claim_id
            and d.claimed_until>clock_timestamp() and d.status<>'done'
            and u.banned_until>clock_timestamp() and u.raw_app_meta_data->>'placeholder'='true'
    );
end;
$$;

CREATE FUNCTION argus_private.business_custody_identity_change(p_table text, p_old jsonb, p_new jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare m record; expected jsonb; actor uuid;
begin
    if p_table<>all(array['business_fiscal_operations','business_fiscal_observations']) then
        return argus_private.business_custody_before_fiscal_identity_change(p_table,p_old,p_new);
    end if;
    if current_user<>'postgres' then return false; end if;
    if coalesce(current_setting('argus.business_custody_space',true),'')<>'' then
        -- Existing custody validation is generic for typed JSON identities.
        return argus_private.business_custody_graph_identity_change(p_table,p_old,p_new);
    end if;
    if coalesce(current_setting('argus.business_departure_actor',true),'')='' then return false; end if;
    actor:=current_setting('argus.business_departure_actor')::uuid;
    select a.* into m from argus_private.business_departure_aliases a
        join argus_private.account_deletion_runs d on d.id=a.deletion_run_id
        where a.actor_id=actor and a.departing_user_id=d.user_id and a.claim_id=d.claim_id
        and d.claimed_until>clock_timestamp() and d.status<>'done';
    if not found or p_old->>'space_id' is distinct from m.space_id::text then return false; end if;
    expected:=argus_private.business_custody_identity_json(p_old,m.departing_user_id::text,m.departing_user_id::text,m.actor_id::text);
    return expected=p_new and exists(select 1 from argus_private.business_custody_changes
        where space_id=m.space_id and table_name=p_table and old_row=p_old and new_row=p_new);
end;
$$;

CREATE FUNCTION argus_private.business_custody_identity_json(v jsonb, u text, p text, a text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare result jsonb; k text; item jsonb;
begin
    if jsonb_typeof(v)='array' then
        select coalesce(jsonb_agg(argus_private.business_custody_identity_json(value,u,p,a) order by ordinality),'[]'::jsonb)
            into result from jsonb_array_elements(v) with ordinality;
        return result;
    elsif jsonb_typeof(v)<>'object' or v is null then return v;
    end if;
    result:='{}'::jsonb;
    for k,item in select * from jsonb_each(v) loop
        if item=to_jsonb(u) and k=any(array['actor_id','issuer_id','consenting_actor_id','revoked_by','recipient_id']) then item:=to_jsonb(a);
        elsif item=to_jsonb(u) and k=any(array['user_id','owner_id','record_owner_id','reversal_of_owner_id','activity_owner_id','account_owner_id','goal_owner_id','destination_owner_id']) then item:=to_jsonb(p);
        else item:=argus_private.business_custody_identity_json(item,u,p,a);
        end if;
        result:=result||jsonb_build_object(k,item);
    end loop;
    if v->>'actor_id'=u and v?'display_name' then result:=result||'{"display_name":"Exmiembro"}'::jsonb; end if;
    if v->>'issuer_id'=u and v?'issuer_display_name' then result:=result||'{"issuer_display_name":"Exmiembro"}'::jsonb; end if;
    return result;
end;
$$;

CREATE FUNCTION argus_private.business_document_binding_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
    b jsonb := new.preparation_binding;
    moved boolean := tg_op = 'UPDATE' and old.preparation_binding is not null
        and new.preparation_binding is distinct from old.preparation_binding;
begin
    if current_user='postgres' and tg_op='UPDATE' then
        if argus_private.business_custody_identity_change(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new; end if;
    end if;
    if tg_op = 'UPDATE' and old.preparation_binding is not null
        and (new.connection_id is distinct from old.connection_id
            or new.user_id is distinct from old.user_id
            or (old.batch is not null and new.batch is distinct from old.batch)
            or (new.source_bytes is not null
                and new.source_bytes is distinct from old.source_bytes)) then
        raise exception 'business_preparation_binding_immutable' using errcode = '23514';
    end if;
    if moved and (
        b is null
        or b->>'source_sha256' is distinct from old.preparation_binding->>'source_sha256'
        or b->'target' is distinct from old.preparation_binding->'target'
        or exists (
            select 1 from public.business_client_grants g
            where g.id=(old.preparation_binding->'actor'->>'grant_id')::uuid
                and g.revoked_at is null
                and (g.expires_at is null or g.expires_at > clock_timestamp())
        )
    ) then
        raise exception 'business_preparation_binding_immutable' using errcode = '23514';
    end if;
    if b is null then
        return new;
    end if;
    if new.draft->>'sha256' is distinct from b->>'source_sha256'
        or (new.source_sha256 is not null
            and new.source_sha256 is distinct from b->>'source_sha256') then
        raise exception 'business_preparation_source_changed' using errcode = '23514';
    end if;
    if tg_op = 'INSERT' or old.preparation_binding is null or moved then
        perform (b->>'binding_id')::uuid, (b->>'captured_at')::timestamptz;
        if not exists (
            select 1 from public.financial_source_connections c
            join public.spaces s on s.id=c.owner_space_id
            join public.business_client_grants g on g.space_id=s.id
            join auth.users u on u.id=g.grantee_id
            where c.id=new.connection_id and c.user_id=new.user_id
                and c.owner_space_id=(b->>'space_id')::uuid
                and s.created_by=new.user_id and s.kind='business' and s.closed_at is null
                and c.status<>'disconnected'
                and g.id=(b->'actor'->>'grant_id')::uuid
                and g.grantee_id=(b->'actor'->>'actor_id')::uuid
                and g.issuer_id=(b->'actor'->>'issuer_id')::uuid
                and g.revoked_at is null
                and (g.expires_at is null or g.expires_at > clock_timestamp())
                and g.capabilities @> array['read','prepare']::text[]
                and coalesce(u.is_anonymous,false)=false
                and new.draft->'consent'='true'::jsonb
                and new.draft->'source_available'='true'::jsonb
                and (new.source_path is not null or new.source_bytes is not null)
            for share of c,s,g
        ) then
            raise exception 'business_preparation_binding_denied' using errcode = '23514';
        end if;
    end if;
    if (tg_op = 'INSERT' or old.preparation_binding is null)
        and b->'target' <> 'null'::jsonb and not exists (
            select 1 from public.financial_import_events e
            where e.id=(b->'target'->>'draft_id')::uuid
                and e.owner_space_id=(b->>'space_id')::uuid and e.user_id=new.user_id
                and e.version=(b->'target'->>'version')::integer
                and e.state='open' and e.resolution ? 'business'
            for share of e
        ) then
        raise exception 'business_preparation_target_invalid' using errcode = '23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_fiscal_actor_retained() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
    if exists(select 1 from public.business_fiscal_operations o where
        o.prepared_actor->>'actor_id'=old.id::text or o.prepared_actor->>'issuer_id'=old.id::text
        or o.approved_actor->>'actor_id'=old.id::text or o.approved_actor->>'issuer_id'=old.id::text) then
        raise exception 'business_custody_identity_detachment_required' using errcode='23514';
    end if;
    return old;
end;
$$;

CREATE FUNCTION argus_private.business_fiscal_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
    if argus_private.business_custody_identity_change(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new; end if;
    if tg_table_name='business_fiscal_observations' then
        raise exception 'fiscal_evidence_immutable' using errcode='23514';
    end if;
    if (to_jsonb(new)-array['approved_actor','contact_token','contacted_at','provider_id','attempts','next_check','lease_token','lease_until'])
       is distinct from (to_jsonb(old)-array['approved_actor','contact_token','contacted_at','provider_id','attempts','next_check','lease_token','lease_until'])
       or (old.contact_token is not null and (new.contact_token is distinct from old.contact_token or new.contacted_at is distinct from old.contacted_at or new.approved_actor is distinct from old.approved_actor))
       or (old.provider_id is not null and new.provider_id is distinct from old.provider_id)
       or new.attempts<old.attempts then
        raise exception 'fiscal_intent_immutable' using errcode='23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_fiscal_number(ecf text, ncf text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    select case
        when upper(btrim(coalesce(nullif(ecf, ''), ncf), E' \t\r\n'))
            ~ '^(B[0-9]{10}|E[0-9]{12})$'
        then upper(btrim(coalesce(nullif(ecf, ''), ncf), E' \t\r\n'))
    end
$_$;

CREATE FUNCTION argus_private.business_grant_approve_owner_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if new.business_role is null then
        new.business_role := case
            when 'approve'=any(new.capabilities) and exists (
                select 1 from public.spaces where id=new.space_id and current_owner_id=new.grantee_id
            ) then 'owner'
            when 'approve'=any(new.capabilities) then null
            when 'prepare'=any(new.capabilities) then 'editor'
            else 'viewer' end;
    end if;
    if new.business_role is null then
        raise exception 'business_grant_approve_owner_only' using errcode='23514';
    end if;
    new.capabilities := case new.business_role
        when 'owner' then array['read','prepare','approve']
        when 'viewer' then array['read']
        else array['read','prepare'] end;
    if new.business_role='owner' and new.revoked_at is null and new.expires_at is not null then
        raise exception 'business_owner_cannot_expire' using errcode='23514';
    end if;
    if tg_op='UPDATE' then
        new.membership_version := old.membership_version + case
            when (new.business_role,new.revoked_at,new.expires_at) is distinct from (old.business_role,old.revoked_at,old.expires_at) then 1 else 0 end;
    end if;
    if tg_op='UPDATE' and old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
        raise exception 'business_membership_revocation_final' using errcode='23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_historical_actor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
    if not exists(select 1 from auth.users where id=new.actor_id)
       and not exists(select 1 from argus_private.business_custody_reservations
           where space_id=new.space_id and deleted_actor_id=new.actor_id)
       and not exists(select 1 from argus_private.business_departure_aliases
           where space_id=new.space_id and actor_id=new.actor_id) then
        raise exception 'business_actor_not_found' using errcode='23503';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_historical_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
    if not exists(select 1 from auth.users where id=new.owner_id)
       and not exists(select 1 from argus_private.business_custody_reservations
           where space_id=new.space_id and deleted_actor_id=new.owner_id)
       and not exists(select 1 from argus_private.business_departure_aliases
           where space_id=new.space_id and actor_id=new.owner_id) then
        raise exception 'business_historical_owner_not_found' using errcode='23503';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_immutable_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if current_user = 'postgres' and tg_op = 'UPDATE' then
        if argus_private.business_custody_identity_change(tg_table_name, to_jsonb(old), to_jsonb(new)) then
            return new;
        end if;
    end if;
    if tg_op = 'DELETE'
        and (pg_trigger_depth() > 1 or argus_private.business_purge_marked(old.space_id)) then
        return old;
    end if;
    raise exception 'business_evidence_immutable' using errcode = '23514';
end;
$$;

CREATE FUNCTION argus_private.business_initial_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if new.current_owner_id is null and new.closed_at is null then
        new.current_owner_id := new.created_by;
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_invitation_auth_retention() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
    if exists(select 1 from public.business_access_invites where recipient_id=old.id) then
        raise exception 'business_custody_identity_detachment_required' using errcode='23514';
    end if;
    return old;
end;
$$;

CREATE FUNCTION argus_private.business_invitation_recipient() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
    if new.recipient_id is not null and not exists(select 1 from auth.users where id=new.recipient_id)
        and not exists(select 1 from argus_private.business_custody_reservations where space_id=new.space_id and deleted_actor_id=new.recipient_id)
        and not exists(select 1 from argus_private.business_departure_aliases where space_id=new.space_id and actor_id=new.recipient_id) then
        raise exception 'business_invitation_recipient_not_found' using errcode='23503';
    end if;
    if tg_op='INSERT' and new.target_grant_id is not null and not exists(
        select 1 from public.business_client_grants where id=new.target_grant_id and space_id=new.space_id
            and grantee_id=new.recipient_id and membership_version=new.target_version
    ) then
        raise exception 'business_invitation_target_not_found' using errcode='23503';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_invite_terminal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare m record; expected jsonb;
begin
    if current_user='postgres' and (old.accepted_at is not null or old.revoked_at is not null)
        and current_setting('argus.business_custody_space',true)=old.space_id::text then
        select moves.departing_user_id::text as u,r.custodian_id::text as p,
            r.deleted_actor_id::text as a,s.current_owner_id::text as owner into m
        from argus_private.business_custody_moves moves
        join argus_private.business_custody_reservations r on r.space_id=moves.space_id
        join public.spaces s on s.id=moves.space_id
        join argus_private.account_deletion_runs d on d.id=moves.deletion_run_id
        join argus_private.account_placeholders p on p.id=r.custodian_id
        join auth.users u on u.id=p.id
        where moves.space_id=old.space_id and d.user_id=moves.departing_user_id
            and d.claim_id=moves.claim_id and d.claimed_until>clock_timestamp() and d.status<>'done'
            and u.banned_until>clock_timestamp() and u.raw_app_meta_data->>'placeholder'='true';
        if found and old.issuer_id::text=m.u then
            expected:=argus_private.business_custody_identity_json(to_jsonb(old),m.u,m.p,m.a)
                ||jsonb_build_object('issuer_id',coalesce(nullif(m.owner,m.u),m.p),'historical_issuer_id',m.a);
            if expected=to_jsonb(new) and exists(
                select 1 from argus_private.business_custody_changes where space_id=old.space_id
                    and table_name=tg_table_name and old_row=to_jsonb(old) and new_row=to_jsonb(new)
            ) then return new; end if;
        end if;
    end if;
    if current_user='postgres' and (old.accepted_at is not null or old.revoked_at is not null)
        and argus_private.business_custody_identity_change(tg_table_name,to_jsonb(old),to_jsonb(new)) then
        return new;
    end if;
    if (old.accepted_at is not null or old.revoked_at is not null)
        and (to_jsonb(new)-'accepted_grant_id')
            is distinct from (to_jsonb(old)-'accepted_grant_id') then
        raise exception 'business_invite_terminal' using errcode='23514';
    end if;
    if old.expires_at<=clock_timestamp() and new.expires_at>old.expires_at then
        raise exception 'business_invite_expired' using errcode='23514';
    end if;
    if (new.space_id,new.email,new.requested_role,new.recipient_id,new.target_grant_id,new.target_version,new.issuer_id,new.historical_issuer_id) is distinct from (old.space_id,old.email,old.requested_role,old.recipient_id,old.target_grant_id,old.target_version,old.issuer_id,old.historical_issuer_id) then
        raise exception 'business_invite_recipient_immutable' using errcode='23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_invoice_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if tg_table_name in ('business_invoice_revisions','business_invoice_commands') then
        raise exception 'invoice_revision_immutable' using errcode='23514';
    end if;
    if old.operation_id is not null and new is distinct from old then
        raise exception 'invoice_issue_immutable' using errcode='23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_membership_owner_required() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_space uuid;
begin
    v_space := coalesce(to_jsonb(new)->>'space_id',to_jsonb(old)->>'space_id',to_jsonb(new)->>'id')::uuid;
    if exists (select 1 from public.spaces where id=v_space and kind='business' and closed_at is null)
        and not exists (select 1 from public.business_client_grants where space_id=v_space
            and business_role='owner' and revoked_at is null and expires_at is null) then
        raise exception 'business_last_owner_required' using errcode='23514';
    end if;
    return null;
end;
$$;

CREATE FUNCTION argus_private.business_membership_serialize() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_space uuid;
begin
    v_space := case when tg_op='DELETE' then old.space_id else new.space_id end;
    -- A write, not just a lock, aborts stale repeatable-read mutations.
    update public.spaces set membership_revision=membership_revision+1 where id=v_space;
    if tg_op='UPDATE' and old.space_id<>new.space_id then
        raise exception 'business_membership_scope_immutable' using errcode='23514';
    end if;
    return case when tg_op='DELETE' then old else new end;
end;
$$;

CREATE FUNCTION argus_private.business_owner_consent_revoked() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if old.business_role='owner' and old.revoked_at is null
        and (tg_op='DELETE' or new.business_role<>'owner' or new.revoked_at is not null) then
        update public.business_receipt_reading_consents set revoked_at=clock_timestamp()
            where space_id=old.space_id and owner_id=old.grantee_id and revoked_at is null;
        update public.business_ai_consents set revoked_at=clock_timestamp()
            where space_id=old.space_id and owner_id=old.grantee_id and revoked_at is null;
    end if;
    if tg_op='DELETE' then return old; end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_plan_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if current_user='postgres' and tg_op='UPDATE' then
        if argus_private.business_custody_identity_change(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new; end if;
    end if;
    if old.plan is not null and (new.plan, new.plan_actor)
        is distinct from (old.plan, old.plan_actor) then
        raise exception 'business_plan_immutable' using errcode = '23514';
    end if;
    if (new.turn_key, new.space_id, new.sender_hash, new.actor_id, new.arrival_sequence)
        is distinct from
       (old.turn_key, old.space_id, old.sender_hash, old.actor_id, old.arrival_sequence) then
        raise exception 'business_turn_identity_immutable' using errcode = '23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_purge_marked(space uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    select current_user = 'postgres'
        and current_setting('argus.business_purge_space', true) = space::text
$$;

CREATE FUNCTION argus_private.business_receipt_plan_required() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
    saved_action jsonb;
    saved_actor jsonb;
begin
    if current_user='postgres' and tg_op='UPDATE' then
        if argus_private.business_custody_identity_change(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new; end if;
    end if;
    if tg_op = 'UPDATE' then
        if (new.space_id, new.actor_id, new.idempotency_key, new.input_hash,
            new.command, new.turn_key, new.action_index, new.actor)
            is distinct from
           (old.space_id, old.actor_id, old.idempotency_key, old.input_hash,
            old.command, old.turn_key, old.action_index, old.actor) then
            raise exception 'business_action_identity_immutable' using errcode = '23514';
        end if;
        if old.outcome is not null and (
            new.outcome is null or (old.outcome->>'outcome' <> 'outcome_unknown'
                and new.outcome is distinct from old.outcome)
        ) then
            raise exception 'business_action_outcome_immutable' using errcode = '23514';
        end if;
    end if;
    if new.turn_key is not null then
        select t.plan->'actions'->new.action_index, t.plan_actor
          into saved_action, saved_actor
          from public.business_turns t
         where t.turn_key = new.turn_key and t.space_id = new.space_id
           and t.actor_id = new.actor_id;
        if saved_action is null or saved_action <> new.command
            or saved_actor is distinct from new.actor then
            raise exception 'business_action_plan_required' using errcode = '23514';
        end if;
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_revision_sources_scoped() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
    source_id uuid;
begin
    for source_id in select unnest(new.source_ids) order by 1 loop
        perform 1 from public.business_sources s
         where s.id = source_id and s.space_id = new.space_id
         for key share;
        if not found then
            raise exception 'business_revision_source_not_found' using errcode = '23503';
        end if;
    end loop;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_rnc_digits(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
    select case
        when value ~ '^[0-9 -]+$'
            and length(regexp_replace(value, '[ -]', '', 'g')) in (9, 11)
            and regexp_replace(value, '[ -]', '', 'g') ~ '[1-9]'
        then regexp_replace(value, '[ -]', '', 'g')
    end
$_$;

CREATE FUNCTION argus_private.business_settlement_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if tg_op = 'DELETE'
        and (pg_trigger_depth() > 1 or argus_private.business_purge_marked(old.space_id)) then
        return old;
    end if;
    raise exception 'business_evidence_immutable' using errcode = '23514';
end;
$$;

CREATE FUNCTION argus_private.business_settlement_follows_match() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
    live record;
begin
    select o.applied_status, o.applied_settled_on, o.applied_payment_method
    into live
    from public.business_bank_line_outcomes o
    where o.space_id = new.space_id
        and o.target_id = new.activity_id
        and o.kind = 'match'
        and o.ended_at is null;
    if found and (new.status, new.settled_on, new.payment_method)
        is distinct from
        (live.applied_status, live.applied_settled_on, live.applied_payment_method)
    then
        raise exception 'business_document_matched' using errcode = '23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_settlement_revision_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if pg_trigger_depth() > 1 then
        if tg_op = 'DELETE' then
            return old;
        end if;
        if old.actor_id is not null
            and new.actor_id is null
            and (to_jsonb(new) - 'actor_id') = (to_jsonb(old) - 'actor_id') then
            return new;
        end if;
    end if;
    raise exception 'business_evidence_immutable' using errcode = '23514';
end;
$$;

CREATE FUNCTION argus_private.business_transfer_deadline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    new.expires_at:=new.created_at+interval '168 hours';
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_transfer_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if current_user='postgres' and tg_op='UPDATE' then
        if argus_private.business_custody_identity_change(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new; end if;
    end if;
    if (to_jsonb(new)-'status'-'resolved_at') is distinct from (to_jsonb(old)-'status'-'resolved_at')
        or old.status<>'pending' or new.status not in ('accepted','cancelled','declined','expired')
        or (new.status='expired' and new.resolved_at<old.expires_at)
        or (new.status in ('accepted','declined') and new.resolved_at>=old.expires_at) then
        raise exception 'business_transfer_history_immutable' using errcode='23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_whatsapp_consent_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if current_user='postgres' and tg_op='UPDATE' then
        if argus_private.business_custody_identity_change(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new; end if;
    end if;
    if tg_op = 'DELETE' then
        if exists (select 1 from public.whatsapp_sender_links where id = old.sender_link_id) then
            raise exception 'whatsapp_consent_original_immutable' using errcode = '23514';
        end if;
        return old;
    elsif tg_op = 'UPDATE' then
        if (to_jsonb(new) - 'revoked_at' - 'revoked_by')
            is distinct from (to_jsonb(old) - 'revoked_at' - 'revoked_by')
            or (old.revoked_at is not null and
                (new.revoked_at, new.revoked_by) is distinct from (old.revoked_at, old.revoked_by)) then
            raise exception 'whatsapp_consent_original_immutable' using errcode = '23514';
        end if;
    else
        perform 1 from public.whatsapp_sender_links l
        join public.spaces s on s.id = l.destination_space_id and s.created_by = l.destination_owner_id
        join auth.users u on u.id = l.destination_owner_id
        join public.business_client_grants g on g.id = new.grant_id
            and g.space_id = s.id and g.grantee_id = u.id and g.issuer_id = new.issuer_id
        where l.id = new.sender_link_id and l.status = 'active'
            and s.kind = 'business' and s.closed_at is null
            and coalesce(u.is_anonymous, false) = false
            and g.revoked_at is null and (g.expires_at is null or g.expires_at > clock_timestamp())
            and 'read' = any(g.capabilities) and 'prepare' = any(g.capabilities)
        for share of l, s, g;
        if not found or new.revoked_at is not null then
            raise exception 'whatsapp_consent_owner_required' using errcode = '23514';
        end if;
        new.consented_at := clock_timestamp();
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.business_workspace_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if (new.name,new.business_provided_details,new.business_appearance) is distinct from
        (old.name,old.business_provided_details,old.business_appearance) then
        new.business_workspace_revision := old.business_workspace_revision + 1;
    else
        new.business_workspace_revision := old.business_workspace_revision;
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.claim_guest_workspace_handoff(p_handoff_id uuid, p_secret_hash text, p_destination_user_id uuid) RETURNS TABLE(source_user_id uuid, destination_user_id uuid, conversation_id uuid, pending_action jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
declare
  v_handoff public.guest_workspace_handoffs%rowtype;
  v_workspace public.guest_workspaces%rowtype;
  v_source_is_anonymous boolean;
  v_destination_is_anonymous boolean;
  v_destination_email text;
begin
  select *
    into v_handoff
    from public.guest_workspace_handoffs
   where id = p_handoff_id
   for update;

  if not found or v_handoff.secret_hash is distinct from p_secret_hash then
    raise exception 'guest_handoff_invalid' using errcode = 'P0002';
  end if;
  if v_handoff.status = 'consumed' then
    raise exception 'guest_handoff_consumed' using errcode = 'P0001';
  end if;
  if v_handoff.status <> 'pending' then
    raise exception 'guest_handoff_invalid' using errcode = 'P0002';
  end if;
  if v_handoff.expires_at <= now() then
    raise exception 'guest_handoff_expired' using errcode = 'P0001';
  end if;
  if v_handoff.destination_user_id is distinct from p_destination_user_id then
    raise exception 'guest_handoff_wrong_destination' using errcode = 'P0001';
  end if;

  select coalesce(is_anonymous, false)
    into v_source_is_anonymous
    from auth.users
   where id = v_handoff.source_user_id;
  select coalesce(is_anonymous, false), nullif(btrim(email), '')
    into v_destination_is_anonymous, v_destination_email
    from auth.users
   where id = p_destination_user_id;
  if not found or v_destination_is_anonymous or v_destination_email is null then
    raise exception 'guest_handoff_wrong_destination' using errcode = 'P0001';
  end if;
  if v_source_is_anonymous is not true then
    raise exception 'guest_handoff_source_not_anonymous' using errcode = 'P0001';
  end if;

  select *
    into v_workspace
    from public.guest_workspaces
   where user_id = v_handoff.source_user_id
   for update;
  if not found
     or v_workspace.status <> 'active'
     or v_workspace.expires_at <= now()
     or v_workspace.conversation_id is distinct from v_handoff.source_conversation_id then
    raise exception 'guest_handoff_workspace_unavailable' using errcode = 'P0001';
  end if;

  -- Every user-owned product row must belong to this one guest conversation,
  -- and every row anchored to that conversation must belong to the source.
  if exists (
      select 1 from public.conversations
       where (user_id = v_handoff.source_user_id and id <> v_handoff.source_conversation_id)
          or (id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or not exists (
      select 1 from public.conversations
       where id = v_handoff.source_conversation_id
         and user_id = v_handoff.source_user_id
    )
    or exists (
      select 1 from public.messages
       where (user_id = v_handoff.source_user_id and conversation_id <> v_handoff.source_conversation_id)
          or (conversation_id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1 from public.chat_turn_lifecycles
       where (user_id = v_handoff.source_user_id and conversation_id <> v_handoff.source_conversation_id)
          or (conversation_id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1 from public.strategies
       where (user_id = v_handoff.source_user_id and conversation_id is distinct from v_handoff.source_conversation_id)
          or (conversation_id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1 from public.backtest_runs
       where (user_id = v_handoff.source_user_id and conversation_id is distinct from v_handoff.source_conversation_id)
          or (conversation_id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1 from public.backtest_jobs
       where (user_id = v_handoff.source_user_id and conversation_id <> v_handoff.source_conversation_id)
          or (conversation_id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1 from public.ideas
       where (user_id = v_handoff.source_user_id and source_conversation_id is distinct from v_handoff.source_conversation_id)
          or (source_conversation_id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1 from public.idea_versions
       where (user_id = v_handoff.source_user_id and source_conversation_id is distinct from v_handoff.source_conversation_id)
          or (source_conversation_id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1 from public.evidence_artifacts
       where (user_id = v_handoff.source_user_id and source_conversation_id is distinct from v_handoff.source_conversation_id)
          or (source_conversation_id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1 from public.decision_notes
       where (user_id = v_handoff.source_user_id and source_conversation_id is distinct from v_handoff.source_conversation_id)
          or (source_conversation_id = v_handoff.source_conversation_id and user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1
        from public.run_context_packets as link
        join public.backtest_runs as run on run.id = link.run_id
       where (link.user_id = v_handoff.source_user_id and run.user_id <> v_handoff.source_user_id)
          or (run.user_id = v_handoff.source_user_id and link.user_id <> v_handoff.source_user_id)
    )
    or exists (
      select 1 from public.collections where user_id = v_handoff.source_user_id
    )
    or exists (
      select 1 from public.collection_strategies where user_id = v_handoff.source_user_id
    ) then
    raise exception 'guest_handoff_unsafe_product_graph' using errcode = 'P0001';
  end if;

  perform set_config('argus.owner_transfer', 'on', true);

  update public.conversations
     set user_id = p_destination_user_id
   where id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.messages
     set user_id = p_destination_user_id
   where conversation_id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.chat_turn_lifecycles
     set user_id = p_destination_user_id
   where conversation_id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.strategies
     set user_id = p_destination_user_id
   where conversation_id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.backtest_runs
     set user_id = p_destination_user_id
   where conversation_id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.backtest_jobs
     set user_id = p_destination_user_id
   where conversation_id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.ideas
     set user_id = p_destination_user_id
   where source_conversation_id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.idea_versions
     set user_id = p_destination_user_id
   where source_conversation_id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.evidence_artifacts
     set user_id = p_destination_user_id
   where source_conversation_id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.decision_notes
     set user_id = p_destination_user_id
   where source_conversation_id = v_handoff.source_conversation_id
     and user_id = v_handoff.source_user_id;
  update public.context_packets
     set user_id = p_destination_user_id
   where user_id = v_handoff.source_user_id;
  update public.run_context_packets
     set user_id = p_destination_user_id
   where user_id = v_handoff.source_user_id;

  update public.guest_workspaces
     set status = 'claimed',
         claimed_by = p_destination_user_id,
         claimed_at = now(),
         updated_at = now()
   where user_id = v_handoff.source_user_id;
  update public.guest_workspace_handoffs
     set status = 'consumed',
         consumed_at = now()
   where id = v_handoff.id;

  return query
  select
    v_handoff.source_user_id,
    p_destination_user_id,
    v_handoff.source_conversation_id,
    v_handoff.pending_action;
end;
$$;

CREATE FUNCTION argus_private.claim_guest_workspace_handoff_by_email(p_handoff_id uuid, p_secret_hash text, p_destination_user_id uuid, p_allow_same_destination_replay boolean DEFAULT false) RETURNS TABLE(source_user_id uuid, destination_user_id uuid, conversation_id uuid, pending_action jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
declare
  v_handoff public.guest_workspace_handoffs%rowtype;
  v_destination_is_anonymous boolean;
  v_destination_email_hash text;
begin
  select *
    into v_handoff
    from public.guest_workspace_handoffs
   where id = p_handoff_id
   for update;

  if not found or v_handoff.secret_hash is distinct from p_secret_hash then
    raise exception 'guest_handoff_invalid' using errcode = 'P0002';
  end if;

  select
    coalesce(auth_user.is_anonymous, false),
    encode(
      extensions.digest(
        convert_to(lower(btrim(auth_user.email)), 'UTF8'),
        'sha256'
      ),
      'hex'
    )
    into v_destination_is_anonymous, v_destination_email_hash
    from auth.users as auth_user
   where auth_user.id = p_destination_user_id
   for update;
  if not found
     or v_destination_is_anonymous
     or v_destination_email_hash is distinct from v_handoff.destination_email_hash then
    raise exception 'guest_handoff_wrong_destination' using errcode = 'P0001';
  end if;

  if v_handoff.status = 'consumed' then
    if p_allow_same_destination_replay
       and v_handoff.destination_user_id is not distinct from p_destination_user_id then
      return query
      select
        v_handoff.source_user_id,
        p_destination_user_id,
        v_handoff.source_conversation_id,
        v_handoff.pending_action,
        true;
      return;
    end if;
    raise exception 'guest_handoff_consumed' using errcode = 'P0001';
  end if;
  if v_handoff.status <> 'pending' then
    raise exception 'guest_handoff_invalid' using errcode = 'P0002';
  end if;
  if v_handoff.expires_at <= now() then
    raise exception 'guest_handoff_expired' using errcode = 'P0001';
  end if;
  if v_handoff.destination_user_id is not null
     and v_handoff.destination_user_id is distinct from p_destination_user_id then
    raise exception 'guest_handoff_wrong_destination' using errcode = 'P0001';
  end if;

  update public.guest_workspace_handoffs
     set destination_user_id = p_destination_user_id
   where id = v_handoff.id;

  return query
  select claimed.*, false
    from argus_private.claim_guest_workspace_handoff(
      p_handoff_id,
      p_secret_hash,
      p_destination_user_id
    ) as claimed;
end;
$$;

CREATE FUNCTION argus_private.conversation_is_personal(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    select not exists (
        select 1 from public.conversations c
        where c.id = p_conversation_id and c.owner_space_id is not null
    );
$$;

CREATE FUNCTION argus_private.defer_deletion_keys() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  set constraints
    public.household_plan_bindings_budget_id_owner_user_id_fkey,
    public.household_plan_bindings_expectation_id_owner_user_id_fkey,
    public.household_plan_bindings_goal_id_owner_user_id_fkey,
    public.household_plan_bindings_debt_plan_id_owner_user_id_fkey,
    public.household_plan_bindings_kind_definition_id_owner_user_id_f_fkey,
    public.household_plan_bindings_kind_definition_id_owner_user_id_r_fkey,
    public.household_plan_bindings_owner_membership_id_household_id_o_fkey,
    public.financial_plan_links_budget_id_user_id_fkey,
    public.financial_plan_links_expectation_id_user_id_fkey,
    public.financial_plan_links_goal_id_user_id_fkey,
    public.financial_plan_links_debt_plan_id_user_id_fkey,
    public.financial_plan_links_binding_id_user_id_fkey,
    public.financial_plan_links_activity_id_activity_revision_activit_fkey,
    public.financial_goal_allocations_goal_id_goal_owner_id_fkey,
    public.financial_goal_allocations_binding_id_goal_owner_id_fkey,
    public.financial_goal_allocation_revisions_goal_id_goal_owner_id_fkey,
    public.financial_goal_allocation_revi_account_id_account_owner_id_fkey,
    public.financial_plan_responsibiliti_kind_definition_id_owner_id__fkey,
    public.financial_debt_plans_debt_account_id_user_id_fkey,
    public.financial_records_account_id_user_id_fkey,
    public.financial_record_revisions_record_id_user_id_fkey,
    public.financial_purchase_revision_owner_fk,
    public.financial_activity_revisions_activity_id_user_id_fkey,
    public.financial_activity_membership_revision_fk,
    public.financial_activity_memberships_activity_id_user_id_fkey,
    public.household_plan_archived_claim_activity_id_activity_revisio_fkey,
    public.household_plan_archived_activ_activity_id_activity_revisio_fkey,
    public.financial_activity_current_revision_fk,
    public.financial_activity_original_record_revision,
    public.financial_payment_return_original_owner_fk
  deferred;
end;
$$;

CREATE FUNCTION argus_private.deletion_activity_household(p_activity_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select b.household_id
    from (
      select l.binding_id, l.created_at as claimed_at, l.claim_id as claim_ref
        from public.financial_plan_links l
       where l.activity_id = p_activity_id and l.binding_id is not null
      union all
      select c.binding_id, coalesce(c.claim_created_at, 'infinity'), c.claim_id
        from public.household_plan_archived_claims c
       where c.activity_id = p_activity_id
      union all
      select a.binding_id, 'infinity'::timestamptz, a.binding_id
        from public.household_plan_archived_activities a
       where a.activity_id = p_activity_id
    ) c
    join public.household_plan_bindings b on b.id = c.binding_id
   order by c.claimed_at, c.claim_ref
   limit 1;
$$;

CREATE FUNCTION argus_private.deletion_auth_blockers(p_user_id uuid) RETURNS SETOF text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_key record;
  v_held boolean;
begin
  for v_key in
    select c.conrelid::regclass as tbl, a.attname as col
      from pg_catalog.pg_constraint c
      join pg_catalog.pg_class r on r.oid = c.conrelid
      join pg_catalog.pg_namespace n on n.oid = r.relnamespace
      join pg_catalog.pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
     where c.contype = 'f' and c.confrelid = 'auth.users'::regclass
       and c.confdeltype in ('a', 'r') and array_length(c.conkey, 1) = 1
       and n.nspname <> 'auth'
     order by 1, 2
  loop
    execute format('select exists (select 1 from %s where %I = $1)', v_key.tbl, v_key.col)
      into v_held using p_user_id;
    if v_held then
      return next v_key.tbl::text || '.' || v_key.col;
    end if;
  end loop;
end;
$_$;

CREATE FUNCTION argus_private.deletion_drop_binding(p_binding_id uuid, p_owner uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform argus_private.require_deletion_writer();
  if current_user <> 'postgres' then
    raise exception 'account_deletion_writer_required' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.household_plan_bindings where id = p_binding_id and owner_user_id = p_owner
  ) then
    raise exception 'account_deletion_binding_not_found' using errcode = 'P0002';
  end if;
  delete from public.household_plan_archived_claims where binding_id = p_binding_id;
  delete from public.household_plan_archived_activities where binding_id = p_binding_id;
  delete from public.household_plan_archived_allocations where binding_id = p_binding_id;
  delete from public.household_plan_receipts where binding_id = p_binding_id;
  delete from public.household_plan_participants where binding_id = p_binding_id;
  delete from public.financial_plan_links where binding_id = p_binding_id;
  delete from public.financial_goal_allocations where binding_id = p_binding_id;
  delete from public.financial_goal_allocation_revisions where binding_id = p_binding_id;
  delete from public.household_plan_bindings where id = p_binding_id;
end;
$$;

CREATE FUNCTION argus_private.deletion_finish(p_user_id uuid, p_actor_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_email text;
  v_threads text[];
  v_blocker text;
begin
  perform argus_private.require_deletion_writer();
  if current_user <> 'postgres' then
    raise exception 'account_deletion_writer_required' using errcode = '42501';
  end if;
  perform argus_private.defer_deletion_keys();
  select email into v_email from auth.users where id = p_user_id;

  -- 5.1: the person's command receipts and their name on others' revisions.
  delete from public.household_plan_receipts
   where actor_id = p_user_id
      or membership_id in (select id from public.household_members where user_id = p_user_id);
  update public.financial_plan_definition_revisions set actor_id = null where actor_id = p_user_id;
  delete from public.household_account_grants
   where owner_user_id = p_user_id
      or recipient_membership_id in (select id from public.household_members where user_id = p_user_id);
  delete from public.household_command_receipts where actor_id = p_user_id;

  -- 5.3: the person's own remaining plans, explicitly.
  delete from public.financial_plan_links where user_id = p_user_id;
  delete from public.financial_goal_allocations where goal_owner_id = p_user_id or account_owner_id = p_user_id;
  delete from public.financial_plan_responsibilities where owner_id = p_user_id;
  delete from public.financial_budgets where user_id = p_user_id;
  delete from public.financial_expectations where user_id = p_user_id;
  delete from public.financial_goals where user_id = p_user_id;
  delete from public.financial_debt_plans where user_id = p_user_id;
  delete from public.financial_goal_allocation_revisions where goal_owner_id = p_user_id;
  delete from public.financial_plan_definition_revisions where owner_id = p_user_id;

  -- 6: feedback keeps no email or user id.
  update public.feedback
     set context = context - 'account_email' - 'user_id' - 'email'
   where (user_id = p_user_id or (v_email is not null and context ->> 'account_email' = v_email))
     and context is not null;

  -- Outside the FKs (Marcus's design note, section 3).
  select array_agg(id::text) into v_threads from public.conversations where user_id = p_user_id;
  if v_threads is not null then
    delete from public.checkpoint_writes where thread_id = any(v_threads);
    delete from public.checkpoint_blobs where thread_id = any(v_threads);
    delete from public.checkpoints where thread_id = any(v_threads);
  end if;
  delete from public.argus_memory_vectors where payload ->> 'user_id' = p_user_id::text;
  if v_email is not null then
    delete from public.private_alpha_allowlist where lower(email) = lower(v_email);
    delete from public.private_alpha_access_welcome_claims where lower(recipient_email) = lower(v_email);
    delete from public.private_alpha_access_welcome_deliveries where lower(recipient_email) = lower(v_email);
  end if;
  delete from public.visitor_usage_counters
   where visitor_key in ('user:' || p_user_id::text, 'session:' || p_user_id::text);
  if p_actor_hash is not null then
    delete from public.guest_funnel_milestones where subject_key = p_actor_hash;
  end if;

  set constraints all immediate;

  -- Nothing that would block the Admin API delete, or keep the id, is left.
  v_blocker := case
    when exists (select 1 from public.financial_plan_definition_revisions where owner_id = p_user_id or actor_id = p_user_id)
      then 'financial_plan_definition_revisions'
    when exists (select 1 from public.household_plan_receipts where actor_id = p_user_id)
      then 'household_plan_receipts'
    when exists (select 1 from public.households where admin_user_id = p_user_id and status = 'active')
      then 'households.admin_user_id'
    when exists (select 1 from public.household_plan_bindings where owner_user_id = p_user_id)
      then 'household_plan_bindings'
    when exists (select 1 from public.household_plan_participants p join public.household_members m on m.id = p.membership_id where m.user_id = p_user_id)
      then 'household_plan_participants'
    when exists (select 1 from public.financial_plan_responsibilities r join public.household_members m on m.id = r.membership_id where m.user_id = p_user_id)
      then 'financial_plan_responsibilities'
    when exists (select 1 from public.financial_plan_links l join public.household_members m on m.id = l.contributor_membership_id where m.user_id = p_user_id)
      then 'financial_plan_links.contributor_membership_id'
    when exists (select 1 from public.financial_goal_allocation_revisions r join public.household_members m on m.id = r.contributor_membership_id where m.user_id = p_user_id)
      then 'financial_goal_allocation_revisions.contributor_membership_id'
    when exists (select 1 from public.financial_plan_links where activity_owner_id = p_user_id)
      then 'financial_plan_links.activity_owner_id'
    when exists (select 1 from public.household_plan_archived_claims where activity_owner_id = p_user_id)
      then 'household_plan_archived_claims'
    when exists (select 1 from public.household_plan_archived_activities where activity_owner_id = p_user_id)
      then 'household_plan_archived_activities'
    when exists (select 1 from public.financial_goal_allocation_revisions where account_owner_id = p_user_id)
      then 'financial_goal_allocation_revisions.account_owner_id'
    when exists (select 1 from public.financial_activity_memberships where record_owner_id = p_user_id and user_id <> p_user_id)
      then 'financial_activity_memberships.record_owner_id'
    when exists (select 1 from public.financial_activity_memberships where user_id = p_user_id and record_owner_id <> p_user_id)
      then 'retain_foreign_activity'
    when exists (select 1 from public.financial_record_revisions where reversal_of_owner_id = p_user_id and user_id <> p_user_id)
      then 'financial_record_revisions.reversal_of_owner_id'
    when exists (select 1 from public.financial_asset_changes where recorded_by = p_user_id and user_id <> p_user_id)
      then 'financial_asset_changes.recorded_by'
    else null end;
  if v_blocker is not null then
    raise exception 'account_deletion_blocker_left: %', v_blocker using errcode = '55000';
  end if;
end;
$$;

CREATE FUNCTION argus_private.deletion_hand_over_plans(p_user_id uuid, p_household_id uuid) RETURNS TABLE(binding_id uuid, new_owner_membership_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_binding record;
  v_successor record;
begin
  perform argus_private.require_deletion_writer();
  if current_user <> 'postgres' then
    raise exception 'account_deletion_writer_required' using errcode = '42501';
  end if;
  for v_binding in
    select b.id, b.kind
      from public.household_plan_bindings b
     where b.household_id = p_household_id and b.owner_user_id = p_user_id
       and b.revoked_at is null and b.departed_at is null
     order by b.id
     for update
  loop
    select p.membership_id, m.user_id into v_successor
      from public.household_plan_participants p
      join public.household_members m on m.id = p.membership_id
     where p.binding_id = v_binding.id and p.revoked_at is null
       and m.left_at is null and m.user_id <> p_user_id
     order by p.joined_at, p.membership_id
     limit 1;
    if not found then
      perform argus_private.deletion_drop_binding(v_binding.id, p_user_id);
    elsif v_binding.kind <> 'debt' then
      perform argus_private.deletion_rekey_binding(
        v_binding.id, p_user_id, v_successor.user_id, v_successor.membership_id
      );
      binding_id := v_binding.id;
      new_owner_membership_id := v_successor.membership_id;
      return next;
    end if;
  end loop;
  set constraints all immediate;
end;
$$;

CREATE FUNCTION argus_private.deletion_pass_on_archives(p_user_id uuid) RETURNS TABLE(binding_id uuid, new_owner_membership_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_binding record;
  v_successor record;
begin
  perform argus_private.require_deletion_writer();
  if current_user <> 'postgres' then
    raise exception 'account_deletion_writer_required' using errcode = '42501';
  end if;
  for v_binding in
    select b.id, b.kind, b.departed_at
      from public.household_plan_bindings b
     where b.owner_user_id = p_user_id and b.revoked_at is null
       and b.departed_at is not null and b.kind <> 'debt'
       and b.departed_at < now()
     order by b.id
     for update
  loop
    select p.membership_id, m.user_id into v_successor
      from public.household_plan_participants p
      join public.household_members m on m.id = p.membership_id
     where p.binding_id = v_binding.id
       and (p.revoked_at is null or p.revoked_at > v_binding.departed_at)
       and m.left_at is null and m.user_id <> p_user_id
     order by p.joined_at, p.membership_id
     limit 1;
    if not found then
      perform argus_private.deletion_drop_binding(v_binding.id, p_user_id);
    else
      perform argus_private.deletion_rekey_binding(
        v_binding.id, p_user_id, v_successor.user_id, v_successor.membership_id
      );
      binding_id := v_binding.id;
      new_owner_membership_id := v_successor.membership_id;
      return next;
    end if;
  end loop;
  set constraints all immediate;
end;
$$;

CREATE FUNCTION argus_private.deletion_place_unit(p_user_id uuid, p_unit_kind text, p_unit_id uuid, p_placeholder_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_binding public.household_plan_bindings%rowtype;
  v_member public.household_members%rowtype;
  v_placeholder_mid uuid;
  v_number integer;
  v_participant public.household_plan_participants%rowtype;
  v_debt_copy uuid;
  v_from uuid[];
  v_to uuid[];
  v_used boolean := false;
begin
  perform argus_private.require_deletion_writer();
  if current_user <> 'postgres' then
    raise exception 'account_deletion_writer_required' using errcode = '42501';
  end if;
  if not exists (select 1 from argus_private.account_placeholders where id = p_placeholder_id)
     or not exists (select 1 from auth.users where id = p_placeholder_id) then
    raise exception 'account_deletion_placeholder_missing' using errcode = 'P0002';
  end if;
  perform argus_private.defer_deletion_keys();

  -- One id map per placeholder for the whole transaction, shared by every
  -- kind: a single-leg activity has its record's id, so the copies must too.
  -- Two plans in one household that pin the same activity share one copy.
  create temp table if not exists deletion_id_map (placeholder_id uuid, old_id uuid, new_id uuid not null, primary key (placeholder_id, old_id)) on commit drop;
  create temp table if not exists deletion_copied (placeholder_id uuid, kind text, old_id uuid, primary key (placeholder_id, kind, old_id)) on commit drop;
  create temp table if not exists deletion_unit_ids (kind text, old_id uuid, primary key (kind, old_id)) on commit drop;
  create temp table if not exists deletion_fresh_ids (kind text, old_id uuid, primary key (kind, old_id)) on commit drop;
  truncate pg_temp.deletion_unit_ids, pg_temp.deletion_fresh_ids;

  if p_unit_kind = 'plan' then
    select * into v_binding from public.household_plan_bindings where id = p_unit_id for update;
    if not found then
      return false;
    end if;
    insert into pg_temp.deletion_unit_ids
    select 'activity', a from (
      select l.activity_id as a from public.financial_plan_links l
       where l.binding_id = p_unit_id and l.activity_owner_id = p_user_id
      union select activity_id from public.household_plan_archived_claims
       where binding_id = p_unit_id and activity_owner_id = p_user_id
      union select activity_id from public.household_plan_archived_activities
       where binding_id = p_unit_id and activity_owner_id = p_user_id
    ) s
    where argus_private.deletion_activity_household(a) = v_binding.household_id
    on conflict do nothing;
    insert into pg_temp.deletion_unit_ids
    select 'account', a from (
      select account_id as a from public.financial_goal_allocation_revisions
       where binding_id = p_unit_id and account_owner_id = p_user_id
      union
      select d.debt_account_id from public.financial_debt_plans d
       where v_binding.kind = 'debt' and v_binding.owner_user_id = p_user_id
         and d.id = v_binding.definition_id and d.user_id = p_user_id
    ) s
    where a is not null
    on conflict do nothing;
  elsif p_unit_kind = 'group' then
    if exists (select 1 from public.financial_activity_groups where id = p_unit_id and user_id = p_user_id) then
      insert into pg_temp.deletion_unit_ids values ('activity', p_unit_id) on conflict do nothing;
    else
      insert into pg_temp.deletion_unit_ids
      select distinct 'record', m.record_id from public.financial_activity_memberships m
       where m.activity_id = p_unit_id and m.record_owner_id = p_user_id
      on conflict do nothing;
    end if;
  else
    raise exception 'account_deletion_unit_invalid' using errcode = '22023';
  end if;

  -- The person's own legs in the copied activities, and the accounts they sit in.
  insert into pg_temp.deletion_unit_ids
  select distinct 'record', m.record_id from public.financial_activity_memberships m
   where m.activity_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'activity')
     and m.user_id = p_user_id and m.record_owner_id = p_user_id
  on conflict do nothing;
  insert into pg_temp.deletion_unit_ids
  select distinct 'account', r.account_id from public.financial_records r
   where r.id in (select old_id from pg_temp.deletion_unit_ids where kind = 'record')
  on conflict do nothing;

  -- Activities and records move in place: they keep their ids, revisions
  -- and timestamps, because other people's legs and links name them by id.
  -- Accounts are copied (new ids), since an account also holds rows that go
  -- with the person. An id map per placeholder covers the account copies for
  -- the whole transaction, so units of one scope share one copy.
  insert into pg_temp.deletion_id_map
  select distinct p_placeholder_id, old_id, gen_random_uuid() from pg_temp.deletion_unit_ids
   where kind = 'account'
  on conflict do nothing;
  insert into pg_temp.deletion_fresh_ids
  select u.kind, u.old_id from pg_temp.deletion_unit_ids u
   where u.kind = 'account' and not exists (
     select 1 from pg_temp.deletion_copied c
      where c.placeholder_id = p_placeholder_id and c.kind = u.kind and c.old_id = u.old_id);
  insert into pg_temp.deletion_copied select p_placeholder_id, kind, old_id from pg_temp.deletion_fresh_ids;

  select array_agg(old_id order by old_id), array_agg(new_id order by old_id)
    into v_from, v_to
    from (
      select old_id, new_id from pg_temp.deletion_id_map where placeholder_id = p_placeholder_id
      union all select p_user_id, p_placeholder_id
    ) ids;

  -- The copy below names its columns, so a Business account would silently
  -- become a Personal account of the placeholder.
  if exists (
    select 1 from public.financial_accounts a
      join pg_temp.deletion_unit_ids u on u.kind = 'account' and u.old_id = a.id
     where a.owner_space_id is not null
  ) then
    raise exception 'business_account_in_copy' using errcode = 'P0001';
  end if;

  insert into public.financial_accounts
      (id, user_id, space_id, type, currency, nickname, archived, ownership_share_bps, version, created_at, updated_at)
  select m.new_id, p_placeholder_id, a.space_id, a.type, a.currency, null, a.archived,
         a.ownership_share_bps, 1, a.created_at, now()
    from public.financial_accounts a
    join pg_temp.deletion_id_map m on m.placeholder_id = p_placeholder_id and m.old_id = a.id
    join pg_temp.deletion_fresh_ids f on f.kind = 'account' and f.old_id = a.id;

  -- The person's own receipts and import coverage on the moving rows go with
  -- them (their keys are not deferrable and name the person).
  delete from public.financial_activity_receipts
   where user_id = p_user_id
     and activity_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'activity');
  delete from public.financial_operation_receipts
   where user_id = p_user_id
     and record_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'record');
  delete from public.financial_observation_coverage
   where user_id = p_user_id
     and (activity_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'record')
          or observation_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'record'));

  update public.financial_activity_groups
     set user_id = p_placeholder_id
   where id in (select old_id from pg_temp.deletion_unit_ids where kind = 'activity')
     and user_id = p_user_id;
  update public.financial_activity_revisions
     set user_id = p_placeholder_id
   where activity_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'activity')
     and user_id = p_user_id;
  update public.financial_records r
     set user_id = p_placeholder_id, account_id = m.new_id
    from pg_temp.deletion_id_map m
   where r.id in (select old_id from pg_temp.deletion_unit_ids where kind = 'record')
     and r.user_id = p_user_id
     and m.placeholder_id = p_placeholder_id and m.old_id = r.account_id;
  -- Kept history holds amount, date, category and currency: notes, source ids
  -- and correction reasons are dropped and recorded_by cleared. purchase_* and
  -- reversal_* are generated from details; a link to one of the person's own
  -- activities that did not move with this placeholder is dropped.
  update public.financial_record_revisions rr
     set user_id = p_placeholder_id,
         recorded_by = null,
         reason = null,
         details = argus_private.deletion_rewrite_ids(
           (case when rr.details ? 'reversal_of_activity_id'
                      and coalesce((rr.details ->> 'reversal_of_owner_id')::uuid, rr.user_id) = p_user_id
                      and not exists (select 1 from public.financial_activity_groups g
                                       where g.id = (rr.details ->> 'reversal_of_activity_id')::uuid
                                         and g.user_id = p_placeholder_id)
                 then rr.details - 'reversal_of_activity_id' - 'reversal_of_revision' - 'reversal_of_owner_id'
                 else rr.details end)
           - (case when rr.details ? 'purchase_activity_id'
                        and not exists (select 1 from public.financial_activity_groups g
                                         where g.id = (rr.details ->> 'purchase_activity_id')::uuid
                                           and g.user_id = p_placeholder_id)
                   then array['purchase_activity_id', 'purchase_revision'] else array[]::text[] end)
           - 'note' - 'source_id',
           v_from, v_to)
   where rr.record_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'record')
     and rr.user_id = p_user_id;
  update public.financial_activity_memberships
     set user_id = p_placeholder_id
   where activity_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'activity')
     and user_id = p_user_id;
  update public.financial_activity_memberships
     set record_owner_id = p_placeholder_id
   where record_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'record')
     and record_owner_id = p_user_id;

  -- Every claim or archive on a moved activity, in any plan, follows it now:
  -- the activity's key holds it immediate at the end of this call. In another
  -- household's plan it is the read-only reference of decision c. The
  -- person's own personal claims on it go with them (5.3 deletes the rest).
  delete from public.financial_plan_links
   where binding_id is null and user_id = p_user_id
     and activity_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'activity');
  update public.financial_plan_links l
     set activity_owner_id = p_placeholder_id,
         attribution = argus_private.deletion_rewrite_ids(l.attribution, v_from, v_to)
   where l.binding_id is not null and l.binding_id is distinct from p_unit_id
     and l.activity_owner_id = p_user_id
     and l.activity_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'activity');
  update public.household_plan_archived_claims c
     set activity_owner_id = p_placeholder_id
   where c.binding_id is distinct from p_unit_id and c.activity_owner_id = p_user_id
     and c.activity_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'activity');
  update public.household_plan_archived_activities c
     set activity_owner_id = p_placeholder_id
   where c.binding_id is distinct from p_unit_id and c.activity_owner_id = p_user_id
     and c.activity_id in (select old_id from pg_temp.deletion_unit_ids where kind = 'activity');

  v_used := exists (select 1 from pg_temp.deletion_unit_ids);

  if p_unit_kind = 'plan' then
    -- Claims, archives and allocation history of this plan point at the copies.
    update public.financial_plan_links l
       set activity_owner_id = g.user_id
      from public.financial_activity_groups g
     where l.binding_id = p_unit_id and l.activity_owner_id = p_user_id
       and g.id = l.activity_id and g.user_id <> p_user_id;
    -- Every claim's accepted legs name accounts; the person's now have copies.
    update public.financial_plan_links l
       set attribution = argus_private.deletion_rewrite_ids(l.attribution, v_from, v_to)
     where l.binding_id = p_unit_id and l.attribution is not null;
    update public.household_plan_archived_claims c
       set activity_owner_id = g.user_id
      from public.financial_activity_groups g
     where c.binding_id = p_unit_id and c.activity_owner_id = p_user_id
       and g.id = c.activity_id and g.user_id <> p_user_id;
    update public.household_plan_archived_activities c
       set activity_owner_id = g.user_id
      from public.financial_activity_groups g
     where c.binding_id = p_unit_id and c.activity_owner_id = p_user_id
       and g.id = c.activity_id and g.user_id <> p_user_id;
    update public.financial_goal_allocation_revisions r
       set account_id = m.new_id, account_owner_id = p_placeholder_id
      from pg_temp.deletion_id_map m
     where m.placeholder_id = p_placeholder_id and r.binding_id = p_unit_id and r.account_owner_id = p_user_id and r.account_id = m.old_id;
    -- Live backing from the person's accounts ends; the archive keeps it.
    delete from public.financial_goal_allocations
     where binding_id = p_unit_id and account_owner_id = p_user_id;

    -- The household's one Exmiembro membership for this person, shared by
    -- every plan of theirs in the household. former_member_number orders the
    -- household's former members; plan reads number them per plan.
    select * into v_member from public.household_members
     where household_id = v_binding.household_id and user_id = p_user_id
     order by joined_at desc, id desc limit 1;
    if found then
      select id into v_placeholder_mid from public.household_members
       where household_id = v_binding.household_id and user_id = p_placeholder_id;
      if v_placeholder_mid is null then
        select coalesce(max(former_member_number), 0) + 1 into v_number
          from public.household_members
         where household_id = v_binding.household_id and former_member_number is not null;
        v_placeholder_mid := gen_random_uuid();
        insert into public.household_members
            (id, household_id, user_id, joined_at, left_at, display_name, former_member_number)
        values (v_placeholder_mid, v_binding.household_id, p_placeholder_id, v_member.joined_at,
                coalesce(v_member.left_at, now()), 'Exmiembro', v_number);
      end if;
      select * into v_participant from public.household_plan_participants
       where binding_id = p_unit_id
         and membership_id in (select id from public.household_members
                                where household_id = v_binding.household_id and user_id = p_user_id)
       order by joined_at limit 1;
      insert into public.household_plan_participants
          (binding_id, household_id, membership_id, permission, revoked_at, granted_revision, joined_at)
      values (p_unit_id, v_binding.household_id, v_placeholder_mid,
              coalesce(v_participant.permission, 'view'),
              coalesce(v_participant.revoked_at, now()),
              coalesce(v_participant.granted_revision, v_binding.first_shared_revision),
              coalesce(v_participant.joined_at, v_member.joined_at));
      delete from public.household_plan_participants
       where binding_id = p_unit_id
         and membership_id in (select id from public.household_members
                                where household_id = v_binding.household_id and user_id = p_user_id);
      update public.financial_plan_links
         set contributor_membership_id = v_placeholder_mid
       where binding_id = p_unit_id
         and contributor_membership_id in (select id from public.household_members where user_id = p_user_id);
      update public.financial_goal_allocations
         set contributor_membership_id = v_placeholder_mid
       where binding_id = p_unit_id
         and contributor_membership_id in (select id from public.household_members where user_id = p_user_id);
      update public.financial_goal_allocation_revisions
         set contributor_membership_id = v_placeholder_mid
       where binding_id = p_unit_id
         and contributor_membership_id in (select id from public.household_members where user_id = p_user_id);
      update public.financial_plan_responsibilities r
         set membership_id = v_placeholder_mid
       where r.kind = v_binding.kind and r.definition_id = v_binding.definition_id
         and r.owner_id = v_binding.owner_user_id
         and r.membership_id in (select id from public.household_members where user_id = p_user_id);
      delete from public.household_plan_receipts
       where binding_id = p_unit_id
         and (actor_id = p_user_id
              or membership_id in (select id from public.household_members where user_id = p_user_id));
      v_used := true;

      -- A read-only archive the person still owns (shared debt plans, Lucas,
      -- Oct 2) moves to this placeholder together with its debt account.
      if v_binding.owner_user_id = p_user_id then
        if v_binding.kind = 'debt' then
          select m.new_id into v_debt_copy
            from public.financial_debt_plans d
            join pg_temp.deletion_id_map m
              on m.placeholder_id = p_placeholder_id and m.old_id = d.debt_account_id
           where d.id = v_binding.definition_id and d.user_id = p_user_id;
        end if;
        perform argus_private.deletion_rekey_binding(
          p_unit_id, p_user_id, p_placeholder_id, v_placeholder_mid, v_debt_copy
        );
      end if;
    end if;
  end if;

  set constraints all immediate;
  return v_used;
end;
$$;

CREATE FUNCTION argus_private.deletion_placeholder_units(p_user_id uuid) RETURNS TABLE(unit_kind text, unit_id uuid, scope_kind text, scope_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with mids as (
    select id from public.household_members where user_id = p_user_id
  ),
  plans as (
    select l.binding_id as id from public.financial_plan_links l
     where l.binding_id is not null
       and (l.activity_owner_id = p_user_id or l.contributor_membership_id in (select id from mids))
    union select binding_id from public.household_plan_archived_claims where activity_owner_id = p_user_id
    union select binding_id from public.household_plan_archived_activities where activity_owner_id = p_user_id
    union select binding_id from public.financial_goal_allocation_revisions
     where binding_id is not null
       and (account_owner_id = p_user_id or contributor_membership_id in (select id from mids))
    union select binding_id from public.household_plan_participants where membership_id in (select id from mids)
    union select b.id from public.household_plan_bindings b
     where b.revoked_at is null and exists (
       select 1 from public.financial_plan_responsibilities r
        where r.kind = b.kind and r.definition_id = b.definition_id
          and r.owner_id = b.owner_user_id and r.membership_id in (select id from mids))
    union select id from public.household_plan_bindings
     where owner_user_id = p_user_id and revoked_at is null and kind = 'debt'
  ),
  planned as (
    select l.activity_id from public.financial_plan_links l
     where l.activity_owner_id = p_user_id and l.binding_id in (select id from plans)
    union select activity_id from public.household_plan_archived_claims where activity_owner_id = p_user_id
    union select activity_id from public.household_plan_archived_activities where activity_owner_id = p_user_id
  ),
  groups as (
    select m.activity_id as id from public.financial_activity_memberships m
     where m.user_id = p_user_id and m.record_owner_id <> p_user_id
       and m.activity_id not in (select activity_id from planned)
    union
    select m.activity_id from public.financial_activity_memberships m
     where m.user_id <> p_user_id and m.record_owner_id = p_user_id
  )
  select 'plan'::text, p.id, 'household'::text, b.household_id
    from plans p join public.household_plan_bindings b on b.id = p.id
  union all
  -- A group a household plan claims or archives belongs to the scope of the
  -- household that claimed it first (decision c; the plan's link names its
  -- legs and accounts); any other group is shared outside a plan and is its
  -- own scope.
  select 'group'::text, g.id,
         case when h.household_id is null then 'group' else 'household' end,
         coalesce(h.household_id, g.id)
    from groups g
    cross join lateral (
      select argus_private.deletion_activity_household(g.id) as household_id
    ) h;
$$;

CREATE FUNCTION argus_private.deletion_rekey_binding(p_binding_id uuid, p_from uuid, p_to uuid, p_to_membership_id uuid, p_debt_account_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_binding public.household_plan_bindings%rowtype;
begin
  perform argus_private.require_deletion_writer();
  if current_user <> 'postgres' then
    raise exception 'account_deletion_writer_required' using errcode = '42501';
  end if;
  select * into v_binding
    from public.household_plan_bindings
   where id = p_binding_id and owner_user_id = p_from
   for update;
  if not found then
    raise exception 'account_deletion_binding_not_found' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.household_plan_bindings
     where kind = v_binding.kind and definition_id = v_binding.definition_id
       and owner_user_id = p_from and id <> p_binding_id and revoked_at is null
  ) then
    raise exception 'account_deletion_definition_bound_twice' using errcode = '55000';
  end if;
  perform argus_private.defer_deletion_keys();
  -- The binding moves first: the claim and allocation triggers check every
  -- moved row against the binding's owner.
  update public.household_plan_bindings
     set owner_user_id = p_to, owner_membership_id = p_to_membership_id
   where id = p_binding_id;

  if v_binding.kind = 'budget' then
    update public.financial_budgets set user_id = p_to where id = v_binding.definition_id and user_id = p_from;
    update public.financial_plan_links set user_id = p_to where budget_id = v_binding.definition_id and user_id = p_from;
  elsif v_binding.kind = 'bill' then
    update public.financial_expectations set user_id = p_to where id = v_binding.definition_id and user_id = p_from;
    update public.financial_plan_links set user_id = p_to where expectation_id = v_binding.definition_id and user_id = p_from;
  elsif v_binding.kind = 'goal' then
    update public.financial_goals set user_id = p_to where id = v_binding.definition_id and user_id = p_from;
    update public.financial_plan_links set user_id = p_to where goal_id = v_binding.definition_id and user_id = p_from;
  elsif v_binding.kind = 'debt' then
    -- financial_debt_plans cascades from its owner's debt account, so a debt
    -- plan moves together with that account (or the account's placeholder copy).
    update public.financial_debt_plans
       set user_id = p_to,
           debt_account_id = coalesce(p_debt_account_id, debt_account_id),
           body = case when p_debt_account_id is null then body
                       else jsonb_set(body, '{debt_account_id}', to_jsonb(p_debt_account_id::text)) end
     where id = v_binding.definition_id and user_id = p_from;
    update public.financial_plan_links set user_id = p_to where debt_plan_id = v_binding.definition_id and user_id = p_from;
  end if;
  update public.financial_plan_definition_revisions
     set owner_id = p_to,
         body = case when v_binding.kind = 'debt' and p_debt_account_id is not null and body ? 'debt_account_id'
                     then jsonb_set(body, '{debt_account_id}', to_jsonb(p_debt_account_id::text))
                     else body end
   where kind = v_binding.kind and definition_id = v_binding.definition_id and owner_id = p_from;
  update public.financial_plan_responsibilities
     set owner_id = p_to
   where kind = v_binding.kind and definition_id = v_binding.definition_id and owner_id = p_from;
  update public.financial_plan_links set user_id = p_to where binding_id = p_binding_id and user_id = p_from;
  if v_binding.kind = 'goal' then
    update public.financial_goal_allocations
       set goal_owner_id = p_to
     where goal_id = v_binding.definition_id and goal_owner_id = p_from;
    update public.financial_goal_allocation_revisions
       set goal_owner_id = p_to
     where goal_id = v_binding.definition_id and goal_owner_id = p_from;
  end if;
  -- The new owner is no longer a participant of their own plan.
  delete from public.household_plan_participants
   where binding_id = p_binding_id and membership_id = p_to_membership_id;
end;
$$;

CREATE FUNCTION argus_private.deletion_rewrite_ids(p_doc jsonb, p_from uuid[], p_to uuid[]) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_text text := p_doc::text;
  i integer;
begin
  if p_doc is null or p_from is null then
    return p_doc;
  end if;
  for i in 1 .. coalesce(array_length(p_from, 1), 0) loop
    v_text := replace(v_text, p_from[i]::text, p_to[i]::text);
  end loop;
  return v_text::jsonb;
end;
$$;

CREATE FUNCTION argus_private.enforce_registered_memory_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new.owner_id is distinct from old.owner_id then
    raise exception 'personalization memory owner is immutable'
      using errcode = '23514';
  end if;

  if not argus_private.is_registered_memory_owner(new.owner_id) then
    raise exception
      'personalization memory requires a registered owner without an active Guest workspace'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION argus_private.fill_sender_link_space() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  new.destination_space_id := coalesce(
    new.destination_space_id, public.business_space_of(new.destination_owner_id)
  );
  if new.destination_space_id is null then
    raise exception 'business_space_missing' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.finalize_linked_guest_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce(new.is_anonymous, false) is false
     and nullif(btrim(new.email), '') is not null
     and exists (
       select 1
         from public.guest_workspaces
        where user_id = new.id
          and status in ('active', 'claiming')
     ) then
    update public.profiles
       set email = lower(btrim(new.email)),
           updated_at = now()
     where id = new.id;

    update public.guest_workspaces
       set status = 'claimed',
           claimed_by = new.id,
           claimed_at = coalesce(claimed_at, now()),
           updated_at = now()
     where user_id = new.id
       and status in ('active', 'claiming');
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.financial_activity_is_personal(p_activity_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    select not exists (
        select 1 from public.financial_activity_memberships m
        join public.financial_records r on r.id = m.record_id
        left join public.financial_accounts a on a.id = r.account_id
        where m.activity_id = p_activity_id
          and (r.owner_space_id is not null or a.owner_space_id is not null)
    );
$$;

CREATE FUNCTION argus_private.forget_invite_party(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ref uuid;
begin
  if p_user_id is null then
    raise exception 'account_deletion_user_required' using errcode = '22023';
  end if;
  select ref into v_ref from public.invite_sender_refs where user_id = p_user_id;
  update public.invite_referrals
     set sender_ref = gen_random_uuid()  -- volatile: a new value for each row
   where sender_user_id = p_user_id
      or (v_ref is not null and sender_ref = v_ref);
  update public.invite_referrals set sender_user_id = null where sender_user_id = p_user_id;
  update public.invite_referrals set acceptor_user_id = null where acceptor_user_id = p_user_id;
  delete from public.invite_sender_refs where user_id = p_user_id;
  update public.beta_invitations
     set revoked_at = now()
   where created_by = p_user_id
     and kind = 'beta'
     and revoked_at is null
     and use_count < max_uses;
  update public.beta_invitations set created_by = null where created_by = p_user_id;
  update public.beta_invite_quota_grants set granted_by = null where granted_by = p_user_id;
  update public.household_invitations set created_by = null where created_by = p_user_id;
  update public.household_invitations set accepted_by = null where accepted_by = p_user_id;
end;
$$;

CREATE FUNCTION argus_private.freeze_business_email_destination() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if (new.space_id, new.principal_id, new.grant_id) is distinct from
       (old.space_id, old.principal_id, old.grant_id) then
        raise exception 'email_route_destination_immutable';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.guard_guest_memory_zero_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_memory_state_count bigint;
begin
  if old.status not in ('active', 'claiming')
     or new.status <> 'claimed' then
    return new;
  end if;

  select count(*)
    into v_memory_state_count
    from (
      select owner_id
        from public.memory_settings
       where owner_id = new.user_id
      union all
      select owner_id
        from public.memory_candidates
       where owner_id = new.user_id
      union all
      select owner_id
        from public.memory_consent_actions
       where owner_id = new.user_id
      union all
      select owner_id
        from public.memory_records
       where owner_id = new.user_id
      union all
      select owner_id
        from public.memory_provenance
       where owner_id = new.user_id
      union all
      select owner_id
        from public.memory_prompt_history
       where owner_id = new.user_id
      union all
      select owner_id
        from public.memory_reconciliations
       where owner_id = new.user_id
      union all
      select owner_id
        from public.memory_provider_projections
       where owner_id = new.user_id
      union all
      select owner_id
        from public.memory_provider_cleanup
       where owner_id = new.user_id
    ) as memory_state;

  if v_memory_state_count <> 0 then
    raise exception 'Guest personalization memory state must be zero before claim'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION argus_private.guard_locked_owner_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(current_setting('argus.locked_history_writer', true), '') <> 'deletion'
     or current_user <> 'postgres' then
    raise exception 'locked_history_owner_columns: %', TG_TABLE_NAME using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.guard_memory_record_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op <> 'DELETE'
     or tg_table_schema <> 'public'
     or tg_table_name <> 'memory_records' then
    raise exception
      'unsupported memory record delete target: %.% %',
      tg_table_schema,
      tg_table_name,
      tg_op
      using errcode = '23514';
  end if;

  if exists (
    select 1
      from public.profiles
     where id = old.owner_id
  )
  and exists (
    select 1
      from public.memory_reconciliations
     where owner_id = old.owner_id
       and record_id = old.id
       and status in ('pending', 'running')
  ) then
    raise exception
      'memory record deletion requires unfinished provider reconciliation to complete'
      using errcode = '23514';
  end if;

  return old;
end;
$$;

CREATE FUNCTION argus_private.is_account_placeholder(p_id uuid, p_app_metadata jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(p_app_metadata ->> 'placeholder', '') = 'true'
      or exists (select 1 from argus_private.account_placeholders t where t.id = p_id);
$$;

CREATE FUNCTION argus_private.is_registered_memory_owner(p_owner_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from auth.users as auth_user
     where auth_user.id = p_owner_id
       and coalesce(auth_user.is_anonymous, true) is false
  )
  and not exists (
    select 1
      from public.guest_workspaces as workspace
     where workspace.user_id = p_owner_id
       and workspace.status in ('active', 'claiming')
  );
$$;

CREATE FUNCTION argus_private.lock_memory_record_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner_id uuid;
  v_record_id text;
begin
  if tg_table_schema = 'public'
     and tg_table_name = 'memory_records'
     and tg_op = 'INSERT' then
    v_owner_id := new.owner_id;
    v_record_id := new.id;
  elsif tg_table_schema = 'public'
        and tg_table_name = 'memory_records'
        and tg_op = 'DELETE' then
    if not exists (
      select 1
        from public.profiles
       where id = old.owner_id
    ) then
      return old;
    end if;
    v_owner_id := old.owner_id;
    v_record_id := old.id;
  elsif tg_table_schema = 'public'
        and tg_table_name = 'memory_reconciliations'
        and tg_op in ('INSERT', 'UPDATE') then
    v_owner_id := new.owner_id;
    v_record_id := new.record_id;
  else
    raise exception
      'unsupported memory record lifecycle target: %.% %',
      tg_table_schema,
      tg_table_name,
      tg_op
      using errcode = '23514';
  end if;

  if tg_table_name = 'memory_reconciliations' then
    if new.operation = 'reset' then
      perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'argus:memory-owner:' || v_owner_id::text,
          0
        )
      );
      return new;
    end if;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'argus:memory-record:'
      || v_owner_id::text
      || ':'
      || v_record_id,
      0
    )
  );

  if tg_table_name = 'memory_records'
     and tg_op = 'INSERT'
     and exists (
       select 1
         from public.memory_reconciliations
        where owner_id = v_owner_id
          and record_id = v_record_id
          and operation = 'delete'
     ) then
    raise exception
      'memory record insert rejected by existing delete reconciliation'
      using errcode = '23514';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.memory_categories_are_valid(p_categories text[], p_require_nonempty boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    (not p_require_nonempty or cardinality(p_categories) > 0)
    and cardinality(p_categories) <= 4
    and cardinality(p_categories) = (
      select count(distinct category)::integer
        from pg_catalog.unnest(p_categories) as category
    )
    and coalesce(
      (
        select bool_and(
          category in (
            'personalization_preference',
            'workflow_preference',
            'explicit_decision_note',
            'past_session_anchor'
          )
        )
          from pg_catalog.unnest(p_categories) as category
      ),
      true
    );
$$;

CREATE FUNCTION argus_private.memory_sensitivity_flags_are_valid(p_flags text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select
    cardinality(p_flags) <= 10
    and cardinality(p_flags) = (
      select count(distinct flag)::integer
        from pg_catalog.unnest(p_flags) as flag
    )
    and coalesce(
      (
        select bool_and(
          flag in (
            'broker_credential',
            'account_balance',
            'exact_holdings',
            'tax_or_legal_status',
            'identifying_financial_detail',
            'health',
            'employment',
            'family',
            'raw_conversation'
          )
        )
          from pg_catalog.unnest(p_flags) as flag
      ),
      true
    );
$$;

CREATE FUNCTION argus_private.prepare_guest_workspace_handoff(p_source_user_id uuid, p_destination_email_hash text, p_source_conversation_id uuid, p_pending_action jsonb, p_secret_hash text, p_existing_secret_hash text DEFAULT NULL::text, p_handoff_kind text DEFAULT 'existing_account'::text) RETURNS TABLE(id uuid, expires_at timestamp with time zone, destination_user_id uuid, reused_secret boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
#variable_conflict use_column
declare
  v_handoff public.guest_workspace_handoffs%rowtype;
  v_workspace public.guest_workspaces%rowtype;
  v_source_is_anonymous boolean;
  v_expires_at timestamptz;
  v_reused_secret boolean := false;
begin
  if p_handoff_kind not in ('existing_account', 'new_account_signup')
     or p_destination_email_hash !~ '^[0-9a-f]{64}$'
     or p_secret_hash !~ '^[0-9a-f]{64}$'
     or (
       p_existing_secret_hash is not null
       and p_existing_secret_hash !~ '^[0-9a-f]{64}$'
     ) then
    raise exception 'guest_handoff_invalid' using errcode = '22023';
  end if;

  -- Serialize every preparation for one source before taking row locks. Claim
  -- takes the handoff then workspace locks in the same order.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('guest-handoff:' || p_source_user_id::text, 0)
  );

  select *
    into v_handoff
    from public.guest_workspace_handoffs
   where source_user_id = p_source_user_id
     and status = 'pending'
   for update;

  select coalesce(is_anonymous, false)
    into v_source_is_anonymous
    from auth.users
   where auth.users.id = p_source_user_id
   for update;
  if not found or v_source_is_anonymous is not true then
    raise exception 'guest_handoff_source_not_anonymous' using errcode = 'P0001';
  end if;

  select *
    into v_workspace
    from public.guest_workspaces
   where user_id = p_source_user_id
   for update;
  if not found
     or v_workspace.status <> 'active'
     or v_workspace.expires_at <= now()
     or v_workspace.conversation_id is distinct from p_source_conversation_id
     or not exists (
       select 1
         from public.conversations
        where conversations.id = p_source_conversation_id
          and conversations.user_id = p_source_user_id
     ) then
    raise exception 'guest_handoff_workspace_unavailable' using errcode = 'P0001';
  end if;

  if p_pending_action is not null
     and not argus_private.valid_guest_pending_action(
       p_pending_action,
       p_source_conversation_id
     ) then
    raise exception 'guest_handoff_invalid' using errcode = '22023';
  end if;

  if v_handoff.id is not null then
    if v_handoff.handoff_kind = 'new_account_signup'
       and v_handoff.destination_user_id is not null
       and v_handoff.destination_email_hash is distinct from p_destination_email_hash then
      raise exception 'guest_signup_destination_bound' using errcode = 'P0001';
    end if;

    -- Once signup has created an Auth user, the person's later password login
    -- must reuse this bound ticket. The browser cannot inspect the HttpOnly
    -- cookie to know that its ordinary login preparation is a continuation.
    if v_handoff.handoff_kind = 'new_account_signup'
       and v_handoff.destination_email_hash is not distinct from p_destination_email_hash
       and (
         p_handoff_kind = 'new_account_signup'
         or v_handoff.destination_user_id is not null
       ) then
      v_reused_secret := p_existing_secret_hash is not null
        and v_handoff.secret_hash is not distinct from p_existing_secret_hash;
      update public.guest_workspace_handoffs
         set secret_hash = case
               when v_reused_secret then secret_hash
               else p_secret_hash
             end,
             source_conversation_id = p_source_conversation_id,
             pending_action = p_pending_action,
             expires_at = v_workspace.expires_at
       where guest_workspace_handoffs.id = v_handoff.id
       returning * into v_handoff;

      return query
      select
        v_handoff.id,
        v_handoff.expires_at,
        v_handoff.destination_user_id,
        v_reused_secret;
      return;
    end if;

    update public.guest_workspace_handoffs
       set status = 'revoked'
     where guest_workspace_handoffs.id = v_handoff.id;
  end if;

  v_expires_at := case
    when p_handoff_kind = 'new_account_signup' then v_workspace.expires_at
    else now() + interval '10 minutes'
  end;

  insert into public.guest_workspace_handoffs (
    secret_hash,
    source_user_id,
    destination_email_hash,
    destination_user_id,
    source_conversation_id,
    pending_action,
    handoff_kind,
    created_at,
    expires_at
  ) values (
    p_secret_hash,
    p_source_user_id,
    p_destination_email_hash,
    null,
    p_source_conversation_id,
    p_pending_action,
    p_handoff_kind,
    now(),
    v_expires_at
  )
  returning * into v_handoff;

  return query
  select
    v_handoff.id,
    v_handoff.expires_at,
    v_handoff.destination_user_id,
    false;
end;
$_$;

CREATE FUNCTION argus_private.protect_memory_child_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'memory_prompt_history' then
    if new.owner_id is distinct from old.owner_id
       or new.category is distinct from old.category then
      raise exception '% identity is immutable', tg_table_name
        using errcode = '23514';
    end if;
  elsif tg_table_name = 'memory_reconciliations' then
    if new.owner_id is distinct from old.owner_id
       or new.record_id is distinct from old.record_id
       or new.generation is distinct from old.generation then
      raise exception '% identity is immutable', tg_table_name
        using errcode = '23514';
    end if;
  elsif tg_table_name = 'memory_provider_projections' then
    if new.owner_id is distinct from old.owner_id
       or new.record_id is distinct from old.record_id then
      raise exception '% identity is immutable', tg_table_name
        using errcode = '23514';
    end if;
  elsif tg_table_name = 'memory_provider_cleanup' then
    if new.owner_id is distinct from old.owner_id
       or new.record_id is distinct from old.record_id
       or new.provider_ref is distinct from old.provider_ref
       or new.generation is distinct from old.generation
       or new.created_at is distinct from old.created_at then
      raise exception '% identity is immutable', tg_table_name
        using errcode = '23514';
    end if;
  else
    raise exception 'unsupported memory child table: %', tg_table_name
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION argus_private.protect_memory_provider_cleanup_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'pending' or new.resolved_at is not null then
      raise exception 'memory provider cleanup must begin pending'
        using errcode = '23514';
    end if;
    return new;
  end if;

  if old.status = 'resolved'
     and (
       new.status is distinct from old.status
       or new.resolved_at is distinct from old.resolved_at
     ) then
    raise exception 'memory provider cleanup terminal state is immutable'
      using errcode = '23514';
  end if;
  if old.status = 'pending'
     and not (
       (
         new.status = 'pending'
         and new.resolved_at is null
       )
       or (
         new.status = 'resolved'
         and new.resolved_at is not null
       )
     ) then
    raise exception 'memory provider cleanup transition is invalid'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION argus_private.protect_memory_record_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.id is distinct from old.id
     or new.owner_id is distinct from old.owner_id
     or new.candidate_id is distinct from old.candidate_id
     or new.consent_action_id is distinct from old.consent_action_id
     or new.category is distinct from old.category
     or new.created_at is distinct from old.created_at then
    raise exception 'memory record identity and consent are immutable'
      using errcode = '23514';
  end if;

  if new.label is not distinct from old.label
     and new.value is not distinct from old.value then
    raise exception 'memory record edit requires a label or value change'
      using errcode = '23514';
  end if;
  if new.revision <> old.revision + 1
     or new.updated_at <= old.updated_at then
    raise exception 'memory record edits require the next revision and update time'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION argus_private.refuse_business_account_grant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.financial_accounts a
     where a.id = new.account_id and a.owner_space_id is not null
  ) then
    raise exception 'business_account_not_shareable' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.refuse_placeholder_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (select 1 from argus_private.account_placeholders where id = new.id) then
    raise exception 'placeholder_domain_reserved' using errcode = '42501';
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.reject_immutable_memory_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception '% is immutable', tg_table_name
    using errcode = '23514';
end;
$$;

CREATE FUNCTION argus_private.reject_retired_recipient() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if exists (
        select 1 from public.business_email_retired_aliases
        where recipient = new.recipient
    ) then
        raise exception 'email_alias_retired';
    end if;
    if new.alias_normalized is not null and exists (
        select 1 from public.business_email_retired_aliases
        where alias_normalized = new.alias_normalized
    ) then
        raise exception 'email_alias_retired';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.require_deletion_writer() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(current_setting('argus.locked_history_writer', true), '') <> 'deletion'
     or current_user <> 'postgres' then
    raise exception 'account_deletion_writer_required' using errcode = '42501';
  end if;
end;
$$;

CREATE FUNCTION argus_private.require_import_observation_same_space() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select c.owner_space_id from public.financial_source_connections c
       where c.id = new.connection_id)
     is distinct from
     (select e.owner_space_id from public.financial_import_events e
       where e.id = new.event_id and e.user_id = new.user_id) then
    raise exception 'import_observation_space_mismatch' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.require_whatsapp_capture_same_space() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
      from public.financial_source_connections c
      join public.whatsapp_sender_links l
        on l.destination_owner_id = c.user_id
       and l.destination_space_id = c.owner_space_id
       and l.status = 'active'
     where c.id = new.connection_id
       and c.user_id = new.destination_owner_id
       and (
         (tg_op = 'UPDATE' and old.connection_id is not distinct from new.connection_id)
         or l.wa_id_hash = new.sender_hash
       )
  ) then
    raise exception 'whatsapp_capture_space_mismatch' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.reserve_deleted_route_alias() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    insert into public.business_email_retired_aliases (alias_normalized, recipient)
    values (old.alias_normalized, old.recipient)
    on conflict do nothing;
    return old;
end;
$$;

CREATE FUNCTION argus_private.reserve_memory_provider_ref() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner_id uuid;
  v_provider_ref text;
  v_provider_refs text[];
begin
  if tg_table_name = 'memory_provider_projections' then
    v_owner_id := new.owner_id;
    v_provider_refs := array[new.provider_ref];
    if tg_op = 'UPDATE' then
      v_provider_refs := array_append(v_provider_refs, old.provider_ref);
    end if;
  elsif tg_table_name = 'memory_provider_cleanup' then
    v_owner_id := new.owner_id;
    v_provider_refs := array[new.provider_ref];
  else
    raise exception 'unsupported memory provider reservation table: %',
      tg_table_name
      using errcode = '23514';
  end if;

  for v_provider_ref in
    select distinct ref
      from unnest(v_provider_refs) as provider_refs(ref)
     order by ref
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'argus:memory-provider-ref:' || v_owner_id::text || ':' || v_provider_ref,
        0
      )
    );
  end loop;

  if tg_table_name = 'memory_provider_projections'
     and exists (
       select 1
         from public.memory_provider_cleanup
        where owner_id = new.owner_id
          and provider_ref = new.provider_ref
          and status = 'pending'
     ) then
    raise exception 'memory provider ref is reserved for pending cleanup'
      using errcode = '23514';
  end if;

  if tg_table_name = 'memory_provider_cleanup'
     and tg_op = 'INSERT'
     and exists (
       select 1
         from public.memory_provider_projections
        where owner_id = new.owner_id
          and provider_ref = new.provider_ref
          and record_id <> new.record_id
     ) then
    raise exception 'memory provider ref belongs to a different live record'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION argus_private.reset_plan_participant_seniority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.granted_revision is distinct from old.granted_revision
     or (old.revoked_at is not null and new.revoked_at is null) then
    new.joined_at := now();
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.stamp_archived_claim_created_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.claim_created_at is null then
    select l.created_at into new.claim_created_at
      from public.financial_plan_links l
     where l.binding_id = new.binding_id and l.claim_id = new.claim_id
     limit 1;
    new.claim_created_at := coalesce(new.claim_created_at, now());
  end if;
  return new;
end;
$$;

CREATE FUNCTION argus_private.tombstone_business_email_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
    update public.business_email_deliveries
    set state = 'rejected', error_code = 'email_source_deleted',
        subject = null, sender = null, sent_at = null, text_body = null,
        lease_token = null, lease_until = null, updated_at = now()
    where original_document_id = old.id;
    update public.business_email_parts
    set state = 'rejected', error_code = 'email_source_deleted',
        filename = 'deleted', media_type = 'application/octet-stream'
    where document_id = old.id;
    return old;
end;
$$;

CREATE FUNCTION argus_private.valid_guest_pending_action(p_action jsonb, p_conversation_id uuid) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
declare v_key text; v_reason text;
begin
  if jsonb_typeof(p_action) <> 'object' then return false; end if;
  for v_key in select jsonb_object_keys(p_action) loop
    if v_key not in ('reason', 'conversation_id', 'action_id', 'artifact_id', 'message_id') or jsonb_typeof(p_action -> v_key) <> 'string' then
      return false;
    end if;
  end loop;
  v_reason := p_action ->> 'reason';
  if v_reason is null or v_reason not in ('second_simulation', 'simulation_limit', 'message_limit', 'save_decision', 'new_conversation', 'keep_history', 'discovery_searches', 'share_result') then return false; end if;
  if nullif(p_action ->> 'conversation_id', '') is distinct from p_conversation_id::text
     or nullif(p_action ->> 'action_id', '') is null then return false; end if;
  if v_reason = 'save_decision' then
    if nullif(p_action ->> 'artifact_id', '') is null then return false; end if;
  elsif p_action ? 'artifact_id' then
    return false;
  end if;
  if v_reason = 'share_result' then
    if nullif(p_action ->> 'message_id', '') is null then return false; end if;
  elsif p_action ? 'message_id' then
    return false;
  end if;
  return true;
end;
$$;

CREATE FUNCTION argus_private.validate_memory_consent_action() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_candidate_category text;
begin
  if new.action <> 'candidate_confirmation' then
    return new;
  end if;

  select category
    into v_candidate_category
    from public.memory_candidates
   where owner_id = new.owner_id
     and id = new.candidate_id;

  if not found then
    raise exception
      'candidate confirmation requires an existing same-owner candidate'
      using errcode = '23514';
  end if;

  if not (v_candidate_category = any(new.requested_scope)) then
    raise exception 'candidate category must be in requested scope'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION argus_private.validate_memory_reconciliation_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_record_exists boolean;
begin
  if tg_table_schema <> 'public'
     or tg_table_name <> 'memory_reconciliations'
     or tg_op not in ('INSERT', 'UPDATE') then
    raise exception
      'unsupported reconciliation lifecycle target: %.% %',
      tg_table_schema,
      tg_table_name,
      tg_op
      using errcode = '23514';
  end if;

  if new.operation not in ('create', 'update', 'delete', 'reset') then
    raise exception 'unsupported reconciliation operation: %', new.operation
      using errcode = '23514';
  end if;
  if new.status not in ('pending', 'running', 'succeeded', 'failed') then
    raise exception 'unsupported reconciliation status: %', new.status
      using errcode = '23514';
  end if;
  if (
    new.status in ('pending', 'running')
    and new.completed_at is not null
  )
  or (
    new.status in ('succeeded', 'failed')
    and new.completed_at is null
  ) then
    raise exception 'invalid reconciliation state for status %', new.status
      using errcode = '23514';
  end if;
  if tg_op = 'UPDATE'
     and new.operation is distinct from old.operation then
    raise exception 'memory reconciliation operation is immutable'
      using errcode = '23514';
  end if;

  if (
    new.operation = 'reset'
    and new.record_id <> ''
  )
  or (
    new.operation <> 'reset'
    and length(new.record_id) not between 1 and 128
  ) then
    raise exception 'invalid reconciliation operation and record shape'
      using errcode = '23514';
  end if;
  if new.operation <> 'reset'
     and new.status = 'running'
     and exists (
       select 1
         from public.memory_reconciliations
        where owner_id = new.owner_id
          and operation = 'reset'
     ) then
    raise exception
      'memory provider work is blocked by unresolved owner reset'
      using errcode = '23514';
  end if;
  if tg_op = 'UPDATE'
     and new.created_at is distinct from old.created_at then
    raise exception 'memory reconciliation creation time is immutable'
      using errcode = '23514';
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'pending'
       or new.claim_token is not null
       or new.lease_expires_at is not null
       or new.attempt_count <> 0
       or new.error_code is not null
       or new.completed_at is not null then
      raise exception 'invalid reconciliation insert transition'
        using errcode = '23514';
    end if;
  elsif old.status = 'pending' and new.status = 'running' then
    if new.claim_token is null
       or new.lease_expires_at is null
       or new.lease_expires_at <= statement_timestamp()
       or new.attempt_count <> old.attempt_count + 1
       or new.error_code is not null
       or new.completed_at is not null then
      raise exception 'running reconciliation requires a fresh claim'
        using errcode = '23514';
    end if;
  elsif old.status = 'running' and new.status = 'running' then
    if old.lease_expires_at is null
       or old.lease_expires_at > statement_timestamp()
       or new.claim_token is null
       or new.claim_token is not distinct from old.claim_token
       or new.lease_expires_at is null
       or new.lease_expires_at <= statement_timestamp()
       or new.attempt_count <> old.attempt_count + 1
       or new.error_code is not null
       or new.completed_at is not null then
      raise exception 'running reconciliation lease is not reclaimable'
        using errcode = '23514';
    end if;
  elsif old.status = 'running'
        and new.status in ('succeeded', 'failed') then
    if old.lease_expires_at is null
       or new.completed_at is null
       or old.lease_expires_at <= statement_timestamp() then
      raise exception 'expired reconciliation claim cannot finish'
        using errcode = '23514';
    end if;
    if new.claim_token is not null
       or new.attempt_count <> old.attempt_count
       or new.lease_expires_at is not null
       or (new.status = 'succeeded' and new.error_code is not null)
       or (new.status = 'failed' and new.error_code is null) then
      raise exception 'invalid % reconciliation terminal transition', new.status
        using errcode = '23514';
    end if;
  else
    raise exception
      'invalid reconciliation transition: % to %',
      old.status,
      new.status
      using errcode = '23514';
  end if;

  select exists (
    select 1
      from public.memory_records
     where owner_id = new.owner_id
       and id = new.record_id
  )
    into v_record_exists;

  if new.operation in ('create', 'update')
     and not v_record_exists then
    raise exception
      '% reconciliation requires a live same-owner record',
      new.operation
      using errcode = '23514';
  end if;
  if new.operation = 'delete'
     and v_record_exists then
    raise exception 'delete reconciliation requires record absence'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION argus_private.validate_memory_record_consent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_action text;
  v_candidate_id text;
  v_requested_scope text[];
  v_effective_scope text[];
begin
  select action, candidate_id, requested_scope, effective_scope
    into v_action, v_candidate_id, v_requested_scope, v_effective_scope
    from public.memory_consent_actions
   where owner_id = new.owner_id
     and id = new.consent_action_id;

  -- The composite foreign key owns missing/cross-owner linkage failures.
  if not found then
    return new;
  end if;

  if v_action <> 'candidate_confirmation'
     or v_candidate_id is distinct from new.candidate_id
     or not (new.category = any(v_requested_scope))
     or not (new.category = any(v_effective_scope)) then
    raise exception
      'memory record category must be in requested consent scope and match confirmed consent'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION argus_private.validated_usage_windows(p_user_id uuid, p_resource text, p_usage_limits jsonb, p_now timestamp with time zone) RETURNS TABLE(window_period text, limit_count integer, period_start timestamp with time zone, period_end timestamp with time zone, guest_session boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_item jsonb;
  v_period text;
  v_limit integer;
  v_start timestamptz;
  v_end timestamptz;
  v_workspace public.guest_workspaces%rowtype;
  v_expected_limit integer;
  v_is_anonymous boolean;
begin
  if jsonb_typeof(p_usage_limits) is distinct from 'array'
     or jsonb_array_length(p_usage_limits) = 0 then
    raise exception 'allowance windows are required'
      using errcode = '22023';
  end if;

  select coalesce(u.is_anonymous, false)
    into v_is_anonymous
    from auth.users as u
   where u.id = p_user_id;
  if not found then
    raise exception 'allowance owner is not an Auth user'
      using errcode = '23503';
  end if;
  if v_is_anonymous and (
    jsonb_array_length(p_usage_limits) <> 1
    or p_usage_limits -> 0 ->> 'period' <> 'guest_session'
  ) then
    raise exception 'anonymous users require the guest session allowance'
      using errcode = '23514';
  end if;
  if not v_is_anonymous and exists (
    select 1
      from jsonb_array_elements(p_usage_limits) as item
     where item ->> 'period' = 'guest_session'
  ) then
    raise exception 'permanent users cannot use a guest session allowance'
      using errcode = '23514';
  end if;

  for v_item in select value from jsonb_array_elements(p_usage_limits)
  loop
    v_period := v_item ->> 'period';
    v_limit := (v_item ->> 'limit')::integer;
    if v_limit is null or v_limit < 0 then
      raise exception 'invalid allowance limit'
        using errcode = '22023';
    end if;

    if v_period in ('hour', 'day') then
      if v_item ->> 'period_start' is not null
         or v_item ->> 'period_end' is not null then
        raise exception 'registered windows cannot supply explicit bounds'
          using errcode = '22023';
      end if;
      v_start := date_trunc(v_period, p_now);
      v_end := v_start
        + case v_period
            when 'hour' then interval '1 hour'
            else interval '1 day'
          end;
      return query
        select v_period, v_limit, v_start, v_end, false;
      continue;
    end if;

    if v_period <> 'guest_session' then
      raise exception 'unsupported allowance window'
        using errcode = '22023';
    end if;

    select *
      into v_workspace
      from public.guest_workspaces
     where user_id = p_user_id
     for update;
    if not found
       or v_workspace.status <> 'active'
       or v_workspace.expires_at <= p_now then
      raise exception 'guest workspace is not active'
        using errcode = '23514';
    end if;

    v_start := (v_item ->> 'period_start')::timestamptz;
    v_end := (v_item ->> 'period_end')::timestamptz;
    if v_start is distinct from v_workspace.created_at
       or v_end is distinct from v_workspace.expires_at then
      raise exception 'guest allowance bounds do not match workspace'
        using errcode = '23514';
    end if;

    v_expected_limit := case p_resource
      when 'chat_messages' then 10
      when 'backtest_runs' then 2
      when 'feedback' then 5
      else null
    end;
    if v_expected_limit is null or v_limit <> v_expected_limit then
      raise exception 'guest allowance limit does not match policy'
        using errcode = '23514';
    end if;
    return query
      select v_period, v_limit, v_start, v_end, true;
  end loop;
end;
$$;

CREATE FUNCTION argus_private.whatsapp_capture_consent_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if tg_op = 'UPDATE' and new.ai_consent_id is distinct from old.ai_consent_id then
        raise exception 'whatsapp_capture_consent_immutable' using errcode = '23514';
    elsif tg_op = 'INSERT' and new.ai_consent_id is not null then
        perform 1 from public.business_whatsapp_ai_consents
            where id = new.ai_consent_id and revoked_at is null for share;
        if not found then
            raise exception 'whatsapp_capture_consent_revoked' using errcode = '23514';
        end if;
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.whatsapp_outbox_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if tg_op = 'INSERT' then
        if new.state <> 'pending' or not exists (
            select 1 from public.whatsapp_inbound_messages i
             where i.provider_message_key = new.provider_message_key
               and i.transport_envelope is not null and i.composition_state = 'completed'
        ) then
            raise exception 'whatsapp_outbox_reply_not_persisted' using errcode = '23514';
        end if;
        return new;
    end if;
    if tg_op = 'DELETE' then
        if exists (select 1 from public.whatsapp_inbound_messages i
                    where i.provider_message_key = old.provider_message_key) then
            raise exception 'whatsapp_outbox_parent_required' using errcode = '23514';
        end if;
        return old;
    end if;
    if (new.provider_message_key, new.reply_index, new.body, new.created_at)
        is distinct from (old.provider_message_key, old.reply_index, old.body, old.created_at) then
        raise exception 'whatsapp_outbox_identity_immutable' using errcode = '23514';
    end if;
    if old.state in ('sent', 'unknown', 'waiting_for_window', 'suppressed')
        and new is distinct from old then
        raise exception 'whatsapp_outbox_settled' using errcode = '23514';
    end if;
    if old.state = 'sending' and new.state not in ('sending', 'sent', 'unknown') then
        raise exception 'whatsapp_outbox_no_retry' using errcode = '23514';
    end if;
    return new;
end;
$$;

CREATE FUNCTION argus_private.whatsapp_transport_original() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if tg_op = 'UPDATE' and old.transport_envelope is not null then
        if (new.id, new.provider_message_key, new.sender_hash, new.destination_owner_id,
            new.sender_link_id, new.destination_space_id, new.sent_at, new.transport_envelope,
            new.transport_key_id, new.received_at, new.arrival_sequence)
            is distinct from
           (old.id, old.provider_message_key, old.sender_hash, old.destination_owner_id,
            old.sender_link_id, old.destination_space_id, old.sent_at, old.transport_envelope,
            old.transport_key_id, old.received_at, old.arrival_sequence) then
            raise exception 'whatsapp_transport_original_immutable' using errcode = '23514';
        end if;
        if old.composition_state in ('completed', 'unknown')
            and new.composition_state is distinct from old.composition_state then
            raise exception 'whatsapp_composition_settled' using errcode = '23514';
        end if;
        if old.composition_state = 'started' and new.composition_state = 'not_started' then
            raise exception 'whatsapp_composition_no_retry' using errcode = '23514';
        end if;
    elsif new.transport_envelope is not null then
        perform 1 from public.whatsapp_sender_links l
         where l.id = new.sender_link_id and l.status = 'active'
           and l.destination_space_id = new.destination_space_id
           and l.destination_owner_id = new.destination_owner_id
           and l.wa_id_hash = new.sender_hash for share;
        if not found then
            raise exception 'whatsapp_sender_link_inactive' using errcode = '23514';
        end if;
    end if;
    return new;
end;
$$;

CREATE FUNCTION public.accept_chat_turn(p_user_id uuid, p_conversation_id uuid, p_message_id uuid, p_role text, p_content text, p_metadata jsonb, p_created_at timestamp with time zone, p_preview text, p_request_id text, p_expected_source_assistant_id uuid DEFAULT NULL::uuid, p_expected_source_metadata jsonb DEFAULT NULL::jsonb, p_option_id text DEFAULT NULL::text, p_replacement_values jsonb DEFAULT NULL::jsonb, p_request_message_id uuid DEFAULT NULL::uuid) RETURNS TABLE(message jsonb, lifecycle jsonb, replayed boolean, source_message jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_appended record;
  v_lifecycle public.chat_turn_lifecycles%rowtype;
  v_original public.messages%rowtype;
  v_retry_lifecycle public.chat_turn_lifecycles%rowtype;
  v_source public.messages%rowtype;
  v_latest public.messages%rowtype;
  v_existing public.messages%rowtype;
  v_existing_lifecycle public.chat_turn_lifecycles%rowtype;
  v_canonical_metadata jsonb;
  v_canonical_content text;
  v_canonical_preview text;
  v_retry boolean := p_request_message_id is not null;
  v_now timestamptz := clock_timestamp();
begin
  if p_role is distinct from 'user' then
    raise exception 'Accepted chat-turn message must have user role.'
      using errcode = '22023';
  end if;

  if nullif(btrim(p_request_id), '') is null then
    raise exception 'Lifecycle request id must not be blank.'
      using errcode = '22023';
  end if;

  if v_retry then
    if p_message_id = p_request_message_id then
      return;
    end if;

    select l.*
      into v_retry_lifecycle
      from public.chat_turn_lifecycles as l
     where l.turn_id = p_request_message_id
       and l.user_id = p_user_id
       and l.conversation_id = p_conversation_id
     for update;
    if not found then
      return;
    end if;

    perform 1
      from public.conversations as c
     where c.id = p_conversation_id
       and c.user_id = p_user_id
     for update;
    if not found then
      return;
    end if;

    select m.*
      into v_original
      from public.messages as m
     where m.id = p_request_message_id
       and m.user_id = p_user_id
       and m.conversation_id = p_conversation_id
       and m.role = 'user';

    if v_original.id is null
       or v_retry_lifecycle.turn_id is null
       or v_retry_lifecycle.retryable is distinct from true
       or not (
         v_retry_lifecycle.status in ('recoverable_failed', 'abandoned')
         or (
           v_retry_lifecycle.status = 'reconciled'
           and v_retry_lifecycle.reconciled_outcome = 'recoverable_failed'
         )
       )
       or jsonb_typeof(v_original.metadata -> 'chat_action')
         is distinct from 'object'
       or v_original.metadata -> 'chat_action' ->> 'type'
         is distinct from 'select_response_option'
       or jsonb_typeof(
         v_original.metadata -> 'chat_action' -> 'payload'
       ) is distinct from 'object'
       or nullif(btrim(
         v_original.metadata -> 'chat_action' -> 'payload' ->> 'option_id'
       ), '') is null
       or jsonb_typeof(
         v_original.metadata -> 'chat_action' -> 'payload'
           -> 'replacement_values'
       ) is distinct from 'object' then
      return;
    end if;

    select m.*
      into v_source
      from public.messages as m
     where m.user_id = p_user_id
       and m.conversation_id = p_conversation_id
       and m.role = 'assistant'
       and (
         m.created_at < v_original.created_at
         or (
           m.created_at = v_original.created_at
           and m.id < v_original.id
         )
       )
       and exists (
         select 1
           from jsonb_array_elements(
             case
               when jsonb_typeof(
                 m.metadata -> 'clarification' -> 'options'
               ) = 'array'
               then m.metadata -> 'clarification' -> 'options'
               else '[]'::jsonb
             end
           ) as response_option
          where response_option ->> 'id' = (
            v_original.metadata -> 'chat_action' -> 'payload' ->> 'option_id'
          )
            and response_option -> 'replacement_values' = (
              v_original.metadata -> 'chat_action' -> 'payload'
                -> 'replacement_values'
            )
       )
     order by m.created_at desc, m.id desc
     limit 1;
    if not found then
      return;
    end if;

    v_canonical_content := v_original.content;
    v_canonical_metadata := (
      coalesce(p_metadata, '{}'::jsonb)
      - 'chat_action'
      - 'mentions'
      - 'resolution_provenance'
    ) || jsonb_build_object(
      'chat_action',
      v_original.metadata -> 'chat_action'
    );
    v_canonical_preview := case
      when v_canonical_content = '__ONBOARDING_SKIP__'
        or v_canonical_content like '__ONBOARDING_GOAL__:%'
      then null
      else left(
        regexp_replace(btrim(v_canonical_content), '\s+', ' ', 'g'),
        180
      )
    end;

    select m.*
      into v_existing
      from public.messages as m
     where m.id = p_message_id;
    if found then
      select l.*
        into v_existing_lifecycle
        from public.chat_turn_lifecycles as l
       where l.turn_id = p_message_id
         and l.user_id = p_user_id
         and l.conversation_id = p_conversation_id;
      if not found
         or v_existing.user_id is distinct from p_user_id
         or v_existing.conversation_id is distinct from p_conversation_id
         or v_existing.role is distinct from p_role
         or v_existing.content is distinct from v_canonical_content
         or v_existing.metadata is distinct from v_canonical_metadata
         or v_existing_lifecycle.request_id is distinct from p_request_id then
        return;
      end if;
      return query select
        to_jsonb(v_existing),
        to_jsonb(v_existing_lifecycle),
        true,
        to_jsonb(v_source);
      return;
    end if;

    select m.*
      into v_latest
      from public.messages as m
     where m.user_id = p_user_id
       and m.conversation_id = p_conversation_id
     order by m.created_at desc, m.id desc
     limit 1;
    if not found
       or (
         v_retry_lifecycle.status = 'abandoned'
         and v_latest.id is distinct from v_original.id
       )
       or (
         v_retry_lifecycle.status <> 'abandoned'
         and v_latest.id is distinct from
           v_retry_lifecycle.assistant_message_id
       ) then
      return;
    end if;
  else
    v_canonical_content := p_content;
    v_canonical_metadata := p_metadata;
    v_canonical_preview := p_preview;
  end if;

  select appended.message, appended.source_message, appended.replayed
    into v_appended
    from public.append_conversation_message(
      p_user_id,
      p_conversation_id,
      p_message_id,
      p_role,
      v_canonical_content,
      v_canonical_metadata,
      p_created_at,
      v_canonical_preview,
      case when v_retry then null else p_expected_source_assistant_id end,
      case when v_retry then null else p_expected_source_metadata end,
      case when v_retry then null else p_option_id end,
      case when v_retry then null else p_replacement_values end
    ) as appended;

  if v_appended.message is null then
    if p_expected_source_assistant_id is not null then
      return;
    end if;
    raise exception 'Serialized message append returned no message.'
      using errcode = 'P0002';
  end if;

  insert into public.chat_turn_lifecycles (
    turn_id,
    user_id,
    conversation_id,
    request_id,
    status,
    accepted_at,
    created_at,
    updated_at
  ) values (
    p_message_id,
    p_user_id,
    p_conversation_id,
    p_request_id,
    'accepted',
    v_now,
    v_now,
    v_now
  )
  on conflict (turn_id) do nothing
  returning * into v_lifecycle;

  if not found then
    select l.*
      into v_lifecycle
      from public.chat_turn_lifecycles as l
     where l.turn_id = p_message_id
     for update;

    if not found
       or v_lifecycle.user_id is distinct from p_user_id
       or v_lifecycle.conversation_id is distinct from p_conversation_id
       or v_lifecycle.request_id is distinct from p_request_id then
      raise exception 'Chat-turn identity collided with a different request.'
        using errcode = '23505';
    end if;
  end if;

  return query select
    v_appended.message,
    to_jsonb(v_lifecycle),
    coalesce(v_appended.replayed, false),
    case
      when v_retry then to_jsonb(v_source)
      else v_appended.source_message
    end;
end;
$$;

CREATE FUNCTION public.admit_backtest_job(p_user_id uuid, p_operation_scope text, p_idempotency_key text, p_identity_hash text, p_payload_hash text, p_launch_payload jsonb, p_initial_status text, p_conversation_id uuid, p_request_message_id uuid, p_confirmation_message_id uuid, p_execution_metadata jsonb, p_user_running_limit integer, p_user_queued_limit integer, p_global_running_limit integer, p_global_queued_limit integer, p_allowance_limits jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare
    v_existing public.backtest_jobs%rowtype;
    v_job public.backtest_jobs%rowtype;
    v_now timestamptz := now();
    v_stale record;
    v_window record;
    v_charged integer;
    v_user_running integer;
    v_user_queued integer;
    v_global_running integer;
    v_global_queued integer;
begin
    if p_operation_scope not in ('chat.run_backtest', 'backtests.run') then
        raise exception 'unsupported operation scope %', p_operation_scope;
    end if;
    if p_initial_status not in ('queued', 'running') then
        raise exception 'unsupported initial status %', p_initial_status;
    end if;

    perform pg_advisory_xact_lock(hashtext('backtest_admission'));

    select * into v_existing
    from public.backtest_jobs
    where user_id = p_user_id
      and operation_scope = p_operation_scope
      and idempotency_key = p_idempotency_key
    for update;
    if found then
        if v_existing.identity_hash is null then
            if v_existing.payload_hash is not null
               and v_existing.payload_hash = p_payload_hash then
                update public.backtest_jobs
                set identity_hash = p_identity_hash,
                    updated_at = v_now
                where id = v_existing.id
                returning * into v_existing;
            else
                return jsonb_build_object('decision', 'conflict');
            end if;
        elsif v_existing.identity_hash <> p_identity_hash then
            return jsonb_build_object('decision', 'conflict');
        end if;
        if p_operation_scope = 'backtests.run'
           and v_existing.status = 'running'
           and v_existing.started_at is not null
           and v_existing.started_at <= v_now - interval '15 minutes' then
            update public.backtest_jobs
            set status = 'failed',
                failure_code = 'direct_execution_abandoned',
                failure_detail = 'execution_interrupted',
                retryable = true,
                finished_at = v_now,
                updated_at = v_now
            where id = v_existing.id
            returning * into v_existing;
        end if;
        return jsonb_build_object(
            'decision', 'replay',
            'job', to_jsonb(v_existing)
        );
    end if;

    if p_operation_scope = 'backtests.run' then
        for v_stale in
            select id from public.backtest_jobs
            where operation_scope = 'backtests.run'
              and status = 'running'
              and started_at is not null
              and started_at <= v_now - interval '15 minutes'
            order by started_at asc, id asc
            limit 20
            for update
        loop
            update public.backtest_jobs
            set status = 'failed',
                failure_code = 'direct_execution_abandoned',
                failure_detail = 'execution_interrupted',
                retryable = true,
                finished_at = v_now,
                updated_at = v_now
            where id = v_stale.id;
        end loop;
    end if;

    for v_window in
        select * from argus_private.validated_usage_windows(
          p_user_id,
          'backtest_runs',
          p_allowance_limits,
          v_now
        )
    loop
        select coalesce(sum(used_count), 0) into v_charged
        from public.usage_counters
        where user_id = p_user_id
          and resource = 'backtest_runs'
          and period = v_window.window_period
          and period_start = v_window.period_start;
        if v_charged >= v_window.limit_count then
            return jsonb_build_object(
              'decision',
              case when v_window.guest_session
                then 'conversion_required'
                else 'allowance_exhausted'
              end
            );
        end if;
    end loop;

    select
        count(*) filter (where status = 'running' and user_id = p_user_id),
        count(*) filter (where status = 'queued' and user_id = p_user_id),
        count(*) filter (where status = 'running'),
        count(*) filter (where status = 'queued')
    into v_user_running, v_user_queued, v_global_running, v_global_queued
    from public.backtest_jobs
    where status in ('queued', 'running');

    if p_operation_scope = 'backtests.run' or p_initial_status = 'running' then
        if v_user_running >= p_user_running_limit then
            return jsonb_build_object('decision', 'per_user_capacity');
        end if;
    end if;
    if p_operation_scope = 'backtests.run' or p_initial_status = 'queued' then
        if v_user_queued >= p_user_queued_limit then
            return jsonb_build_object('decision', 'per_user_capacity');
        end if;
    end if;
    if p_operation_scope = 'backtests.run' or p_initial_status = 'running' then
        if v_global_running >= p_global_running_limit then
            return jsonb_build_object('decision', 'global_capacity');
        end if;
    end if;
    if p_operation_scope = 'backtests.run' or p_initial_status = 'queued' then
        if v_global_queued >= p_global_queued_limit then
            return jsonb_build_object('decision', 'global_capacity');
        end if;
    end if;

    insert into public.backtest_jobs (
        user_id,
        conversation_id,
        request_message_id,
        confirmation_message_id,
        operation_scope,
        idempotency_key,
        identity_hash,
        payload_hash,
        launch_payload,
        status,
        priority,
        attempts,
        max_attempts,
        queued_at,
        started_at,
        execution_metadata
    ) values (
        p_user_id,
        p_conversation_id,
        p_request_message_id,
        p_confirmation_message_id,
        p_operation_scope,
        p_idempotency_key,
        p_identity_hash,
        p_payload_hash,
        p_launch_payload,
        p_initial_status,
        'normal',
        0,
        1,
        v_now,
        case when p_initial_status = 'running' then v_now else null end,
        coalesce(p_execution_metadata, '{}'::jsonb)
    ) returning * into v_job;

    for v_window in
        select * from argus_private.validated_usage_windows(
          p_user_id,
          'backtest_runs',
          p_allowance_limits,
          v_now
        )
    loop
        insert into public.usage_counters (
            user_id,
            resource,
            period,
            period_start,
            period_end,
            used_count,
            limit_count
        ) values (
            p_user_id,
            'backtest_runs',
            v_window.window_period,
            v_window.period_start,
            v_window.period_end,
            1,
            v_window.limit_count
        )
        on conflict (user_id, resource, period, period_start)
        do update set
            used_count = public.usage_counters.used_count + 1,
            limit_count = excluded.limit_count,
            updated_at = now();
    end loop;

    return jsonb_build_object(
        'decision', 'admitted',
        'job', to_jsonb(v_job)
    );
end;
$$;

CREATE FUNCTION public.append_conversation_message(p_user_id uuid, p_conversation_id uuid, p_message_id uuid, p_role text, p_content text, p_metadata jsonb, p_created_at timestamp with time zone, p_preview text, p_expected_source_assistant_id uuid, p_expected_source_metadata jsonb, p_option_id text, p_replacement_values jsonb) RETURNS TABLE(message jsonb, source_message jsonb, replayed boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_conversation_id uuid;
  v_existing public.messages%rowtype;
  v_source public.messages%rowtype;
  v_latest public.messages%rowtype;
  v_message public.messages%rowtype;
  v_latest_created_at timestamptz;
  v_created_at timestamptz;
begin
  select c.id
    into v_conversation_id
    from public.conversations as c
   where c.id = p_conversation_id
     and c.user_id = p_user_id
   for update;

  if not found then
    raise exception 'Conversation not found or not owned by user.'
      using errcode = 'P0002';
  end if;

  select m.*
    into v_existing
    from public.messages as m
   where m.id = p_message_id;

  if found then
    if v_existing.user_id is distinct from p_user_id
      or v_existing.conversation_id is distinct from p_conversation_id
      or v_existing.role is distinct from p_role
      or v_existing.content is distinct from p_content
      or v_existing.metadata is distinct from coalesce(p_metadata, '{}'::jsonb) then
      raise exception 'Message identity collided with different immutable payload.'
        using errcode = '23505';
    end if;

    if p_expected_source_assistant_id is not null then
      select m.*
        into v_source
        from public.messages as m
       where m.user_id = p_user_id
         and m.conversation_id = p_conversation_id
         and (
           m.created_at < v_existing.created_at
           or (
             m.created_at = v_existing.created_at
             and m.id < v_existing.id
           )
         )
       order by m.created_at desc, m.id desc
       limit 1;

      if not found
        or v_source.id is distinct from p_expected_source_assistant_id
        or v_source.role is distinct from 'assistant'
        or (
          p_expected_source_metadata is not null
          and v_source.metadata is distinct from p_expected_source_metadata
        )
        or jsonb_typeof(p_replacement_values) is distinct from 'object'
        or not exists (
          select 1
            from jsonb_array_elements(
              case
                when jsonb_typeof(
                  v_source.metadata -> 'clarification' -> 'options'
                ) = 'array'
                then v_source.metadata -> 'clarification' -> 'options'
                else '[]'::jsonb
              end
            ) as response_option
           where response_option ->> 'id' = p_option_id
             and response_option -> 'replacement_values'
               = p_replacement_values
        ) then
        return;
      end if;
    end if;

    return query select
      to_jsonb(v_existing),
      case
        when p_expected_source_assistant_id is null then null::jsonb
        else to_jsonb(v_source)
      end,
      true;
    return;
  end if;

  if p_expected_source_assistant_id is not null then
    select m.*
      into v_latest
      from public.messages as m
     where m.user_id = p_user_id
       and m.conversation_id = p_conversation_id
     order by m.created_at desc, m.id desc
     limit 1;

    if not found
      or v_latest.id is distinct from p_expected_source_assistant_id
      or v_latest.role is distinct from 'assistant'
      or (
        p_expected_source_metadata is not null
        and v_latest.metadata is distinct from p_expected_source_metadata
      )
      or nullif(btrim(p_option_id), '') is null
      or jsonb_typeof(p_replacement_values) is distinct from 'object'
      or not exists (
        select 1
          from jsonb_array_elements(
            case
              when jsonb_typeof(
                v_latest.metadata -> 'clarification' -> 'options'
              ) = 'array'
              then v_latest.metadata -> 'clarification' -> 'options'
              else '[]'::jsonb
            end
          ) as response_option
         where response_option ->> 'id' = p_option_id
           and response_option -> 'replacement_values' = p_replacement_values
      ) then
      return;
    end if;
    v_source := v_latest;
  end if;

  if p_created_at is null then
    raise exception 'Message created_at must not be null.'
      using errcode = '22023';
  end if;

  select max(m.created_at)
    into v_latest_created_at
    from public.messages as m
   where m.user_id = p_user_id
     and m.conversation_id = p_conversation_id;

  v_created_at := p_created_at;
  if v_latest_created_at is not null then
    v_created_at := greatest(
      v_created_at,
      v_latest_created_at + interval '1 microsecond'
    );
  end if;

  insert into public.messages (
    id,
    user_id,
    conversation_id,
    role,
    content,
    metadata,
    created_at
  )
  values (
    p_message_id,
    p_user_id,
    p_conversation_id,
    p_role,
    p_content,
    coalesce(p_metadata, '{}'::jsonb),
    v_created_at
  )
  returning * into v_message;

  if nullif(btrim(p_preview), '') is not null then
    update public.conversations as c
       set last_message_preview = p_preview,
           updated_at = now()
     where c.id = p_conversation_id
       and c.user_id = p_user_id;
  end if;

  return query select
    to_jsonb(v_message),
    case
      when p_expected_source_assistant_id is null then null::jsonb
      else to_jsonb(v_source)
    end,
    false;
end;
$$;

CREATE FUNCTION public.append_conversation_message_settling_usage(p_user_id uuid, p_conversation_id uuid, p_message_id uuid, p_role text, p_content text, p_metadata jsonb, p_created_at timestamp with time zone, p_preview text, p_usage_resource text, p_usage_limits jsonb) RETURNS TABLE(message jsonb, source_message jsonb, replayed boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'argus_private'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_result record;
  v_window record;
  v_now timestamptz := now();
  v_updated_rows bigint;
begin
  if p_usage_resource is null then
    raise exception 'settlement requires a resource'
      using errcode = '22023';
  end if;

  select t.message, t.source_message, t.replayed
    into v_result
    from public.append_conversation_message(
      p_user_id,
      p_conversation_id,
      p_message_id,
      p_role,
      p_content,
      p_metadata,
      p_created_at,
      p_preview,
      null::uuid,
      null::jsonb,
      null::text,
      null::jsonb
    ) as t;

  if v_result.message is null then
    return;
  end if;
  if coalesce(v_result.replayed, false) then
    return query
      select v_result.message, v_result.source_message, true;
    return;
  end if;

  for v_window in
    select * from argus_private.validated_usage_windows(
      p_user_id,
      p_usage_resource,
      p_usage_limits,
      v_now
    )
  loop
    if v_window.window_period = 'guest_session' then
      insert into public.usage_counters (
        user_id,
        resource,
        period,
        period_start,
        period_end,
        used_count,
        limit_count
      ) values (
        p_user_id,
        p_usage_resource,
        v_window.window_period,
        v_window.period_start,
        v_window.period_end,
        1,
        v_window.limit_count
      )
      on conflict (user_id, resource, period, period_start)
      do update set
        used_count = public.usage_counters.used_count + 1,
        limit_count = excluded.limit_count,
        updated_at = now()
      where public.usage_counters.used_count < excluded.limit_count;

      get diagnostics v_updated_rows = row_count;
      if v_updated_rows = 0 then
        raise exception 'guest message allowance exhausted'
          using errcode = 'AG010';
      end if;
    else
      insert into public.usage_counters (
        user_id,
        resource,
        period,
        period_start,
        period_end,
        used_count,
        limit_count
      ) values (
        p_user_id,
        p_usage_resource,
        v_window.window_period,
        v_window.period_start,
        v_window.period_end,
        1,
        v_window.limit_count
      )
      on conflict (user_id, resource, period, period_start)
      do update set
        used_count = public.usage_counters.used_count + 1,
        limit_count = excluded.limit_count,
        updated_at = now();
    end if;
  end loop;

  return query
    select v_result.message, v_result.source_message, false;
end;
$$;

