CREATE FUNCTION public.claim_private_alpha_access_welcome(p_email text, p_language text, p_content_version text, p_subject text) RETURNS TABLE(recipient_email text, language text, content_version text, subject text, claim_token uuid, claimed_at timestamp with time zone, send_allowed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_email text := lower(btrim(p_email));
  v_role text;
  v_language text;
  v_disabled_at timestamptz;
  v_claim public.private_alpha_access_welcome_claims%rowtype;
begin
  select a.role, a.language, a.disabled_at
    into v_role, v_language, v_disabled_at
  from public.private_alpha_allowlist as a
  where a.email = v_email
  for update;

  if not found
    or v_role is distinct from 'requested'
    or v_disabled_at is not null
    or p_language is distinct from v_language
    or p_content_version is distinct from 'private-alpha-access-welcome/v1'
    or char_length(p_subject) not between 1 and 200 then
    return;
  end if;

  select c.*
    into v_claim
  from public.private_alpha_access_welcome_claims as c
  where c.recipient_email = v_email
  for update;

  if found then
    if v_claim.language is distinct from p_language
      or v_claim.content_version is distinct from p_content_version
      or v_claim.subject is distinct from p_subject then
      return;
    end if;
  else
    insert into public.private_alpha_access_welcome_claims (
      recipient_email,
      language,
      content_version,
      subject
    )
    values (
      v_email,
      p_language,
      p_content_version,
      p_subject
    )
    returning * into v_claim;
  end if;

  return query
  select v_claim.recipient_email,
         v_claim.language,
         v_claim.content_version,
         v_claim.subject,
         v_claim.claim_token,
         v_claim.claimed_at,
         v_claim.claimed_at > now() - interval '24 hours';
end;
$$;

CREATE FUNCTION public.claim_research_usage(p_guest_visitor_key text, p_resource text, p_global_visitor_key text, p_global_limit integer, p_guest_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_period_start timestamptz := date_trunc('day', now());
  v_period_end timestamptz := date_trunc('day', now()) + interval '1 day';
  v_global_used integer;
  v_guest_used integer;
begin
  if p_resource is null or length(trim(p_resource)) = 0
     or p_global_visitor_key is null
     or length(trim(p_global_visitor_key)) = 0
     or p_global_limit is null
     or p_global_limit < 1
     or (
       p_guest_visitor_key is not null
       and (
         length(trim(p_guest_visitor_key)) = 0
         or p_guest_visitor_key = p_global_visitor_key
         or p_guest_limit is null
         or p_guest_limit < 1
       )
     ) then
    raise exception 'Research usage claim is invalid.'
      using errcode = '22023';
  end if;

  -- Every claim takes the shared row first. The fixed order prevents a guest
  -- claim and a signed-in claim from acquiring the same rows in reverse.
  insert into public.visitor_usage_counters (
    visitor_key, resource, period, period_start, period_end,
    used_count, limit_count
  ) values (
    p_global_visitor_key, p_resource, 'day', v_period_start, v_period_end,
    0, p_global_limit
  )
  on conflict (visitor_key, resource, period, period_start) do nothing;

  select used_count
    into v_global_used
    from public.visitor_usage_counters
   where visitor_key = p_global_visitor_key
     and resource = p_resource
     and period = 'day'
     and period_start = v_period_start
   for update;

  if p_guest_visitor_key is not null then
    insert into public.visitor_usage_counters (
      visitor_key, resource, period, period_start, period_end,
      used_count, limit_count
    ) values (
      p_guest_visitor_key, p_resource, 'day', v_period_start, v_period_end,
      0, p_guest_limit
    )
    on conflict (visitor_key, resource, period, period_start) do nothing;

    select used_count
      into v_guest_used
      from public.visitor_usage_counters
     where visitor_key = p_guest_visitor_key
       and resource = p_resource
       and period = 'day'
       and period_start = v_period_start
     for update;

    if v_guest_used >= p_guest_limit then
      return jsonb_build_object(
        'available', false,
        'guest_exhausted', true
      );
    end if;
  end if;

  if v_global_used >= p_global_limit then
    return jsonb_build_object(
      'available', false,
      'guest_exhausted', false
    );
  end if;

  update public.visitor_usage_counters
     set used_count = used_count + 1,
         limit_count = p_global_limit,
         period_end = v_period_end,
         updated_at = now()
   where visitor_key = p_global_visitor_key
     and resource = p_resource
     and period = 'day'
     and period_start = v_period_start;

  if p_guest_visitor_key is not null then
    update public.visitor_usage_counters
       set used_count = used_count + 1,
           limit_count = p_guest_limit,
           period_end = v_period_end,
           updated_at = now()
     where visitor_key = p_guest_visitor_key
       and resource = p_resource
       and period = 'day'
       and period_start = v_period_start;
  end if;

  -- The day charged, so a failed provider call can return exactly this charge.
  return jsonb_build_object(
    'available', true,
    'guest_exhausted', false,
    'period_start', v_period_start
  );
end;
$$;

COMMENT ON FUNCTION public.claim_research_usage(p_guest_visitor_key text, p_resource text, p_global_visitor_key text, p_global_limit integer, p_guest_limit integer) IS 'Atomically claims shared and optional guest daily research capacity before provider work.';

