CREATE FUNCTION public.complete_private_alpha_access_welcome(p_email text, p_language text, p_content_version text, p_subject text, p_provider_receipt text, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_email text := lower(btrim(p_email));
  v_role text;
  v_language text;
  v_disabled_at timestamptz;
  v_claim public.private_alpha_access_welcome_claims%rowtype;
  v_claim_found boolean;
begin
  select a.role, a.language, a.disabled_at
    into v_role, v_language, v_disabled_at
  from public.private_alpha_allowlist as a
  where a.email = v_email
  for update;

  if not found
    or v_disabled_at is not null
    or v_role not in ('requested', 'user')
    or p_language is distinct from v_language then
    return false;
  end if;

  select c.*
    into v_claim
  from public.private_alpha_access_welcome_claims as c
  where c.recipient_email = v_email
  for update;
  v_claim_found := found;

  if p_claim_token is null then
    -- Replay of an already-completed approval. An open claim means a send
    -- is owed for this grant, so the replay path must refuse and let the
    -- caller run the real claim/send path.
    if v_claim_found or v_role is distinct from 'user' then
      return false;
    end if;
    return exists (
      select 1
      from public.private_alpha_access_welcome_deliveries as d
      where d.recipient_email = v_email
        and d.language = p_language
        and d.content_version = p_content_version
        and d.subject = p_subject
    );
  end if;

  if v_claim_found then
    if v_claim.claim_token is distinct from p_claim_token
      or v_claim.language is distinct from p_language
      or v_claim.content_version is distinct from p_content_version
      or v_claim.subject is distinct from p_subject then
      return false;
    end if;

    -- The delivery row records the latest grant's welcome; a fresh grant
    -- after offboarding replaces the stale record instead of failing on it.
    insert into public.private_alpha_access_welcome_deliveries (
      recipient_email,
      language,
      content_version,
      subject,
      provider_receipt
    )
    values (
      v_email,
      p_language,
      p_content_version,
      p_subject,
      p_provider_receipt
    )
    on conflict (recipient_email) do update
      set language = excluded.language,
          content_version = excluded.content_version,
          subject = excluded.subject,
          provider_receipt = excluded.provider_receipt,
          sent_at = now();

    delete from public.private_alpha_access_welcome_claims
    where recipient_email = v_email
      and claim_token = p_claim_token;
    if not found then
      raise exception 'access welcome claim consumption failed'
        using errcode = '40001';
    end if;

    if v_role = 'requested' then
      update public.private_alpha_allowlist
      set role = 'user'
      where email = v_email
        and role = 'requested'
        and disabled_at is null;
      if not found then
        raise exception 'access welcome promotion failed'
          using errcode = '40001';
      end if;
    end if;

    return true;
  end if;

  -- Token supplied but the claim is gone: a concurrent completion already
  -- consumed it. Succeed only when that completion's outcome is in place.
  if v_role is distinct from 'user' then
    return false;
  end if;
  return exists (
    select 1
    from public.private_alpha_access_welcome_deliveries as d
    where d.recipient_email = v_email
      and d.language = p_language
      and d.content_version = p_content_version
      and d.subject = p_subject
  );
end;
$$;

CREATE FUNCTION public.create_feedback_settling_usage(p_feedback_id uuid, p_user_id uuid, p_feedback_type text, p_message text, p_context jsonb, p_usage_resource text, p_usage_limits jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_existing public.feedback%rowtype;
  v_window record;
  v_now timestamptz := now();
  v_used integer;
begin
  perform pg_advisory_xact_lock(
    hashtextextended(p_user_id::text || ':' || p_usage_resource, 0)
  );

  select *
    into v_existing
    from public.feedback
   where id = p_feedback_id
   for update;
  if found then
    if v_existing.user_id is not distinct from p_user_id
       and v_existing.type is not distinct from p_feedback_type
       and v_existing.message is not distinct from p_message
       and v_existing.context is not distinct from coalesce(p_context, '{}'::jsonb)
    then
      return jsonb_build_object(
        'decision', 'accepted',
        'feedback_id', p_feedback_id,
        'replayed', true
      );
    end if;
    raise exception 'feedback identity collision'
      using errcode = '23505';
  end if;

  for v_window in
    select * from argus_private.validated_usage_windows(
      p_user_id,
      p_usage_resource,
      p_usage_limits,
      v_now
    )
  loop
    select coalesce(sum(used_count), 0)
      into v_used
      from public.usage_counters
     where user_id = p_user_id
       and resource = p_usage_resource
       and period = v_window.window_period
       and period_start = v_window.period_start;
    if v_used >= v_window.limit_count then
      return jsonb_build_object(
        'decision',
        case when v_window.guest_session
          then 'conversion_required'
          else 'allowance_exhausted'
        end
      );
    end if;
  end loop;

  insert into public.feedback (
    id,
    user_id,
    type,
    message,
    context,
    created_at
  ) values (
    p_feedback_id,
    p_user_id,
    p_feedback_type,
    p_message,
    coalesce(p_context, '{}'::jsonb),
    v_now
  );

  for v_window in
    select * from argus_private.validated_usage_windows(
      p_user_id,
      p_usage_resource,
      p_usage_limits,
      v_now
    )
  loop
    insert into public.usage_counters (
      user_id,
      resource,
      period,
      period_start,
      period_end,
      used_count,
      limit_count
    ) values (
      p_user_id,
      p_usage_resource,
      v_window.window_period,
      v_window.period_start,
      v_window.period_end,
      1,
      v_window.limit_count
    )
    on conflict (user_id, resource, period, period_start)
    do update set
      used_count = public.usage_counters.used_count + 1,
      limit_count = excluded.limit_count,
      updated_at = now();
  end loop;

  return jsonb_build_object(
    'decision', 'accepted',
    'feedback_id', p_feedback_id,
    'replayed', false
  );
end;
$$;

CREATE FUNCTION public.create_financial_account(p_user_id uuid, p_idempotency_key text, p_identity_hash text, p_type text, p_currency text, p_nickname text, p_ownership_share_bps integer, p_opening_amount_minor bigint, p_opening_as_of timestamp with time zone, p_opening_zone text, p_owner_space_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
    v_reserved public.financial_account_idempotency%rowtype;
    v_account_id uuid;
    v_record_id uuid;
    v_now timestamptz := now();
    v_identity_hash text := p_identity_hash
        || coalesce(':space:' || p_owner_space_id::text, '');
begin
    if not exists (
        select 1 from auth.users u
        where u.id = p_user_id and coalesce(u.is_anonymous, false) = false
    ) then
        return jsonb_build_object('decision', 'registered_required');
    end if;

    select * into v_reserved
    from public.financial_account_idempotency
    where user_id = p_user_id
      and operation_scope = 'financial_accounts.create'
      and idempotency_key = p_idempotency_key
    for update;
    if found then
        if v_reserved.identity_hash = v_identity_hash then
            return jsonb_build_object('decision', 'replay', 'account_id', v_reserved.account_id);
        end if;
        return jsonb_build_object('decision', 'conflict');
    end if;

    begin
        insert into public.financial_accounts (
            user_id, owner_space_id, type, currency, nickname, ownership_share_bps,
            created_at, updated_at
        )
        values (
            p_user_id, p_owner_space_id, p_type, p_currency, p_nickname,
            p_ownership_share_bps, v_now, v_now
        )
        returning id into v_account_id;

        if p_opening_amount_minor is not null then
            insert into public.financial_records (account_id, user_id, record_kind, created_at)
            values (v_account_id, p_user_id, 'opening_balance', v_now)
            returning id into v_record_id;
            insert into public.financial_record_revisions (
                record_id, user_id, revision, amount_minor, as_of, as_of_zone,
                reason, recorded_by, recorded_at
            )
            values (
                v_record_id, p_user_id, 1, p_opening_amount_minor, p_opening_as_of,
                p_opening_zone, null, p_user_id, v_now
            );
        end if;

        insert into public.financial_account_idempotency (
            user_id, operation_scope, idempotency_key, identity_hash, account_id, created_at
        )
        values (
            p_user_id, 'financial_accounts.create', p_idempotency_key,
            v_identity_hash, v_account_id, v_now
        );
    exception when unique_violation then
        -- A concurrent request with the same key committed first. Decide from
        -- its committed row; this transaction's account insert rolls back.
        select * into v_reserved
        from public.financial_account_idempotency
        where user_id = p_user_id
          and operation_scope = 'financial_accounts.create'
          and idempotency_key = p_idempotency_key;
        if v_reserved.identity_hash = v_identity_hash then
            return jsonb_build_object('decision', 'replay', 'account_id', v_reserved.account_id);
        end if;
        return jsonb_build_object('decision', 'conflict');
    end;

    return jsonb_build_object('decision', 'created', 'account_id', v_account_id);
end;
$$;

