CREATE FUNCTION public.delete_withheld_backtest_result(p_user_id uuid, p_run_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
    v_idea_ids uuid[];
    v_deleted_run boolean;
begin
    delete from public.evidence_artifacts
    where user_id = p_user_id
      and source_run_id = p_run_id;

    with removed as (
        delete from public.idea_versions
        where user_id = p_user_id
          and source_run_id = p_run_id
        returning idea_id
    )
    select coalesce(array_agg(distinct idea_id), '{}'::uuid[])
    into v_idea_ids
    from removed;

    delete from public.ideas as idea
    where idea.user_id = p_user_id
      and idea.id = any(v_idea_ids)
      and not exists (
        select 1 from public.idea_versions as v
        where v.idea_id = idea.id
      );

    update public.ideas as idea
    set active_version_id = (
            select v.id from public.idea_versions as v
            where v.user_id = p_user_id
              and v.idea_id = idea.id
            order by v.created_at desc
            limit 1
        ),
        updated_at = now()
    where idea.user_id = p_user_id
      and idea.id = any(v_idea_ids)
      and idea.active_version_id is null;

    delete from public.backtest_runs
    where user_id = p_user_id
      and id = p_run_id
    returning true into v_deleted_run;

    return coalesce(v_deleted_run, false);
end;
$$;

CREATE FUNCTION public.dgii_rnc_lookup(p_rnc text) RETURNS TABLE(rnc text, name text, trade_name text, status text, file_date date, verification text, activity text, start_date date, regime text)
    LANGUAGE sql
    SET search_path TO ''
    AS $$
    select
        registry.rnc,
        registry.name,
        registry.trade_name,
        registry.status,
        registry.file_date,
        case
            when pg_catalog.upper(pg_catalog.btrim(registry.status)) = 'ACTIVO'
                then 'verificado'
            else 'no_activo'
        end,
        registry.activity,
        registry.start_date,
        registry.regime
    from public.dgii_rnc as registry
    where registry.rnc = nullif(
        pg_catalog.regexp_replace(coalesce(p_rnc, ''::text), '[^0-9]', '', 'g'),
        ''::text
    );
$$;

CREATE FUNCTION public.dgii_rnc_swap(min_rows integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
    load_rows bigint;
    duplicate_rncs bigint;
begin
    if min_rows is null or min_rows < 1 then
        raise exception 'min_rows must be at least 1';
    end if;

    lock table public.dgii_rnc_load in access exclusive mode;

    select count(*) into load_rows
    from public.dgii_rnc_load;
    if load_rows < min_rows then
        raise exception
            'dgii_rnc_load has % rows, fewer than the minimum %',
            load_rows,
            min_rows;
    end if;

    select count(*) into duplicate_rncs
    from (
        select load.rnc
        from public.dgii_rnc_load as load
        group by load.rnc
        having count(*) > 1
    ) as duplicates;
    if duplicate_rncs > 0 then
        raise exception 'dgii_rnc_load duplicate rnc count %', duplicate_rncs;
    end if;

    -- Built before the registry lock, so lookups keep running while the key builds.
    alter table public.dgii_rnc_load add constraint dgii_rnc_load_pkey primary key (rnc);

    lock table public.dgii_rnc in access exclusive mode;
    alter table public.dgii_rnc drop constraint dgii_rnc_pkey;
    alter table public.dgii_rnc rename to dgii_rnc_previous;
    alter table public.dgii_rnc_load rename to dgii_rnc;
    alter table public.dgii_rnc_previous rename to dgii_rnc_load;
    alter table public.dgii_rnc rename constraint dgii_rnc_load_pkey to dgii_rnc_pkey;
    truncate table public.dgii_rnc_load;

    revoke all on table public.dgii_rnc from public, anon, authenticated, service_role;
    revoke all on table public.dgii_rnc_load from public, anon, authenticated, service_role;
    grant select on table public.dgii_rnc to service_role;
    grant select, insert, update, delete, truncate on table public.dgii_rnc_load to service_role;

    return load_rows;
end;
$$;

CREATE FUNCTION public.enforce_public_excerpt_source_is_live() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_deleted_at timestamptz;
  v_id uuid;
begin
  if new.source_conversation_id is null then
    if new.selection_key is not null then
      raise exception 'public_excerpt_source_missing' using errcode = '23514';
    end if;
    return new;
  end if;
  select deleted_at into v_deleted_at from public.conversations
   where id = new.source_conversation_id and user_id = new.owner_id for share;
  if not found then
    raise exception 'public_excerpt_source_missing' using errcode = '23514';
  end if;
  if v_deleted_at is not null then
    raise exception 'public_excerpt_source_deleted' using errcode = '23514';
  end if;
  -- Deterministic lock order across overlapping selections prevents inversion.
  for v_id in select distinct unnest(new.source_message_ids) order by 1 loop
    perform 1 from public.messages where id = v_id and user_id = new.owner_id
      and conversation_id = new.source_conversation_id and role = 'assistant' for share;
    if not found then
      raise exception 'public_excerpt_source_missing' using errcode = '23514';
    end if;
  end loop;
  if cardinality(new.source_message_ids) <> (select count(distinct id) from unnest(new.source_message_ids) as id) then
    raise exception 'public_excerpt_source_missing' using errcode = '23514';
  end if;
  for v_id in select distinct unnest(new.source_run_ids) order by 1 loop
    perform 1 from public.backtest_runs where id = v_id and user_id = new.owner_id
      and conversation_id = new.source_conversation_id and status = 'completed' for share;
    if not found then
      raise exception 'public_excerpt_source_missing' using errcode = '23514';
    end if;
  end loop;
  for v_id in select distinct unnest(new.source_artifact_ids) order by 1 loop
    perform 1 from public.evidence_artifacts where id = v_id and user_id = new.owner_id
      and source_conversation_id = new.source_conversation_id for share;
    if not found then
      raise exception 'public_excerpt_source_missing' using errcode = '23514';
    end if;
  end loop;
  return new;
end;
$$;

CREATE FUNCTION public.finalize_backtest_completion(p_user_id uuid, p_execution_identity text, p_run jsonb, p_idea jsonb, p_idea_version jsonb, p_evidence_artifact jsonb) RETURNS TABLE(run jsonb, idea jsonb, idea_version jsonb, evidence_artifact jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_idea_id uuid;
  v_idea_version_id uuid;
  v_evidence_artifact_id uuid;
  v_conversation_id uuid;
  v_strategy_id uuid;
  v_input_chart jsonb;
  v_input_trades jsonb;
  v_card jsonb;
  v_run public.backtest_runs%rowtype;
  v_idea public.ideas%rowtype;
  v_idea_version public.idea_versions%rowtype;
  v_evidence_artifact public.evidence_artifacts%rowtype;
begin
  if nullif(btrim(p_execution_identity), '') is null then
    raise exception 'Backtest execution identity must not be blank.'
      using errcode = '22023';
  end if;
  if (p_run ->> 'status') is distinct from 'completed' then
    raise exception 'Backtest finalization requires a completed run.'
      using errcode = '22023';
  end if;

  v_run_id := nullif(p_run ->> 'id', '')::uuid;
  v_idea_id := nullif(p_idea ->> 'id', '')::uuid;
  v_idea_version_id := nullif(p_idea_version ->> 'id', '')::uuid;
  v_evidence_artifact_id := nullif(p_evidence_artifact ->> 'id', '')::uuid;
  if v_run_id is null
    or v_idea_id is null
    or v_idea_version_id is null
    or v_evidence_artifact_id is null then
    raise exception 'Backtest finalization ids must not be blank.'
      using errcode = '22023';
  end if;

  if nullif(p_idea_version ->> 'idea_id', '')::uuid is distinct from v_idea_id
    or nullif(p_idea_version ->> 'source_run_id', '')::uuid
      is distinct from v_run_id
    or nullif(p_evidence_artifact ->> 'idea_id', '')::uuid
      is distinct from v_idea_id
    or nullif(p_evidence_artifact ->> 'idea_version_id', '')::uuid
      is distinct from v_idea_version_id
    or nullif(p_evidence_artifact ->> 'source_run_id', '')::uuid
      is distinct from v_run_id then
    raise exception 'Backtest finalization sidecar identity is inconsistent.'
      using errcode = '22023';
  end if;

  -- Serialize retries for the same owner/execution pair before inspecting or
  -- creating any row. The application also derives a stable run id from this
  -- execution identity, so a replay converges on one durable tuple.
  perform pg_advisory_xact_lock(
    hashtextextended(p_user_id::text || ':' || btrim(p_execution_identity), 0)
  );

  v_conversation_id := nullif(p_run ->> 'conversation_id', '')::uuid;
  v_strategy_id := nullif(p_run ->> 'strategy_id', '')::uuid;
  if v_conversation_id is not null and not exists (
    select 1
      from public.conversations as c
     where c.id = v_conversation_id
       and c.user_id = p_user_id
  ) then
    raise exception 'Conversation not found or not owned by user.'
      using errcode = 'P0002';
  end if;
  if v_strategy_id is not null and not exists (
    select 1
      from public.strategies as s
     where s.id = v_strategy_id
       and s.user_id = p_user_id
  ) then
    raise exception 'Strategy not found or not owned by user.'
      using errcode = 'P0002';
  end if;
  if exists (
    select 1
      from public.backtest_runs as br
     where br.id = v_run_id
       and br.user_id <> p_user_id
  ) then
    raise exception 'Backtest run is owned by another user.'
      using errcode = '42501';
  end if;

  v_input_chart := case
    when p_run -> 'chart' = 'null'::jsonb then null
    else p_run -> 'chart'
  end;
  v_input_trades := case
    when p_run -> 'trades' = 'null'::jsonb then null
    else p_run -> 'trades'
  end;

  select br.*
    into v_run
    from public.backtest_runs as br
   where br.user_id = p_user_id
     and br.id = v_run_id
   for update;

  if found and (
    v_run.status is distinct from 'completed'
    or v_run.conversation_id is distinct from v_conversation_id
    or v_run.strategy_id is distinct from v_strategy_id
    or v_run.asset_class is distinct from (p_run ->> 'asset_class')
    or v_run.symbols is distinct from array(
      select jsonb_array_elements_text(coalesce(p_run -> 'symbols', '[]'::jsonb))
    )
    or v_run.allocation_method is distinct from (p_run ->> 'allocation_method')
    or v_run.benchmark_symbol is distinct from (p_run ->> 'benchmark_symbol')
    or v_run.metrics is distinct from coalesce(p_run -> 'metrics', '{}'::jsonb)
    or v_run.config_snapshot is distinct from
      coalesce(p_run -> 'config_snapshot', '{}'::jsonb)
    or v_run.chart is distinct from v_input_chart
    or v_run.trades is distinct from v_input_trades
  ) then
    raise exception 'Backtest run identity collided with different immutable payload.'
      using errcode = '23505';
  end if;

  select ea.*
    into v_evidence_artifact
    from public.evidence_artifacts as ea
   where ea.user_id = p_user_id
     and ea.source_run_id = v_run_id
   for update;

  if found then
    select i.*
      into v_idea
      from public.ideas as i
     where i.user_id = p_user_id
       and i.id = v_evidence_artifact.idea_id;
    if not found then
      raise exception 'Existing backtest finalization is missing its idea.'
        using errcode = '23514';
    end if;

    select iv.*
      into v_idea_version
      from public.idea_versions as iv
     where iv.user_id = p_user_id
       and iv.id = v_evidence_artifact.idea_version_id;
    if not found
      or v_idea_version.idea_id is distinct from v_idea.id
      or v_idea_version.source_run_id is distinct from v_run_id then
      raise exception 'Existing backtest finalization tuple is incomplete.'
        using errcode = '23514';
    end if;

    v_card := coalesce(v_run.conversation_result_card, '{}'::jsonb)
      || jsonb_build_object(
        'idea_id', v_idea.id,
        'idea_version_id', v_idea_version.id,
        'evidence_artifact_id', v_evidence_artifact.id,
        'evidence_lifecycle', v_evidence_artifact.lifecycle,
        'artifact_type', v_evidence_artifact.artifact_type
      );
    update public.backtest_runs as br
       set conversation_result_card = v_card,
           updated_at = now()
     where br.user_id = p_user_id
       and br.id = v_run_id
    returning br.* into v_run;

    return query select
      to_jsonb(v_run),
      to_jsonb(v_idea),
      to_jsonb(v_idea_version),
      to_jsonb(v_evidence_artifact);
    return;
  end if;

  if v_run.id is null then
    insert into public.backtest_runs (
      id,
      user_id,
      conversation_id,
      strategy_id,
      status,
      asset_class,
      symbols,
      allocation_method,
      benchmark_symbol,
      metrics,
      config_snapshot,
      conversation_result_card,
      chart,
      trades,
      created_at
    )
    values (
      v_run_id,
      p_user_id,
      v_conversation_id,
      v_strategy_id,
      'completed',
      p_run ->> 'asset_class',
      array(
        select jsonb_array_elements_text(coalesce(p_run -> 'symbols', '[]'::jsonb))
      ),
      p_run ->> 'allocation_method',
      p_run ->> 'benchmark_symbol',
      coalesce(p_run -> 'metrics', '{}'::jsonb),
      coalesce(p_run -> 'config_snapshot', '{}'::jsonb),
      coalesce(p_run -> 'conversation_result_card', '{}'::jsonb),
      v_input_chart,
      v_input_trades,
      coalesce((p_run ->> 'created_at')::timestamptz, now())
    )
    returning * into v_run;
  end if;

  insert into public.ideas (
    id,
    user_id,
    source_conversation_id,
    title,
    summary,
    lifecycle,
    active_version_id,
    created_at,
    updated_at
  )
  values (
    v_idea_id,
    p_user_id,
    nullif(p_idea ->> 'source_conversation_id', '')::uuid,
    p_idea ->> 'title',
    coalesce(p_idea ->> 'summary', ''),
    coalesce(p_idea ->> 'lifecycle', 'captured'),
    null,
    coalesce((p_idea ->> 'created_at')::timestamptz, now()),
    coalesce((p_idea ->> 'updated_at')::timestamptz, now())
  )
  returning * into v_idea;

  insert into public.idea_versions (
    id,
    user_id,
    idea_id,
    source_conversation_id,
    source_run_id,
    version_number,
    canonical_spec,
    strategy_snapshot,
    title,
    summary,
    lifecycle,
    created_at
  )
  values (
    v_idea_version_id,
    p_user_id,
    v_idea_id,
    nullif(p_idea_version ->> 'source_conversation_id', '')::uuid,
    v_run_id,
    coalesce((p_idea_version ->> 'version_number')::integer, 1),
    coalesce(p_idea_version -> 'canonical_spec', '{}'::jsonb),
    coalesce(p_idea_version -> 'strategy_snapshot', '{}'::jsonb),
    p_idea_version ->> 'title',
    coalesce(p_idea_version ->> 'summary', ''),
    coalesce(p_idea_version ->> 'lifecycle', 'captured'),
    coalesce((p_idea_version ->> 'created_at')::timestamptz, now())
  )
  returning * into v_idea_version;

  update public.ideas as i
     set active_version_id = v_idea_version_id,
         updated_at = now()
   where i.user_id = p_user_id
     and i.id = v_idea_id
  returning i.* into v_idea;

  insert into public.evidence_artifacts (
    id,
    user_id,
    idea_id,
    idea_version_id,
    source_conversation_id,
    source_run_id,
    artifact_type,
    lifecycle,
    title,
    digest,
    payload,
    created_at,
    updated_at
  )
  values (
    v_evidence_artifact_id,
    p_user_id,
    v_idea_id,
    v_idea_version_id,
    nullif(p_evidence_artifact ->> 'source_conversation_id', '')::uuid,
    v_run_id,
    coalesce(p_evidence_artifact ->> 'artifact_type', 'backtest'),
    coalesce(p_evidence_artifact ->> 'lifecycle', 'captured'),
    p_evidence_artifact ->> 'title',
    coalesce(p_evidence_artifact ->> 'digest', ''),
    coalesce(p_evidence_artifact -> 'payload', '{}'::jsonb),
    coalesce((p_evidence_artifact ->> 'created_at')::timestamptz, now()),
    coalesce((p_evidence_artifact ->> 'updated_at')::timestamptz, now())
  )
  returning * into v_evidence_artifact;

  v_card := coalesce(v_run.conversation_result_card, '{}'::jsonb)
    || jsonb_build_object(
      'idea_id', v_idea.id,
      'idea_version_id', v_idea_version.id,
      'evidence_artifact_id', v_evidence_artifact.id,
      'evidence_lifecycle', v_evidence_artifact.lifecycle,
      'artifact_type', v_evidence_artifact.artifact_type
    );
  update public.backtest_runs as br
     set conversation_result_card = v_card,
         updated_at = now()
   where br.user_id = p_user_id
     and br.id = v_run_id
  returning br.* into v_run;

  return query select
    to_jsonb(v_run),
    to_jsonb(v_idea),
    to_jsonb(v_idea_version),
    to_jsonb(v_evidence_artifact);
end;
$$;

CREATE FUNCTION public.finalize_chat_turn(p_user_id uuid, p_conversation_id uuid, p_turn_id uuid, p_request_id text, p_message_id uuid, p_role text, p_content text, p_metadata jsonb, p_created_at timestamp with time zone, p_preview text, p_to_status text, p_failure_code text, p_retryable boolean, p_usage_resource text, p_usage_limits jsonb, p_visitor_key text DEFAULT NULL::text) RETURNS TABLE(message jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_turn public.chat_turn_lifecycles%rowtype;
  v_existing public.messages%rowtype;
  v_appended record;
  v_transition jsonb;
  v_retryable boolean := coalesce(p_retryable, false);
  v_window record;
  v_visitor_windows jsonb;
begin
  select l.*
    into v_turn
    from public.chat_turn_lifecycles as l
   where l.turn_id = p_turn_id
   for update;

  if not found
     or v_turn.user_id is distinct from p_user_id
     or v_turn.conversation_id is distinct from p_conversation_id
     or v_turn.request_id is distinct from p_request_id then
    raise exception 'Chat-turn finalization conflict.'
      using errcode = 'P0002';
  end if;

  if p_role is distinct from 'assistant'
     or p_to_status not in ('completed', 'recoverable_failed')
     or (
       p_to_status = 'completed'
       and (p_failure_code is not null or v_retryable)
     )
     or (
       p_to_status = 'recoverable_failed'
       and p_usage_resource is not null
     )
     or (
       (p_usage_resource is null) is distinct from
       (p_usage_limits is null)
     )
     or (p_visitor_key is not null and p_usage_resource is null) then
    raise exception 'Chat-turn terminal payload is invalid.'
      using errcode = '22023';
  end if;

  if v_turn.status in ('completed', 'recoverable_failed') then
    select m.*
      into v_existing
      from public.messages as m
     where m.id = p_message_id;

    if not found
       or v_turn.status is distinct from p_to_status
       or v_turn.assistant_message_id is distinct from p_message_id
       or v_turn.reconciled_outcome is not null
       or v_turn.failure_code is distinct from p_failure_code
       or v_turn.retryable is distinct from v_retryable
       or v_existing.user_id is distinct from p_user_id
       or v_existing.conversation_id is distinct from p_conversation_id
       or v_existing.role is distinct from p_role
       or v_existing.content is distinct from p_content
       or v_existing.metadata is distinct from coalesce(p_metadata, '{}'::jsonb)
    then
      raise exception 'Chat-turn finalization conflict.'
        using errcode = '40001';
    end if;

    return query select to_jsonb(v_existing);
    return;
  end if;

  if v_turn.status not in ('accepted', 'running') then
    raise exception 'Chat-turn finalization conflict.'
      using errcode = '40001';
  end if;

  if p_usage_resource is not null and p_visitor_key is not null then
    -- Visitor-keyed settlement: append without account settlement, then
    -- settle the visitor windows in this same transaction. Window bounds are
    -- derived here so the charge always lands in the current period.
    select appended.message, appended.source_message, appended.replayed
      into v_appended
      from public.append_conversation_message(
        p_user_id,
        p_conversation_id,
        p_message_id,
        p_role,
        p_content,
        p_metadata,
        p_created_at,
        p_preview,
        null::uuid,
        null::jsonb,
        null::text,
        null::jsonb
      ) as appended;

    v_visitor_windows := '[]'::jsonb;
    for v_window in
      select
        (item ->> 'period')::text as window_period,
        (item ->> 'limit')::integer as limit_count
      from jsonb_array_elements(p_usage_limits) as item
    loop
      if v_window.window_period not in ('hour', 'day') then
        raise exception 'Unsupported visitor settlement period.'
          using errcode = '22023';
      end if;
      v_visitor_windows := v_visitor_windows || jsonb_build_object(
        'period', v_window.window_period,
        'limit', v_window.limit_count,
        'period_start', date_trunc(v_window.window_period, now()),
        'period_end', date_trunc(v_window.window_period, now())
          + case v_window.window_period
              when 'hour' then interval '1 hour'
              else interval '1 day'
            end
      );
    end loop;
    perform public.settle_visitor_usage(
      p_visitor_key,
      p_usage_resource,
      v_visitor_windows
    );
  elsif p_usage_resource is not null then
    select appended.message, appended.source_message, appended.replayed
      into v_appended
      from public.append_conversation_message_settling_usage(
        p_user_id,
        p_conversation_id,
        p_message_id,
        p_role,
        p_content,
        p_metadata,
        p_created_at,
        p_preview,
        p_usage_resource,
        p_usage_limits
      ) as appended;
  else
    select appended.message, appended.source_message, appended.replayed
      into v_appended
      from public.append_conversation_message(
        p_user_id,
        p_conversation_id,
        p_message_id,
        p_role,
        p_content,
        p_metadata,
        p_created_at,
        p_preview,
        null::uuid,
        null::jsonb,
        null::text,
        null::jsonb
      ) as appended;
  end if;

  if v_appended.message is null then
    raise exception 'Chat-turn terminal message was not persisted.'
      using errcode = 'P0002';
  end if;

  select public.transition_chat_turn(
    p_turn_id,
    p_to_status,
    p_message_id,
    null,
    p_failure_code,
    v_retryable
  )
  into v_transition;

  if v_transition ->> 'outcome' not in ('applied', 'noop') then
    raise exception 'Chat-turn finalization conflict.'
      using errcode = '40001';
  end if;

  return query select v_appended.message;
end;
$$;

CREATE FUNCTION public.finalize_direct_backtest_success(p_user_id uuid, p_job_id uuid, p_execution_identity text, p_run jsonb, p_idea jsonb, p_idea_version jsonb, p_evidence_artifact jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
    v_job public.backtest_jobs%rowtype;
    v_final record;
begin
    select * into v_job
    from public.backtest_jobs
    where user_id = p_user_id
      and id = p_job_id
      and operation_scope = 'backtests.run'
    for update;

    if not found or v_job.status <> 'running' then
        return null;
    end if;

    select * into v_final
    from public.finalize_backtest_completion(
        p_user_id,
        p_execution_identity,
        p_run,
        p_idea,
        p_idea_version,
        p_evidence_artifact
    );

    update public.backtest_jobs
    set status = 'succeeded',
        result_run_id = (v_final.run ->> 'id')::uuid,
        failure_code = null,
        failure_detail = null,
        retryable = false,
        finished_at = now(),
        updated_at = now()
    where id = p_job_id;

    return jsonb_build_object(
        'run', v_final.run,
        'idea', v_final.idea,
        'idea_version', v_final.idea_version,
        'evidence_artifact', v_final.evidence_artifact
    );
end;
$$;

CREATE FUNCTION public.is_active_household_member(p_household_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    select exists (
        select 1
        from public.household_members m
        where m.household_id = p_household_id
          and m.user_id = p_user_id
          and m.left_at is null
    );
$$;

CREATE FUNCTION public.mutate_conversation_activity_read_state(p_user_id uuid, p_conversation_id uuid, p_action text, p_source_kind text, p_source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_conversation public.conversations%rowtype;
  v_state public.conversation_read_states%rowtype;
  v_source_occurred_at timestamptz;
  v_source_kind_rank integer;
  v_current_kind_rank integer;
  v_now timestamptz := clock_timestamp();
  v_changed boolean := false;
begin
  if p_action not in ('mark_unread', 'mark_read') then
    return jsonb_build_object('outcome', 'invalid', 'read_state', null);
  end if;
  if p_action = 'mark_unread'
     and (p_source_kind is not null or p_source_id is not null) then
    return jsonb_build_object('outcome', 'invalid', 'read_state', null);
  end if;
  if p_action = 'mark_read'
     and ((p_source_kind is null) <> (p_source_id is null)) then
    return jsonb_build_object('outcome', 'invalid', 'read_state', null);
  end if;
  if p_source_kind is not null
     and p_source_kind not in ('chat_turn', 'backtest_job') then
    return jsonb_build_object('outcome', 'invalid', 'read_state', null);
  end if;

  select c.*
    into v_conversation
    from public.conversations as c
   where c.id = p_conversation_id
     and c.user_id = p_user_id
     and c.deleted_at is null
   for update;

  if not found then
    return jsonb_build_object('outcome', 'missing', 'read_state', null);
  end if;

  select rs.*
    into v_state
    from public.conversation_read_states as rs
   where rs.user_id = p_user_id
     and rs.conversation_id = p_conversation_id
   for update;

  if p_action = 'mark_unread' then
    if found then
      if v_state.manual_unread_at is null then
        update public.conversation_read_states
           set manual_unread_at = v_now,
               updated_at = v_now
         where user_id = p_user_id
           and conversation_id = p_conversation_id
        returning * into v_state;
        v_changed := true;
      end if;
    else
      insert into public.conversation_read_states (
        user_id,
        conversation_id,
        manual_unread_at
      ) values (
        p_user_id,
        p_conversation_id,
        v_now
      )
      on conflict (user_id, conversation_id) do update
        set manual_unread_at = coalesce(
              public.conversation_read_states.manual_unread_at,
              excluded.manual_unread_at
            ),
            updated_at = case
              when public.conversation_read_states.manual_unread_at is null
                then excluded.updated_at
              else public.conversation_read_states.updated_at
            end
      returning * into v_state;
      v_changed := true;
    end if;
    return jsonb_build_object(
      'outcome', case when v_changed then 'applied' else 'noop' end,
      'read_state', to_jsonb(v_state)
    );
  end if;

  if p_source_kind = 'chat_turn' then
    select l.terminal_at
      into v_source_occurred_at
      from public.chat_turn_lifecycles as l
     where l.turn_id = p_source_id
       and l.user_id = p_user_id
       and l.conversation_id = p_conversation_id
       and l.status in (
         'completed', 'recoverable_failed', 'abandoned', 'reconciled'
       )
     for update;
    v_source_kind_rank := 1;
  elsif p_source_kind = 'backtest_job' then
    select coalesce(j.finished_at, j.updated_at)
      into v_source_occurred_at
      from public.backtest_jobs as j
     where j.id = p_source_id
       and j.user_id = p_user_id
       and j.conversation_id = p_conversation_id
       and (
         j.status in ('failed', 'canceled', 'expired')
         or (
           j.status = 'succeeded'
           and argus_private.backtest_job_result_hydrateable(j)
         )
       )
     for update;
    v_source_kind_rank := 2;
  end if;

  if p_source_id is not null and v_source_occurred_at is null then
    return jsonb_build_object('outcome', 'conflict', 'read_state', null);
  end if;

  if v_state.conversation_id is null then
    if p_source_id is null then
      return jsonb_build_object('outcome', 'noop', 'read_state', null);
    end if;
    insert into public.conversation_read_states (
      user_id,
      conversation_id,
      read_through_occurred_at,
      read_through_source_kind,
      read_through_source_id
    ) values (
      p_user_id,
      p_conversation_id,
      v_source_occurred_at,
      p_source_kind,
      p_source_id
    )
    on conflict (user_id, conversation_id) do nothing
    returning * into v_state;
    if found then
      v_changed := true;
    else
      select rs.*
        into v_state
        from public.conversation_read_states as rs
       where rs.user_id = p_user_id
         and rs.conversation_id = p_conversation_id
       for update;
    end if;
  end if;

  if v_state.manual_unread_at is not null then
    v_changed := true;
  end if;

  if p_source_id is not null then
    v_current_kind_rank := case v_state.read_through_source_kind
      when 'chat_turn' then 1
      when 'backtest_job' then 2
      else null
    end;
    if v_state.read_through_occurred_at is null
       or (
         v_source_occurred_at,
         v_source_kind_rank,
         p_source_id
       ) > (
         v_state.read_through_occurred_at,
         v_current_kind_rank,
         v_state.read_through_source_id
       ) then
      v_changed := true;
      v_state.read_through_occurred_at := v_source_occurred_at;
      v_state.read_through_source_kind := p_source_kind;
      v_state.read_through_source_id := p_source_id;
    end if;
  end if;

  if v_changed then
    update public.conversation_read_states
       set read_through_occurred_at = v_state.read_through_occurred_at,
           read_through_source_kind = v_state.read_through_source_kind,
           read_through_source_id = v_state.read_through_source_id,
           manual_unread_at = null,
           updated_at = v_now
     where user_id = p_user_id
       and conversation_id = p_conversation_id
    returning * into v_state;
  end if;

  return jsonb_build_object(
    'outcome', case when v_changed then 'applied' else 'noop' end,
    'read_state', to_jsonb(v_state)
  );
end;
$$;

CREATE FUNCTION public.prepare_guest_workspace_handoff(p_source_user_id uuid, p_destination_email_hash text, p_source_conversation_id uuid, p_pending_action jsonb, p_secret_hash text, p_existing_secret_hash text DEFAULT NULL::text, p_handoff_kind text DEFAULT 'existing_account'::text) RETURNS TABLE(id uuid, expires_at timestamp with time zone, destination_user_id uuid, reused_secret boolean)
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  select *
    from argus_private.prepare_guest_workspace_handoff(
      p_source_user_id,
      p_destination_email_hash,
      p_source_conversation_id,
      p_pending_action,
      p_secret_hash,
      p_existing_secret_hash,
      p_handoff_kind
    );
$$;

CREATE FUNCTION public.prevent_evidence_artifact_immutable_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_owner_transfer boolean :=
    current_user = 'postgres'
    and current_setting('argus.owner_transfer', true) = 'on';
begin
  if new.id is distinct from old.id
    or (new.user_id is distinct from old.user_id and not v_owner_transfer)
    or new.idea_id is distinct from old.idea_id
    or new.idea_version_id is distinct from old.idea_version_id
    or new.source_conversation_id is distinct from old.source_conversation_id
    or new.source_run_id is distinct from old.source_run_id
    or new.artifact_type is distinct from old.artifact_type
    or new.title is distinct from old.title
    or new.digest is distinct from old.digest
    or new.payload is distinct from old.payload
    or new.created_at is distinct from old.created_at then
    raise exception 'evidence_artifacts immutable fields cannot be updated'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.prevent_idea_version_immutable_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_owner_transfer boolean :=
    current_user = 'postgres'
    and current_setting('argus.owner_transfer', true) = 'on';
begin
  if new.id is distinct from old.id
    or (new.user_id is distinct from old.user_id and not v_owner_transfer)
    or new.idea_id is distinct from old.idea_id
    or new.source_conversation_id is distinct from old.source_conversation_id
    or new.source_run_id is distinct from old.source_run_id
    or new.version_number is distinct from old.version_number
    or new.canonical_spec is distinct from old.canonical_spec
    or new.strategy_snapshot is distinct from old.strategy_snapshot
    or new.title is distinct from old.title
    or new.summary is distinct from old.summary
    or new.created_at is distinct from old.created_at then
    raise exception 'idea_versions immutable fields cannot be updated'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.prevent_public_excerpt_immutable_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.id is distinct from old.id
    or new.public_id is distinct from old.public_id
    or new.owner_id is distinct from old.owner_id
    or new.title is distinct from old.title
    or new.payload is distinct from old.payload
    or new.payload_digest is distinct from old.payload_digest
    or new.created_at is distinct from old.created_at
    or new.kind is distinct from old.kind
    or new.selection_key is distinct from old.selection_key
    or new.source_message_ids is distinct from old.source_message_ids
    or new.source_run_ids is distinct from old.source_run_ids
    or new.source_artifact_ids is distinct from old.source_artifact_ids then
    raise exception 'public_excerpt_snapshots immutable fields cannot be updated'
      using errcode = '23514';
  end if;

  if old.revoked_at is not null
    and (
      new.revoked_at is distinct from old.revoked_at
      or new.revocation_reason is distinct from old.revocation_reason
    ) then
    raise exception 'public_excerpt_snapshots revocation cannot be reversed'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION public.protect_foreign_activity_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if exists(select 1 from public.financial_activity_memberships where activity_id=OLD.id and record_owner_id<>OLD.user_id) then
  raise exception 'surviving original owners retain canonical activity history' using errcode='23514';
 end if;
 return OLD;
end $$;

CREATE FUNCTION public.protect_guest_workspace_policy_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_anonymous boolean;
begin
  if tg_op = 'INSERT' then
    select coalesce(u.is_anonymous, false)
      into v_is_anonymous
      from auth.users as u
     where u.id = new.user_id;
    if not found or not v_is_anonymous then
      raise exception 'guest workspace requires an anonymous Auth user'
        using errcode = '23514';
    end if;
    new.expires_at := new.created_at + interval '7 days';
    return new;
  end if;

  if new.user_id is distinct from old.user_id
     or new.created_at is distinct from old.created_at
     or new.expires_at is distinct from old.expires_at then
    raise exception 'guest identity and expiry are immutable'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.protect_profile_age_confirmation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if TG_OP = 'UPDATE' and OLD.age_confirmed_at is not null then
    if NEW.age_confirmed_at is distinct from OLD.age_confirmed_at then
      raise exception 'age confirmation is immutable' using errcode = '23514';
    end if;
  end if;
  if NEW.age_confirmed_at is not null then
    if current_user in ('anon', 'authenticated') and
       (TG_OP = 'INSERT' or OLD.age_confirmed_at is distinct from NEW.age_confirmed_at) then
      raise exception 'age confirmation requires backend initialization' using errcode = '42501';
    end if;
    if not pg_catalog.isfinite(NEW.age_confirmed_at) or
       NEW.age_confirmed_at > pg_catalog.now() + interval '5 minutes' then
      raise exception 'invalid age confirmation instant' using errcode = '23514';
    end if;
  end if;
  return NEW;
end;
$$;

CREATE FUNCTION public.protect_profile_name_initialization() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if TG_OP = 'INSERT' then
    NEW.name_initialization_closed := NEW.name_initialization_closed
      or NEW.display_name is not null or NEW.preferred_name is not null;
  elsif OLD.name_initialization_closed then
    NEW.name_initialization_closed := true;
  end if;
  return NEW;
end;
$$;

CREATE FUNCTION public.purge_expired_guest_funnel_milestones(p_before timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_deleted integer;
begin
  delete from public.guest_funnel_milestones where expires_at <= p_before;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

CREATE FUNCTION public.purge_expired_visitor_usage(p_before timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_deleted integer;
begin
  delete from public.visitor_usage_counters where period_end <= p_before;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

CREATE FUNCTION public.read_conversation_activity_sources(p_user_id uuid, p_conversation_ids uuid[]) RETURNS TABLE(conversation_id uuid, sources jsonb, read_state jsonb)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
begin
  if p_conversation_ids is null or cardinality(p_conversation_ids) = 0 then
    return;
  end if;
  if cardinality(p_conversation_ids) > 100 then
    raise exception 'conversation_activity_batch_too_large'
      using errcode = '22023';
  end if;

  return query
  with requested as (
    select distinct requested_id
      from unnest(p_conversation_ids) as requested_id
  )
  select
    c.id,
    coalesce(activity.sources, '[]'::jsonb),
    case
      when rs.conversation_id is null then null
      else jsonb_build_object(
        'read_through_occurred_at', rs.read_through_occurred_at,
        'read_through_source_kind', rs.read_through_source_kind,
        'read_through_source_id', rs.read_through_source_id,
        'manual_unread_at', rs.manual_unread_at
      )
    end
  from requested
  join public.conversations as c
    on c.id = requested.requested_id
   and c.user_id = p_user_id
  left join public.conversation_read_states as rs
    on rs.conversation_id = c.id
   and rs.user_id = c.user_id
  left join lateral (
    select jsonb_agg(
      source.payload
      order by source.occurred_at, source.source_kind_rank, source.source_id
    ) as sources
    from (
      with jobs as (
        -- One owner-predicate evaluation per job row, shared by the active
        -- and terminal branches below.
        select
          j.*,
          argus_private.backtest_job_result_hydrateable(j) as result_hydrateable
        from public.backtest_jobs as j
        where j.user_id = c.user_id
          and j.conversation_id = c.id
          and j.status in (
            'queued', 'running', 'succeeded', 'failed', 'canceled', 'expired'
          )
      )
      (
        select
          jsonb_build_object(
            'conversation_id', l.conversation_id,
            'source_kind', 'chat_turn',
            'source_id', l.turn_id,
            'status', l.status,
            'occurred_at', l.updated_at,
            'stage_outcome', null,
            'result_hydrateable', false
          ) as payload,
          l.updated_at as occurred_at,
          1 as source_kind_rank,
          l.turn_id as source_id
        from public.chat_turn_lifecycles as l
        where l.user_id = c.user_id
          and l.conversation_id = c.id
          and l.status in ('accepted', 'running')
        order by
          case l.status when 'running' then 2 else 1 end desc,
          l.updated_at desc,
          l.turn_id desc
        limit 1
      )
      union all
      (
        select
          jsonb_build_object(
            'conversation_id', l.conversation_id,
            'source_kind', 'chat_turn',
            'source_id', l.turn_id,
            'status', case
              when l.status = 'reconciled' then
                'reconciled:' || l.reconciled_outcome
              else l.status
            end,
            'occurred_at', l.terminal_at,
            'stage_outcome',
              m.metadata ->> 'agent_runtime_stage_outcome',
            'result_hydrateable', false
          ) as payload,
          l.terminal_at as occurred_at,
          1 as source_kind_rank,
          l.turn_id as source_id
        from public.chat_turn_lifecycles as l
        left join public.messages as m
          on m.id = l.assistant_message_id
         and m.user_id = l.user_id
         and m.conversation_id = l.conversation_id
        where l.user_id = c.user_id
          and l.conversation_id = c.id
          and l.status in (
            'completed', 'recoverable_failed', 'abandoned', 'reconciled'
          )
        order by l.terminal_at desc, l.turn_id desc
        limit 1
      )
      union all
      (
        select
          jsonb_build_object(
            'conversation_id', ranked.conversation_id,
            'source_kind', 'backtest_job',
            'source_id', ranked.id,
            'status', ranked.status,
            'occurred_at', ranked.updated_at,
            'stage_outcome', null,
            'result_hydrateable', ranked.result_hydrateable
          ) as payload,
          ranked.updated_at as occurred_at,
          2 as source_kind_rank,
          ranked.id as source_id
        from jobs as ranked
        where ranked.status in ('queued', 'running', 'succeeded')
          and (
            ranked.status <> 'succeeded'
            or not ranked.result_hydrateable
          )
        order by
          case ranked.status
            when 'running' then 3
            when 'queued' then 2
            else 1
          end desc,
          ranked.updated_at desc,
          ranked.id desc
        limit 1
      )
      union all
      (
        select
          jsonb_build_object(
            'conversation_id', ranked.conversation_id,
            'source_kind', 'backtest_job',
            'source_id', ranked.id,
            'status', ranked.status,
            'occurred_at', coalesce(ranked.finished_at, ranked.updated_at),
            'stage_outcome', null,
            'result_hydrateable', ranked.result_hydrateable
          ) as payload,
          coalesce(ranked.finished_at, ranked.updated_at) as occurred_at,
          2 as source_kind_rank,
          ranked.id as source_id
        from jobs as ranked
        where ranked.status in ('succeeded', 'failed', 'canceled', 'expired')
          and (
            ranked.status <> 'succeeded'
            or ranked.result_hydrateable
          )
        order by coalesce(ranked.finished_at, ranked.updated_at) desc,
          ranked.id desc
        limit 1
      )
    ) as source
  ) as activity on true
  order by c.id;
end;
$$;

CREATE FUNCTION public.reconcile_stale_chat_turns(p_conversation_id uuid, p_user_id uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_turn public.chat_turn_lifecycles%rowtype;
  v_evidence public.messages%rowtype;
  v_outcome text;
  v_failure_code text;
  v_retryable boolean;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  for v_turn in
    select l.*
      from public.chat_turn_lifecycles as l
     where l.user_id = p_user_id
       and l.conversation_id = p_conversation_id
       and l.status in ('accepted', 'running')
       and coalesce(l.running_at, l.accepted_at)
         <= v_now - interval '15 minutes'
     order by coalesce(l.running_at, l.accepted_at) asc, l.turn_id asc
     limit 20
     for update skip locked
  loop
    if v_turn.status not in ('accepted', 'running')
       or coalesce(v_turn.running_at, v_turn.accepted_at)
         > v_now - interval '15 minutes' then
      continue;
    end if;

    select m.*
      into v_evidence
      from public.messages as m
     where m.user_id = v_turn.user_id
       and m.conversation_id = v_turn.conversation_id
       and m.role = 'assistant'
       and m.metadata #>> '{agent_runtime_turn,turn_id}'
         = v_turn.turn_id::text
       and m.metadata #>> '{agent_runtime_turn,request_id}'
         = v_turn.request_id
       and m.metadata #> '{agent_runtime_turn,terminal}' = 'true'::jsonb
       and m.metadata #>> '{agent_runtime_turn,status}'
         in ('completed', 'recoverable_failed')
       and (
         m.metadata #>> '{agent_runtime_turn,status}' = 'completed'
         or (
           m.metadata #>> '{agent_runtime_turn,status}'
             = 'recoverable_failed'
           and m.metadata -> 'agent_runtime_turn' ? 'failure_code'
           and jsonb_typeof(
             m.metadata #> '{agent_runtime_turn,failure_code}'
           ) in ('string', 'null')
           and m.metadata -> 'agent_runtime_turn' ? 'retryable'
           and jsonb_typeof(
             m.metadata #> '{agent_runtime_turn,retryable}'
           ) = 'boolean'
         )
       )
     order by m.created_at asc,
       case m.metadata #>> '{agent_runtime_turn,status}'
         when 'recoverable_failed' then 0
         else 1
       end asc,
       m.id asc
     limit 1;

    if found then
      v_outcome := v_evidence.metadata
        #>> '{agent_runtime_turn,status}';
      v_failure_code := case
        when v_outcome = 'recoverable_failed' then
          v_evidence.metadata #>> '{agent_runtime_turn,failure_code}'
        else null
      end;
      v_retryable := case
        when v_outcome = 'recoverable_failed' then
          coalesce(
            v_evidence.metadata
              #> '{agent_runtime_turn,retryable}' = 'true'::jsonb,
            false
          )
        else false
      end;

      select public.transition_chat_turn(
        v_turn.turn_id,
        'reconciled',
        v_evidence.id,
        v_outcome,
        v_failure_code,
        v_retryable
      )
      into v_result;
    else
      select public.transition_chat_turn(
        v_turn.turn_id,
        'abandoned',
        null,
        null,
        'turn_abandoned',
        true
      )
      into v_result;
    end if;

    if v_result ->> 'outcome' in ('applied', 'noop')
       and v_result -> 'row' is not null then
      return next v_result -> 'row';
    end if;
  end loop;
end;
$$;

CREATE FUNCTION public.reconcile_stale_conversation_activity_turns(p_user_id uuid, p_conversation_ids uuid[]) RETURNS SETOF jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_turn public.chat_turn_lifecycles%rowtype;
  v_evidence public.messages%rowtype;
  v_outcome text;
  v_failure_code text;
  v_retryable boolean;
  v_result jsonb;
  v_now timestamptz := clock_timestamp();
begin
  if p_conversation_ids is null or cardinality(p_conversation_ids) = 0 then
    return;
  end if;
  if cardinality(p_conversation_ids) > 100 then
    raise exception 'conversation_activity_batch_too_large'
      using errcode = '22023';
  end if;

  for v_turn in
    select l.*
      from public.chat_turn_lifecycles as l
      join public.conversations as c
        on c.id = l.conversation_id
       and c.user_id = l.user_id
       and c.deleted_at is null
     where l.user_id = p_user_id
       and l.conversation_id = any(p_conversation_ids)
       and l.status in ('accepted', 'running')
       and coalesce(l.running_at, l.accepted_at)
         <= v_now - interval '15 minutes'
     order by coalesce(l.running_at, l.accepted_at) asc, l.turn_id asc
     limit 20
     for update of l skip locked
  loop
    if v_turn.status not in ('accepted', 'running')
       or coalesce(v_turn.running_at, v_turn.accepted_at)
         > v_now - interval '15 minutes' then
      continue;
    end if;

    select m.*
      into v_evidence
      from public.messages as m
     where m.user_id = v_turn.user_id
       and m.conversation_id = v_turn.conversation_id
       and m.role = 'assistant'
       and m.metadata #>> '{agent_runtime_turn,turn_id}'
         = v_turn.turn_id::text
       and m.metadata #>> '{agent_runtime_turn,request_id}'
         = v_turn.request_id
       and m.metadata #> '{agent_runtime_turn,terminal}' = 'true'::jsonb
       and m.metadata #>> '{agent_runtime_turn,status}'
         in ('completed', 'recoverable_failed')
       and (
         m.metadata #>> '{agent_runtime_turn,status}' = 'completed'
         or (
           m.metadata #>> '{agent_runtime_turn,status}'
             = 'recoverable_failed'
           and m.metadata -> 'agent_runtime_turn' ? 'failure_code'
           and jsonb_typeof(
             m.metadata #> '{agent_runtime_turn,failure_code}'
           ) in ('string', 'null')
           and m.metadata -> 'agent_runtime_turn' ? 'retryable'
           and jsonb_typeof(
             m.metadata #> '{agent_runtime_turn,retryable}'
           ) = 'boolean'
         )
       )
     order by m.created_at asc,
       case m.metadata #>> '{agent_runtime_turn,status}'
         when 'recoverable_failed' then 0
         else 1
       end asc,
       m.id asc
     limit 1;

    if found then
      v_outcome := v_evidence.metadata #>> '{agent_runtime_turn,status}';
      v_failure_code := case
        when v_outcome = 'recoverable_failed' then
          v_evidence.metadata #>> '{agent_runtime_turn,failure_code}'
        else null
      end;
      v_retryable := case
        when v_outcome = 'recoverable_failed' then
          coalesce(
            v_evidence.metadata #> '{agent_runtime_turn,retryable}'
              = 'true'::jsonb,
            false
          )
        else false
      end;

      select public.transition_chat_turn(
        v_turn.turn_id,
        'reconciled',
        v_evidence.id,
        v_outcome,
        v_failure_code,
        v_retryable
      ) into v_result;
    else
      select public.transition_chat_turn(
        v_turn.turn_id,
        'abandoned',
        null,
        null,
        'turn_abandoned',
        true
      ) into v_result;
    end if;

    if v_result ->> 'outcome' in ('applied', 'noop')
       and v_result -> 'row' is not null then
      return next v_result -> 'row';
    end if;
  end loop;
end;
$$;

CREATE FUNCTION public.record_goal_allocation_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if TG_OP='UPDATE' then
  if (OLD.unlinked_minor,OLD.binding_id,OLD.contributor_membership_id) is not distinct from
     (NEW.unlinked_minor,NEW.binding_id,NEW.contributor_membership_id) then return NEW; end if;
  NEW.revision=OLD.revision+1;
 end if;
 insert into public.financial_goal_allocation_revisions values
 (NEW.id,NEW.revision,NEW.goal_id,NEW.goal_owner_id,NEW.account_id,NEW.account_owner_id,
  NEW.unlinked_minor,NEW.contributor_membership_id,NEW.binding_id);
 return NEW;
end $$;

CREATE FUNCTION public.record_plan_definition_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if TG_OP='UPDATE' and OLD.body=NEW.body then return NEW; end if;
 if TG_OP='UPDATE' and current_setting('argus.locked_history_writer', true) = 'deletion'
    and current_user = 'postgres'
    and (NEW.body->>'version') = (OLD.body->>'version') then
  return NEW;
 end if;
 if TG_OP='UPDATE' and (NEW.body->>'version')::integer <= (OLD.body->>'version')::integer then
  raise exception 'canonical definition revision must advance' using errcode='23514';
 end if;
 insert into public.financial_plan_definition_revisions(kind,definition_id,owner_id,revision,body,actor_id)
 values(TG_ARGV[0],NEW.id,NEW.user_id,(NEW.body->>'version')::integer,NEW.body,
 nullif(current_setting('argus.plan_actor',true),'')::uuid);
 if TG_OP='UPDATE' then
  insert into public.financial_plan_responsibilities
   select kind,definition_id,owner_id,(NEW.body->>'version')::integer,
    membership_id,amount_minor,period,occurrence_id,schedule_id,agreed_date
   from public.financial_plan_responsibilities
   where kind=TG_ARGV[0] and definition_id=NEW.id and owner_id=NEW.user_id
    and revision=(OLD.body->>'version')::integer;
 end if;
 return NEW;
end $$;

CREATE FUNCTION public.release_expired_private_alpha_access_welcome_claims(p_expired_before timestamp with time zone DEFAULT (now() - '48:00:00'::interval)) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_released integer;
begin
  delete from public.private_alpha_access_welcome_claims
  where claimed_at <= p_expired_before;
  get diagnostics v_released = row_count;
  return v_released;
end;
$$;

CREATE FUNCTION public.release_research_usage(p_guest_visitor_key text, p_resource text, p_global_visitor_key text, p_period_start timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_released boolean;
begin
  if p_guest_visitor_key is null
     or length(trim(p_guest_visitor_key)) = 0
     or p_resource is null
     or length(trim(p_resource)) = 0
     or p_global_visitor_key is null
     or length(trim(p_global_visitor_key)) = 0
     or p_guest_visitor_key = p_global_visitor_key
     or p_period_start is null then
    raise exception 'Research usage release is invalid.'
      using errcode = '22023';
  end if;

  -- Only the guest's own row for the day that was charged, and never below
  -- zero. The shared row is never touched here.
  update public.visitor_usage_counters
     set used_count = used_count - 1,
         updated_at = now()
   where visitor_key = p_guest_visitor_key
     and resource = p_resource
     and period = 'day'
     and period_start = p_period_start
     and used_count > 0;
  v_released := found;

  return jsonb_build_object('released', v_released);
end;
$$;

COMMENT ON FUNCTION public.release_research_usage(p_guest_visitor_key text, p_resource text, p_global_visitor_key text, p_period_start timestamp with time zone) IS 'Returns a guest''s own daily research claim after provider work failed with no usable response; the shared ceiling keeps the attempt.';

CREATE TABLE public.conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    title text NOT NULL,
    title_source text DEFAULT 'system_default'::text NOT NULL,
    language text,
    pinned boolean DEFAULT false NOT NULL,
    archived boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    last_message_preview text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    owner_space_id uuid,
    CONSTRAINT conversations_language_check CHECK ((language = ANY (ARRAY['en'::text, 'es-419'::text]))),
    CONSTRAINT conversations_title_source_check CHECK ((title_source = ANY (ARRAY['system_default'::text, 'ai_generated'::text, 'user_renamed'::text])))
);

COMMENT ON COLUMN public.conversations.owner_space_id IS 'The Business space this conversation belongs to; null means Personal. Pinned to user_id.';

CREATE FUNCTION public.replace_empty_guest_conversation(p_user_id uuid, p_title text, p_title_source text, p_language text) RETURNS public.conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_workspace public.guest_workspaces%rowtype;
  v_conversation public.conversations%rowtype;
begin
  select *
    into v_workspace
    from public.guest_workspaces
   where user_id = p_user_id
   for update;
  if not found
     or v_workspace.status <> 'active'
     or v_workspace.expires_at <= now() then
    raise exception 'guest workspace is not active'
      using errcode = '23514';
  end if;

  if v_workspace.conversation_id is not null then
    if exists (
      select 1 from public.messages
       where conversation_id = v_workspace.conversation_id
    ) or exists (
      select 1 from public.backtest_jobs
       where conversation_id = v_workspace.conversation_id
    ) or exists (
      select 1 from public.backtest_runs
       where conversation_id = v_workspace.conversation_id
    ) then
      raise exception 'guest conversation is not empty'
        using errcode = '23514';
    end if;
    delete from public.conversations
     where id = v_workspace.conversation_id
       and user_id = p_user_id;
  end if;

  insert into public.conversations (
    user_id,
    title,
    title_source,
    language
  ) values (
    p_user_id,
    p_title,
    p_title_source,
    p_language
  )
  returning * into v_conversation;
  return v_conversation;
end;
$$;

CREATE FUNCTION public.replace_guest_conversation(p_user_id uuid, p_title text, p_title_source text, p_language text) RETURNS public.conversations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
declare
  v_workspace public.guest_workspaces%rowtype;
  v_conversation public.conversations%rowtype;
begin
  select *
    into v_workspace
    from public.guest_workspaces
   where user_id = p_user_id
   for update;
  if not found
     or v_workspace.status <> 'active'
     or v_workspace.expires_at <= now()
     or v_workspace.conversation_id is null then
    raise exception 'guest_workspace_unavailable' using errcode = 'P0001';
  end if;

  if not exists (
      select 1 from public.conversations
       where id = v_workspace.conversation_id and user_id = p_user_id
    )
    or exists (
      select 1 from public.conversations
       where user_id = p_user_id and id <> v_workspace.conversation_id
    )
    or exists (
      select 1 from public.messages
       where (user_id = p_user_id and conversation_id <> v_workspace.conversation_id)
          or (conversation_id = v_workspace.conversation_id and user_id <> p_user_id)
    )
    or exists (
      select 1 from public.strategies
       where (user_id = p_user_id and conversation_id is distinct from v_workspace.conversation_id)
          or (conversation_id = v_workspace.conversation_id and user_id <> p_user_id)
    )
    or exists (
      select 1 from public.backtest_runs
       where (user_id = p_user_id and conversation_id is distinct from v_workspace.conversation_id)
          or (conversation_id = v_workspace.conversation_id and user_id <> p_user_id)
    )
    or exists (
      select 1 from public.backtest_jobs
       where (user_id = p_user_id and conversation_id <> v_workspace.conversation_id)
          or (conversation_id = v_workspace.conversation_id and user_id <> p_user_id)
    )
    or exists (
      select 1 from public.ideas
       where (user_id = p_user_id and source_conversation_id is distinct from v_workspace.conversation_id)
          or (source_conversation_id = v_workspace.conversation_id and user_id <> p_user_id)
    )
    or exists (
      select 1 from public.idea_versions
       where (user_id = p_user_id and source_conversation_id is distinct from v_workspace.conversation_id)
          or (source_conversation_id = v_workspace.conversation_id and user_id <> p_user_id)
    )
    or exists (
      select 1 from public.evidence_artifacts
       where (user_id = p_user_id and source_conversation_id is distinct from v_workspace.conversation_id)
          or (source_conversation_id = v_workspace.conversation_id and user_id <> p_user_id)
    )
    or exists (
      select 1 from public.decision_notes
       where (user_id = p_user_id and source_conversation_id is distinct from v_workspace.conversation_id)
          or (source_conversation_id = v_workspace.conversation_id and user_id <> p_user_id)
    )
    or exists (select 1 from public.collections where user_id = p_user_id)
    or exists (select 1 from public.collection_strategies where user_id = p_user_id) then
    raise exception 'guest_start_over_unsafe_product_graph' using errcode = 'P0001';
  end if;

  update public.guest_workspaces
     set conversation_id = null,
         updated_at = now()
   where user_id = p_user_id;

  delete from public.decision_notes where user_id = p_user_id;
  delete from public.evidence_artifacts where user_id = p_user_id;
  update public.ideas set active_version_id = null where user_id = p_user_id;
  delete from public.idea_versions where user_id = p_user_id;
  delete from public.ideas where user_id = p_user_id;
  delete from public.run_context_packets where user_id = p_user_id;
  delete from public.context_packets where user_id = p_user_id;
  delete from public.backtest_jobs where user_id = p_user_id;
  delete from public.backtest_runs where user_id = p_user_id;
  delete from public.strategies where user_id = p_user_id;
  delete from public.messages where user_id = p_user_id;
  delete from public.checkpoint_writes
   where thread_id = v_workspace.conversation_id::text;
  delete from public.checkpoint_blobs
   where thread_id = v_workspace.conversation_id::text;
  delete from public.checkpoints
   where thread_id = v_workspace.conversation_id::text;
  delete from public.conversations
   where id = v_workspace.conversation_id and user_id = p_user_id;

  insert into public.conversations (user_id, title, title_source, language)
  values (p_user_id, p_title, p_title_source, p_language)
  returning * into v_conversation;
  return v_conversation;
end;
$$;

CREATE FUNCTION public.require_private_alpha_access_welcome_delivery() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.role = 'requested'
    and new.role = 'user'
    and new.disabled_at is null
    and not exists (
      select 1
      from public.private_alpha_access_welcome_deliveries
      where recipient_email = new.email
        and language = new.language
    ) then
    raise exception 'requested promotion requires welcome delivery'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION public.revoke_public_excerpts_for_deleted_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_now timestamptz := now();
begin
  if tg_op = 'DELETE' then
    if tg_table_name = 'conversations' then
      update public.public_excerpt_snapshots as snapshot
         set revoked_at = v_now,
             revocation_reason = 'source_deleted'
       where snapshot.source_conversation_id = old.id
         and snapshot.revoked_at is null
         and exists (
           select 1 from public.profiles as owner
            where owner.id = snapshot.owner_id
         );
    elsif tg_table_name = 'backtest_runs' then
      update public.public_excerpt_snapshots as snapshot
         set revoked_at = v_now,
             revocation_reason = 'source_deleted'
       where (snapshot.source_run_id = old.id or old.id = any(snapshot.source_run_ids))
         and snapshot.revoked_at is null
         and exists (
           select 1 from public.profiles as owner
            where owner.id = snapshot.owner_id
         );
    elsif tg_table_name = 'messages' then
      update public.public_excerpt_snapshots as snapshot
         set revoked_at = v_now, revocation_reason = 'source_deleted'
       where old.id = any(snapshot.source_message_ids)
         and snapshot.revoked_at is null
         and exists (select 1 from public.profiles as owner where owner.id = snapshot.owner_id);
    else
      update public.public_excerpt_snapshots as snapshot
         set revoked_at = v_now,
             revocation_reason = 'source_deleted'
       where (snapshot.evidence_artifact_id = old.id or old.id = any(snapshot.source_artifact_ids))
         and snapshot.revoked_at is null
         and exists (
           select 1 from public.profiles as owner
            where owner.id = snapshot.owner_id
         );
    end if;
    return old;
  end if;

  if old.deleted_at is null and new.deleted_at is not null then
    update public.public_excerpt_snapshots as snapshot
       set revoked_at = v_now,
           revocation_reason = 'source_deleted'
     where snapshot.source_conversation_id = new.id
       and snapshot.revoked_at is null
       and exists (
         select 1 from public.profiles as owner
          where owner.id = snapshot.owner_id
       );
  end if;
  return new;
end;
$$;

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if current_user='postgres' and tg_op='UPDATE' then
        if argus_private.business_custody_identity_change(tg_table_name,to_jsonb(old),to_jsonb(new)) then return new; end if;
    end if;
  new.updated_at = now();
  return new;
end;
$$;

CREATE FUNCTION public.settle_visitor_usage(p_visitor_key text, p_resource text, p_windows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_window record;
  v_used integer;
  v_results jsonb := '[]'::jsonb;
begin
  if p_visitor_key is null or length(trim(p_visitor_key)) = 0 then
    raise exception 'visitor key is required';
  end if;

  for v_window in
    select
      (item->>'period')::text as window_period,
      (item->>'limit')::integer as limit_count,
      (item->>'period_start')::timestamptz as period_start,
      (item->>'period_end')::timestamptz as period_end
    from jsonb_array_elements(p_windows) as item
  loop
    if v_window.limit_count < 1 then
      raise exception 'visitor allowance exhausted'
        using errcode = 'P0001';
    end if;

    insert into public.visitor_usage_counters (
      visitor_key, resource, period, period_start, period_end,
      used_count, limit_count
    ) values (
      p_visitor_key, p_resource, v_window.window_period,
      v_window.period_start, v_window.period_end, 1, v_window.limit_count
    )
    on conflict (visitor_key, resource, period, period_start)
    do update set
      used_count = public.visitor_usage_counters.used_count + 1,
      limit_count = excluded.limit_count,
      updated_at = now()
    where public.visitor_usage_counters.used_count < excluded.limit_count
    returning used_count into v_used;

    if v_used is null then
      raise exception 'visitor allowance exhausted'
        using errcode = 'P0001';
    end if;

    v_results := v_results || jsonb_build_object(
      'period', v_window.window_period,
      'used_count', v_used,
      'limit_count', v_window.limit_count
    );
  end loop;

  return jsonb_build_object('settled', true, 'windows', v_results);
end;
$$;

CREATE FUNCTION public.transition_chat_turn(p_turn_id uuid, p_to_status text, p_assistant_message_id uuid, p_reconciled_outcome text, p_failure_code text, p_retryable boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_turn public.chat_turn_lifecycles%rowtype;
  v_message public.messages%rowtype;
  v_expected_message_status text;
  v_retryable boolean := coalesce(p_retryable, false);
  v_now timestamptz := clock_timestamp();
begin
  select l.*
    into v_turn
    from public.chat_turn_lifecycles as l
   where l.turn_id = p_turn_id
   for update;

  if not found then
    return jsonb_build_object('outcome', 'missing', 'row', null);
  end if;

  if p_to_status = 'running' then
    if p_assistant_message_id is not null
       or p_reconciled_outcome is not null
       or p_failure_code is not null
       or v_retryable then
      return jsonb_build_object(
        'outcome', 'invalid',
        'row', to_jsonb(v_turn)
      );
    end if;
  elsif p_to_status = 'completed' then
    if p_assistant_message_id is null
       or p_reconciled_outcome is not null
       or p_failure_code is not null
       or v_retryable then
      return jsonb_build_object(
        'outcome', 'invalid',
        'row', to_jsonb(v_turn)
      );
    end if;
  elsif p_to_status = 'recoverable_failed' then
    if p_assistant_message_id is null
       or p_reconciled_outcome is not null then
      return jsonb_build_object(
        'outcome', 'invalid',
        'row', to_jsonb(v_turn)
      );
    end if;
  elsif p_to_status = 'abandoned' then
    if p_assistant_message_id is not null
       or p_reconciled_outcome is not null
       or p_failure_code is distinct from 'turn_abandoned'
       or not v_retryable then
      return jsonb_build_object(
        'outcome', 'invalid',
        'row', to_jsonb(v_turn)
      );
    end if;
  elsif p_to_status = 'reconciled' then
    if p_assistant_message_id is null
       or p_reconciled_outcome not in ('completed', 'recoverable_failed')
       or (
         p_reconciled_outcome = 'completed'
         and (p_failure_code is not null or v_retryable)
       ) then
      return jsonb_build_object(
        'outcome', 'invalid',
        'row', to_jsonb(v_turn)
      );
    end if;
  else
    return jsonb_build_object(
      'outcome', 'invalid',
      'row', to_jsonb(v_turn)
    );
  end if;

  if v_turn.status = p_to_status then
    if v_turn.assistant_message_id is not distinct from p_assistant_message_id
       and v_turn.reconciled_outcome
         is not distinct from p_reconciled_outcome
       and v_turn.failure_code is not distinct from p_failure_code
       and v_turn.retryable is not distinct from v_retryable then
      return jsonb_build_object(
        'outcome', 'noop',
        'row', to_jsonb(v_turn)
      );
    end if;
    return jsonb_build_object(
      'outcome', 'conflict',
      'row', to_jsonb(v_turn)
    );
  end if;

  if v_turn.status in (
    'completed',
    'recoverable_failed',
    'abandoned',
    'reconciled'
  ) then
    return jsonb_build_object(
      'outcome', 'conflict',
      'row', to_jsonb(v_turn)
    );
  end if;

  if v_turn.status not in ('accepted', 'running') then
    return jsonb_build_object(
      'outcome', 'conflict',
      'row', to_jsonb(v_turn)
    );
  end if;

  if not (
    (v_turn.status = 'accepted' and p_to_status = 'running')
    or (
      v_turn.status in ('accepted', 'running')
      and p_to_status in (
        'completed',
        'recoverable_failed',
        'abandoned',
        'reconciled'
      )
    )
  ) then
    return jsonb_build_object(
      'outcome', 'conflict',
      'row', to_jsonb(v_turn)
    );
  end if;

  if p_assistant_message_id is not null then
    select m.*
      into v_message
      from public.messages as m
     where m.id = p_assistant_message_id
       and m.user_id = v_turn.user_id
       and m.conversation_id = v_turn.conversation_id
       and m.role = 'assistant';

    v_expected_message_status := case
      when p_to_status = 'reconciled' then p_reconciled_outcome
      else p_to_status
    end;

    if not found
       or v_message.metadata #>> '{agent_runtime_turn,turn_id}'
         is distinct from v_turn.turn_id::text
       or v_message.metadata #>> '{agent_runtime_turn,request_id}'
         is distinct from v_turn.request_id
       or v_message.metadata #> '{agent_runtime_turn,terminal}'
         is distinct from 'true'::jsonb
       or v_message.metadata #>> '{agent_runtime_turn,status}'
         is distinct from v_expected_message_status
       or (
         v_expected_message_status = 'recoverable_failed'
         and (
           not (
             v_message.metadata -> 'agent_runtime_turn' ? 'failure_code'
           )
           or not (
             v_message.metadata -> 'agent_runtime_turn' ? 'retryable'
           )
           or jsonb_typeof(
             v_message.metadata #> '{agent_runtime_turn,retryable}'
           ) is distinct from 'boolean'
           or not (
             jsonb_typeof(
               v_message.metadata #> '{agent_runtime_turn,failure_code}'
             ) in ('string', 'null')
           )
           or v_message.metadata
             #>> '{agent_runtime_turn,failure_code}'
             is distinct from p_failure_code
           or v_message.metadata
             #> '{agent_runtime_turn,retryable}'
             is distinct from to_jsonb(v_retryable)
         )
       )
       or exists (
         select 1
           from public.chat_turn_lifecycles as linked
          where linked.assistant_message_id = p_assistant_message_id
            and linked.turn_id <> p_turn_id
       ) then
      return jsonb_build_object(
        'outcome', 'invalid',
        'row', to_jsonb(v_turn)
      );
    end if;
  end if;

  update public.chat_turn_lifecycles as l
     set status = p_to_status,
         assistant_message_id = p_assistant_message_id,
         reconciled_outcome = p_reconciled_outcome,
         failure_code = p_failure_code,
         retryable = v_retryable,
         running_at = case
           when p_to_status = 'running' then v_now
           else l.running_at
         end,
         terminal_at = case
           when p_to_status in (
             'completed',
             'recoverable_failed',
             'abandoned',
             'reconciled'
           ) then v_now
           else null
         end,
         reconciled_at = case
           when p_to_status = 'reconciled' then v_now
           else null
         end,
         updated_at = v_now
   where l.turn_id = p_turn_id
  returning l.* into v_turn;

  return jsonb_build_object(
    'outcome', 'applied',
    'row', to_jsonb(v_turn)
  );
end;
$$;

CREATE FUNCTION public.update_conversation_message_artifact(p_user_id uuid, p_conversation_id uuid, p_message_id uuid, p_content text, p_metadata jsonb, p_expected_source_metadata jsonb, p_expected_latest_message_id uuid, p_preview text) RETURNS TABLE(message jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_conversation_id uuid;
  v_message public.messages%rowtype;
  v_latest_id uuid;
begin
  select c.id
    into v_conversation_id
    from public.conversations as c
   where c.id = p_conversation_id
     and c.user_id = p_user_id
   for update;

  if not found then
    raise exception 'Conversation not found or not owned by user.'
      using errcode = 'P0002';
  end if;

  select m.*
    into v_message
    from public.messages as m
   where m.id = p_message_id
     and m.user_id = p_user_id
     and m.conversation_id = p_conversation_id;

  if not found then
    raise exception 'Message not found or not owned by user.'
      using errcode = 'P0002';
  end if;

  select m.id
    into v_latest_id
    from public.messages as m
   where m.user_id = p_user_id
     and m.conversation_id = p_conversation_id
   order by m.created_at desc, m.id desc
   limit 1;

  if p_expected_latest_message_id is not null
    and v_latest_id is distinct from p_expected_latest_message_id then
    return;
  end if;

  if p_expected_source_metadata is not null
    and v_message.metadata is distinct from p_expected_source_metadata then
    return;
  end if;

  update public.messages as m
     set content = p_content,
         metadata = coalesce(p_metadata, '{}'::jsonb)
   where m.id = p_message_id
  returning * into v_message;

  -- The update changes neither created_at nor id, so v_latest_id is still
  -- the conversation's latest message inside this lock.
  if nullif(btrim(p_preview), '') is not null
    and v_latest_id = p_message_id then
    update public.conversations as c
       set last_message_preview = p_preview
     where c.id = p_conversation_id
       and c.user_id = p_user_id;
  end if;

  return query select to_jsonb(v_message);
end;
$$;

CREATE FUNCTION public.upsert_current_decision_note(p_user_id uuid, p_evidence_artifact_id uuid, p_decision_id uuid, p_decision_state text, p_note text) RETURNS TABLE(decision jsonb, evidence_artifact jsonb, idea jsonb, idea_version jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  artifact_row public.evidence_artifacts%rowtype;
  decision_row public.decision_notes%rowtype;
  idea_row public.ideas%rowtype;
  version_row public.idea_versions%rowtype;
begin
  select *
    into artifact_row
    from public.evidence_artifacts
   where user_id = p_user_id
     and id = p_evidence_artifact_id
   for update;

  if not found then
    raise exception 'Evidence artifact not found or not owned by user.'
      using errcode = 'P0002';
  end if;

  insert into public.decision_notes (
    id,
    user_id,
    idea_id,
    idea_version_id,
    evidence_artifact_id,
    source_conversation_id,
    decision_state,
    note
  )
  values (
    p_decision_id,
    p_user_id,
    artifact_row.idea_id,
    artifact_row.idea_version_id,
    artifact_row.id,
    artifact_row.source_conversation_id,
    p_decision_state,
    p_note
  )
  on conflict (user_id, evidence_artifact_id)
  do update set
    decision_state = excluded.decision_state,
    note = excluded.note,
    updated_at = now()
  returning * into decision_row;

  update public.evidence_artifacts
     set lifecycle = 'decided',
         updated_at = now()
   where user_id = p_user_id
     and id = artifact_row.id
  returning * into artifact_row;

  update public.ideas
     set lifecycle = 'decided',
         updated_at = now()
   where user_id = p_user_id
     and id = artifact_row.idea_id
  returning * into idea_row;

  update public.idea_versions
     set lifecycle = 'decided'
   where user_id = p_user_id
     and id = artifact_row.idea_version_id
  returning * into version_row;

  return query select
    to_jsonb(decision_row),
    to_jsonb(artifact_row),
    to_jsonb(idea_row),
    to_jsonb(version_row);
end;
$$;

CREATE FUNCTION public.validate_financial_asset_types() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
 if TG_TABLE_NAME='financial_asset_details' then
  if not exists(select 1 from financial_accounts where id=new.account_id and user_id=new.user_id and type in ('property','vehicle','other_asset'))
   or (new.related_debt_account_id is not null and not exists(select 1 from financial_accounts where id=new.related_debt_account_id and user_id=new.user_id and type in ('credit_card','other_debt'))) then
   raise exception 'invalid asset or liability type' using errcode='23514';
  end if;
 elsif new.type<>old.type and (
  (new.type not in ('property','vehicle','other_asset') and exists(select 1 from financial_asset_details where account_id=new.id))
  or (new.type not in ('credit_card','other_debt') and exists(select 1 from financial_asset_details where related_debt_account_id=new.id))
 ) then
  raise exception 'linked account type is retained' using errcode='23514';
 end if;
 return new;
end $$;

CREATE FUNCTION public.validate_profile_auth_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_anonymous boolean;
  v_auth_email text;
begin
  select coalesce(u.is_anonymous, false), nullif(btrim(u.email), '')
    into v_is_anonymous, v_auth_email
    from auth.users as u
   where u.id = new.id;

  if not found then
    raise exception 'profile requires a Supabase Auth user'
      using errcode = '23503';
  end if;

  if v_is_anonymous then
    if new.email is not null then
      raise exception 'anonymous profiles cannot store an email'
        using errcode = '23514';
    end if;
  elsif new.email is null
     or v_auth_email is null
     or lower(btrim(new.email)) is distinct from lower(v_auth_email) then
    raise exception 'permanent profiles require the verified Auth email'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

CREATE FUNCTION public.validate_shared_allocation_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if NEW.binding_id is not null and not exists (
  select 1 from public.household_plan_bindings b join public.household_members m
  on m.id=NEW.contributor_membership_id and m.household_id=b.household_id and m.user_id=NEW.account_owner_id
  where b.id=NEW.binding_id and b.goal_id=NEW.goal_id and b.owner_user_id=NEW.goal_owner_id) then
  raise exception 'shared allocation must retain true owner and consent' using errcode='23514';
 end if;
 return NEW;
end $$;

CREATE FUNCTION public.validate_shared_claim_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if NEW.binding_id is not null and not exists (
  select 1 from public.household_plan_bindings b join public.household_members m
  on m.id=NEW.contributor_membership_id and m.household_id=b.household_id
  where b.id=NEW.binding_id and b.owner_user_id=NEW.user_id
  and (b.budget_id,b.expectation_id,b.goal_id,b.debt_plan_id) is not distinct from
      (NEW.budget_id,NEW.expectation_id,NEW.goal_id,NEW.debt_plan_id)) then
  raise exception 'shared claim must retain its canonical binding' using errcode='23514';
 end if;
 return NEW;
end $$;

CREATE FUNCTION public.whatsapp_inbound_clear_settled_envelope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
    if new.status not in ('received', 'failed') or new.claim_until is null then
        new.claim_envelope := null;
    end if;
    return new;
end;
$$;

CREATE FUNCTION public.write_financial_opening(p_user_id uuid, p_account_id uuid, p_expected_revision integer, p_expected_version integer, p_amount_minor bigint, p_as_of timestamp with time zone, p_zone text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
    v_account public.financial_accounts%rowtype;
    v_record public.financial_records%rowtype;
    v_next integer;
    v_now timestamptz := now();
begin
    if not exists (
        select 1 from auth.users u
        where u.id = p_user_id and coalesce(u.is_anonymous, false) = false
    ) then
        return jsonb_build_object('decision', 'registered_required');
    end if;

    select * into v_account
    from public.financial_accounts
    where id = p_account_id and user_id = p_user_id
    for update;
    if not found then
        return jsonb_build_object('decision', 'not_found');
    end if;
    if v_account.version is distinct from p_expected_version then
        return jsonb_build_object('decision', 'stale');
    end if;

    select * into v_record
    from public.financial_records
    where account_id = p_account_id and record_kind = 'opening_balance'
    for update;

    if (found and v_record.current_revision is distinct from p_expected_revision)
       or (not found and p_expected_revision is not null) then
        return jsonb_build_object('decision', 'stale');
    end if;

    if not found then
        insert into public.financial_records (account_id, user_id, record_kind, created_at)
        values (p_account_id, p_user_id, 'opening_balance', v_now)
        returning * into v_record;
        v_next := 1;
    else
        v_next := v_record.current_revision + 1;
        update public.financial_records
        set current_revision = v_next
        where id = v_record.id;
    end if;

    insert into public.financial_record_revisions (
        record_id, user_id, revision, amount_minor, as_of, as_of_zone,
        reason, recorded_by, recorded_at
    )
    values (
        v_record.id, p_user_id, v_next, p_amount_minor, p_as_of, p_zone,
        p_reason, p_user_id, v_now
    );

    update public.financial_accounts
    set version = version + 1
    where id = p_account_id;

    return jsonb_build_object(
        'decision', 'written', 'record_id', v_record.id, 'revision', v_next
    );
end;
$$;

CREATE TABLE argus_private.account_deletion_placeholders (
    subject_hash text NOT NULL,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    placeholder_id uuid NOT NULL,
    created boolean DEFAULT false NOT NULL,
    used boolean DEFAULT false NOT NULL,
    CONSTRAINT account_deletion_placeholders_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['household'::text, 'group'::text])))
);

CREATE TABLE argus_private.account_deletion_revocations (
    subject_hash text NOT NULL,
    provider text NOT NULL,
    source_ref uuid NOT NULL,
    external_ref text,
    secret_ciphertext bytea,
    secret_key_fingerprint text,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_deletion_revocations_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT account_deletion_revocations_check CHECK (((status = 'pending'::text) OR ((secret_ciphertext IS NULL) AND (external_ref IS NULL)))),
    CONSTRAINT account_deletion_revocations_check1 CHECK (((secret_ciphertext IS NOT NULL) OR (secret_key_fingerprint IS NULL))),
    CONSTRAINT account_deletion_revocations_last_error_check CHECK ((char_length(last_error) <= 200)),
    CONSTRAINT account_deletion_revocations_provider_check CHECK ((provider = ANY (ARRAY['gmail'::text, 'plaid'::text, 'apple'::text]))),
    CONSTRAINT account_deletion_revocations_secret_key_fingerprint_check CHECK ((secret_key_fingerprint ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT account_deletion_revocations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'revoked'::text, 'already_revoked'::text, 'unrecoverable'::text, 'operator_forced'::text])))
);

CREATE TABLE argus_private.account_deletion_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subject_hash text,
    user_id uuid,
    analytics_distinct_id text,
    status text DEFAULT 'started'::text NOT NULL,
    steps jsonb DEFAULT '{}'::jsonb NOT NULL,
    claim_id uuid,
    claimed_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT account_deletion_runs_check CHECK (((status = ANY (ARRAY['started'::text, 'data_deleted'::text])) = (user_id IS NOT NULL))),
    CONSTRAINT account_deletion_runs_check1 CHECK (((status = 'done'::text) = (subject_hash IS NULL))),
    CONSTRAINT account_deletion_runs_check2 CHECK (((status = 'done'::text) = (analytics_distinct_id IS NULL))),
    CONSTRAINT account_deletion_runs_check3 CHECK (((claim_id IS NULL) = (claimed_until IS NULL))),
    CONSTRAINT account_deletion_runs_check4 CHECK (((status <> 'done'::text) OR (claim_id IS NULL))),
    CONSTRAINT account_deletion_runs_status_check CHECK ((status = ANY (ARRAY['started'::text, 'data_deleted'::text, 'done'::text]))),
    CONSTRAINT account_deletion_runs_steps_check CHECK ((jsonb_typeof(steps) = 'object'::text)),
    CONSTRAINT account_deletion_runs_subject_hash_check CHECK ((subject_hash ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE argus_private.account_placeholders (
    id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE argus_private.business_custody_changes (
    space_id uuid NOT NULL,
    table_name text NOT NULL,
    old_row jsonb NOT NULL,
    new_row jsonb NOT NULL
);

COMMENT ON TABLE argus_private.business_custody_changes IS 'Transaction-local exact row rewrite proof for validated postgres deletion writer. Cleared before commit.';

CREATE TABLE argus_private.business_custody_deferred_keys (
    constraint_name text NOT NULL
);

CREATE TABLE argus_private.business_custody_moves (
    space_id uuid NOT NULL,
    departing_user_id uuid,
    deletion_run_id uuid NOT NULL,
    claim_id uuid,
    started_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    identity_cleaned_at timestamp with time zone
);

COMMENT ON TABLE argus_private.business_custody_moves IS 'In-flight identity map. Clear departed ID and claim after verified Auth deletion. No client/service writer.';

CREATE TABLE argus_private.business_custody_objects (
    space_id uuid NOT NULL,
    source_path text,
    destination_path text NOT NULL,
    sha256 text NOT NULL,
    size_bytes bigint NOT NULL,
    media_type text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    verified_at timestamp with time zone,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    CONSTRAINT business_custody_objects_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT business_custody_objects_size_bytes_check CHECK ((size_bytes >= 0))
);

COMMENT ON TABLE argus_private.business_custody_objects IS 'Tracked destination before external copy. Original and rebuilt hashes are independent. Source paths contain in-flight identity and must be cleared by the future deletion completion writer. RESTRICT prevents silently losing the purge plan.';

COMMENT ON COLUMN argus_private.business_custody_objects.id IS 'Random durable copy key. Source path is nullable after identity cleanup; destination and orphan tracking remain until purge.';

CREATE TABLE argus_private.business_custody_reservations (
    space_id uuid NOT NULL,
    custodian_id uuid NOT NULL,
    deleted_actor_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    auth_ready_at timestamp with time zone,
    moved_at timestamp with time zone,
    CONSTRAINT business_custody_reservations_check CHECK ((custodian_id <> deleted_actor_id))
);

COMMENT ON TABLE argus_private.business_custody_reservations IS 'One reserved banned custodian and anonymous historical actor per Business. No departed-person key. Copy preparation alone never authorizes record movement or deletion.';

COMMENT ON COLUMN argus_private.business_custody_reservations.moved_at IS 'Committed full graph movement. Copy preparation alone never settles this marker.';

CREATE TABLE argus_private.business_departure_aliases (
    space_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    departing_user_id uuid,
    deletion_run_id uuid NOT NULL,
    claim_id uuid,
    started_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    identity_cleaned_at timestamp with time zone,
    CONSTRAINT business_departure_aliases_check CHECK (((departing_user_id IS NULL) = (identity_cleaned_at IS NOT NULL))),
    CONSTRAINT business_departure_aliases_check1 CHECK (((claim_id IS NULL) = (identity_cleaned_at IS NOT NULL)))
);

COMMENT ON TABLE argus_private.business_departure_aliases IS 'Scoped anonymous historical actors with no Auth or access grant. Departed identity and claim exist only until verified Auth absence; aliases expire with Business purge.';

CREATE TABLE argus_private.business_invitation_commands (
    space_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    command_key text NOT NULL,
    email text NOT NULL,
    requested_role text NOT NULL,
    invite_id uuid,
    CONSTRAINT business_invitation_commands_command_key_check CHECK (((length(command_key) >= 1) AND (length(command_key) <= 200)))
);

CREATE TABLE argus_private.business_purge_objects (
    run_id uuid NOT NULL,
    path text NOT NULL,
    deleted_at timestamp with time zone
);

COMMENT ON TABLE argus_private.business_purge_objects IS 'Exact original, rebuilt and reserved orphan-copy cleanup plan persisted before Business cascades. Paths are removed at settlement. Shared live references prevent object removal.';

CREATE TABLE argus_private.business_purge_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    closed_at timestamp with time zone NOT NULL,
    status text DEFAULT 'started'::text NOT NULL,
    placeholder_id uuid,
    claim_id uuid,
    claimed_until timestamp with time zone,
    started_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT business_purge_runs_check CHECK (((claim_id IS NULL) = (claimed_until IS NULL))),
    CONSTRAINT business_purge_runs_check1 CHECK (((status = 'done'::text) = (completed_at IS NOT NULL))),
    CONSTRAINT business_purge_runs_check2 CHECK (((status <> 'done'::text) OR (placeholder_id IS NULL))),
    CONSTRAINT business_purge_runs_status_check CHECK ((status = ANY (ARRAY['started'::text, 'data_deleted'::text, 'done'::text])))
);

COMMENT ON TABLE argus_private.business_purge_runs IS 'Postgres-only day-30 retry receipt. The original close date gates graph deletion. Claims serialize sweep passes. Placeholder ID is erased after verified Auth absence. No Business name or real account ID is retained.';

CREATE TABLE argus_private.business_report_view_commands (
    space_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    command_key text NOT NULL,
    command jsonb NOT NULL,
    result jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_report_view_commands_command_check CHECK ((jsonb_typeof(command) = 'object'::text)),
    CONSTRAINT business_report_view_commands_command_key_check CHECK ((((char_length(command_key) >= 1) AND (char_length(command_key) <= 200)) AND (char_length(btrim(command_key)) > 0))),
    CONSTRAINT business_report_view_commands_result_check CHECK ((jsonb_typeof(result) = 'object'::text))
);

COMMENT ON TABLE argus_private.business_report_view_commands IS 'Private idempotency receipts for preference changes. Account deletion cascades preference metadata only; financial custody and retained records do not change.';

CREATE TABLE argus_private.business_saved_report_views (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    name text NOT NULL,
    recipe jsonb NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_saved_report_views_name_check CHECK ((((char_length(name) >= 1) AND (char_length(name) <= 120)) AND (char_length(btrim(name)) > 0))),
    CONSTRAINT business_saved_report_views_recipe_check CHECK (((jsonb_typeof(recipe) = 'object'::text) AND ((recipe ->> 'schema_version'::text) = ANY (ARRAY['1'::text, '2'::text])))),
    CONSTRAINT business_saved_report_views_version_check CHECK ((version > 0))
);

COMMENT ON TABLE argus_private.business_saved_report_views IS 'Private validated query and column recipes. Current selected Business membership is checked by the service on every operation. No financial rows, report results or authority are stored.';

CREATE TABLE argus_private.business_workspace_assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    sha256 text NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_workspace_assets_height_check CHECK (((height >= 1) AND (height <= 1280))),
    CONSTRAINT business_workspace_assets_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT business_workspace_assets_width_check CHECK (((width >= 1) AND (width <= 1280)))
);

CREATE TABLE argus_private.business_workspace_commands (
    actor_id uuid NOT NULL,
    operation text NOT NULL,
    command_key text NOT NULL,
    payload jsonb NOT NULL,
    space_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_workspace_commands_command_key_check CHECK ((((char_length(command_key) >= 1) AND (char_length(command_key) <= 200)) AND (char_length(btrim(command_key)) > 0))),
    CONSTRAINT business_workspace_commands_operation_check CHECK ((operation = ANY (ARRAY['create'::text, 'save'::text, 'upload'::text]))),
    CONSTRAINT business_workspace_commands_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text))
);

COMMENT ON TABLE argus_private.business_workspace_commands IS 'Private atomic create/save replay records. Current membership is rechecked before replay; account deletion removes command metadata, not Business custody.';

CREATE TABLE argus_private.invite_code_digests (
    digest text NOT NULL,
    household_invitation_id uuid,
    beta_invitation_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    rehashed_at timestamp with time zone,
    CONSTRAINT invite_code_digests_check CHECK ((num_nonnulls(household_invitation_id, beta_invitation_id) = 1)),
    CONSTRAINT invite_code_digests_digest_check CHECK ((digest ~ '^v2\.[0-9a-f]{8}\.[0-9a-f]{64}$'::text))
);

COMMENT ON TABLE argus_private.invite_code_digests IS 'Keyed (HMAC-SHA-256) digests of typed invite codes. Backend only: no table grant to anon, authenticated or service_role (service_role has schema usage only), RLS on with no policy.';

CREATE TABLE public.apple_sign_in_credentials (
    user_id uuid NOT NULL,
    client_id text NOT NULL,
    secret_ciphertext bytea NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    secret_key_fingerprint text,
    apple_subject text,
    CONSTRAINT apple_sign_in_credentials_apple_subject_check CHECK (((apple_subject IS NULL) OR (((length(apple_subject) >= 1) AND (length(apple_subject) <= 512)) AND (apple_subject !~ '[[:space:][:cntrl:]]'::text)))),
    CONSTRAINT apple_sign_in_credentials_client_id_check CHECK ((client_id ~ '^[A-Za-z0-9][A-Za-z0-9.-]{0,154}$'::text)),
    CONSTRAINT apple_sign_in_credentials_secret_ciphertext_check CHECK (((octet_length(secret_ciphertext) >= 29) AND (octet_length(secret_ciphertext) <= 8192))),
    CONSTRAINT apple_sign_in_credentials_secret_key_fingerprint_check CHECK ((secret_key_fingerprint ~ '^[0-9a-f]{32}$'::text))
);

CREATE TABLE public.argus_memory_vectors (
    id uuid NOT NULL,
    vector public.vector(1024),
    payload jsonb
);

ALTER TABLE ONLY public.argus_memory_vectors FORCE ROW LEVEL SECURITY;

CREATE TABLE public.backtest_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    conversation_id uuid,
    strategy_id uuid,
    status text DEFAULT 'queued'::text NOT NULL,
    asset_class text NOT NULL,
    symbols text[] NOT NULL,
    allocation_method text DEFAULT 'equal_weight'::text NOT NULL,
    benchmark_symbol text NOT NULL,
    config_snapshot jsonb NOT NULL,
    metrics jsonb DEFAULT '{"aggregate": {}, "by_symbol": {}}'::jsonb NOT NULL,
    conversation_result_card jsonb DEFAULT '{}'::jsonb NOT NULL,
    chart jsonb,
    trades jsonb,
    error jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT backtest_runs_allocation_method_check CHECK ((allocation_method = 'equal_weight'::text)),
    CONSTRAINT backtest_runs_asset_class_check CHECK ((asset_class = ANY (ARRAY['equity'::text, 'crypto'::text, 'currency_pair'::text]))),
    CONSTRAINT backtest_runs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'completed'::text, 'failed'::text]))),
    CONSTRAINT backtest_runs_symbols_check CHECK (((array_length(symbols, 1) >= 1) AND (array_length(symbols, 1) <= 5)))
);

CREATE TABLE public.beta_admissions (
    user_id uuid NOT NULL,
    via text NOT NULL,
    referral_id uuid,
    admitted_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT beta_admissions_via_check CHECK ((via = ANY (ARRAY['beta_invitation'::text, 'group_link'::text, 'household_invitation'::text, 'existing_account'::text])))
);

CREATE TABLE public.beta_invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    token_hash text NOT NULL,
    created_by uuid,
    source_label text,
    max_uses integer NOT NULL,
    use_count integer DEFAULT 0 NOT NULL,
    overflow_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    CONSTRAINT beta_invitations_check CHECK ((expires_at > created_at)),
    CONSTRAINT beta_invitations_check1 CHECK ((use_count <= max_uses)),
    CONSTRAINT beta_invitations_check2 CHECK ((((kind = 'beta'::text) AND (max_uses = 1) AND (source_label IS NULL)) OR ((kind = 'group_link'::text) AND (source_label IS NOT NULL)))),
    CONSTRAINT beta_invitations_idempotency_key_check CHECK (((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 200))),
    CONSTRAINT beta_invitations_kind_check CHECK ((kind = ANY (ARRAY['beta'::text, 'group_link'::text]))),
    CONSTRAINT beta_invitations_max_uses_check CHECK (((max_uses >= 1) AND (max_uses <= 10000))),
    CONSTRAINT beta_invitations_overflow_count_check CHECK ((overflow_count >= 0)),
    CONSTRAINT beta_invitations_source_label_check CHECK (((source_label IS NULL) OR ((char_length(source_label) >= 1) AND (char_length(source_label) <= 80)))),
    CONSTRAINT beta_invitations_use_count_check CHECK ((use_count >= 0))
);

CREATE TABLE public.beta_invite_quota_grants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    granted_by uuid,
    extra integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    CONSTRAINT beta_invite_quota_grants_extra_check CHECK (((extra >= 1) AND (extra <= 1000))),
    CONSTRAINT beta_invite_quota_grants_idempotency_key_check CHECK (((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 200)))
);

CREATE TABLE public.business_access_invites (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    issuer_id uuid NOT NULL,
    email text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '7 days'::interval) NOT NULL,
    accepted_at timestamp with time zone,
    accepted_grant_id uuid,
    revoked_at timestamp with time zone,
    historical_issuer_id uuid,
    requested_role text DEFAULT 'editor'::text NOT NULL,
    recipient_id uuid,
    target_grant_id uuid,
    target_version bigint,
    supersedes_id uuid,
    delivery_state text DEFAULT 'pending'::text NOT NULL,
    CONSTRAINT business_access_invites_check CHECK ((expires_at > created_at)),
    CONSTRAINT business_access_invites_check1 CHECK (((accepted_at IS NULL) OR (revoked_at IS NULL))),
    CONSTRAINT business_access_invites_delivery_state_check CHECK ((delivery_state = ANY (ARRAY['pending'::text, 'accepted'::text, 'failed'::text, 'not_configured'::text, 'sending'::text, 'uncertain'::text]))),
    CONSTRAINT business_access_invites_email_check CHECK (((email = lower(email)) AND (POSITION(('@'::text) IN (email)) > 1) AND (length(email) <= 254))),
    CONSTRAINT business_access_invites_requested_role_check CHECK ((requested_role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text, 'viewer'::text]))),
    CONSTRAINT business_invite_target_version CHECK (((target_grant_id IS NULL) = (target_version IS NULL)))
);

COMMENT ON COLUMN public.business_access_invites.historical_issuer_id IS 'Anonymous former issuer. Does not grant access or link to a departed person.';

CREATE TABLE public.business_action_receipts (
    space_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    actor jsonb NOT NULL,
    idempotency_key text NOT NULL,
    input_hash text NOT NULL,
    command jsonb NOT NULL,
    turn_key text,
    action_index integer,
    outcome jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_action_receipts_access_human CHECK ((((command ->> 'action'::text) <> ALL (ARRAY['owner_grant'::text, 'grant_access'::text, 'invite_access'::text, 'accept_invite'::text, 'revoke_grant'::text, 'revoke_invite'::text])) OR ((((actor ->> 'actor_kind'::text) = 'member'::text) AND (turn_key IS NULL) AND (action_index IS NULL)) IS TRUE))),
    CONSTRAINT business_action_receipts_action_index_check CHECK ((action_index >= 0)),
    CONSTRAINT business_action_receipts_attachment_extractor CHECK ((((command ->> 'action'::text) IS DISTINCT FROM 'prepare_attachment'::text) OR ((((actor ->> 'actor_kind'::text) = 'extractor'::text) AND (turn_key IS NULL) AND (action_index IS NULL) AND (((command -> 'binding'::text) -> 'actor'::text) = actor) AND (((command -> 'binding'::text) ->> 'space_id'::text) = (space_id)::text) AND ((command ->> 'batch_sha256'::text) ~ '^[0-9a-f]{64}$'::text)) IS TRUE))),
    CONSTRAINT business_action_receipts_capture_human CHECK ((((command ->> 'action'::text) IS DISTINCT FROM 'capture_note'::text) OR ((((actor ->> 'actor_kind'::text) = 'member'::text) AND (turn_key IS NULL) AND (action_index IS NULL)) IS TRUE))),
    CONSTRAINT business_action_receipts_check CHECK ((((jsonb_typeof(actor) = 'object'::text) AND ((actor ->> 'actor_id'::text) = (actor_id)::text) AND ((actor ->> 'actor_kind'::text) = ANY (ARRAY['owner_via_agent'::text, 'member'::text, 'extractor'::text])) AND (jsonb_typeof((actor -> 'display_name'::text)) = 'string'::text) AND (jsonb_typeof((actor -> 'grant_id'::text)) = 'string'::text) AND (jsonb_typeof((actor -> 'issuer_id'::text)) = 'string'::text) AND (jsonb_typeof((actor -> 'issuer_display_name'::text)) = 'string'::text)) IS TRUE)),
    CONSTRAINT business_action_receipts_check1 CHECK (((turn_key IS NULL) = (action_index IS NULL))),
    CONSTRAINT business_action_receipts_command_check CHECK ((jsonb_typeof(command) = 'object'::text)),
    CONSTRAINT business_action_receipts_human_only_actions CHECK ((((command ->> 'action'::text) <> ALL (ARRAY['access_seen'::text, 'email_ai_consent_declined'::text, 'mark_personal'::text, 'decide_606'::text, 'receipt_upload'::text, 'receipt_review'::text, 'receipt_confirm'::text])) OR ((((actor ->> 'actor_kind'::text) = 'member'::text) AND (turn_key IS NULL) AND (action_index IS NULL)) IS TRUE))),
    CONSTRAINT business_action_receipts_idempotency_key_check CHECK (((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 80))),
    CONSTRAINT business_action_receipts_income_human CHECK ((((command ->> 'action'::text) IS DISTINCT FROM 'approve_income'::text) OR ((((actor ->> 'actor_kind'::text) = 'member'::text) AND (turn_key IS NULL) AND (action_index IS NULL)) IS TRUE))),
    CONSTRAINT business_action_receipts_input_hash_check CHECK ((input_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT business_action_receipts_outcome_check CHECK (((outcome IS NULL) OR (((jsonb_typeof(outcome) = 'object'::text) AND ((outcome ->> 'outcome'::text) = ANY (ARRAY['applied'::text, 'replayed'::text, 'stale_version'::text, 'not_found'::text, 'permission_denied'::text, 'invalid_input'::text, 'idempotency_conflict'::text, 'outcome_unknown'::text]))) IS TRUE))),
    CONSTRAINT business_action_receipts_rebind_human CHECK ((((command ->> 'action'::text) IS DISTINCT FROM 'rebind_attachment'::text) OR ((((actor ->> 'actor_kind'::text) = 'member'::text) AND (turn_key IS NULL) AND (action_index IS NULL) AND (((command -> 'binding'::text) ->> 'space_id'::text) = (space_id)::text)) IS TRUE))),
    CONSTRAINT business_action_receipts_settle_human CHECK ((((command ->> 'action'::text) IS DISTINCT FROM 'settle_remainder'::text) OR ((((actor ->> 'actor_kind'::text) = 'member'::text) AND (turn_key IS NULL) AND (action_index IS NULL)) IS TRUE))),
    CONSTRAINT business_action_receipts_unplanned_command CHECK (((turn_key IS NOT NULL) OR (((command ->> 'action'::text) = ANY (ARRAY['review_draft'::text, 'approve_expense'::text, 'capture_note'::text, 'approve_income'::text, 'prepare_attachment'::text, 'owner_grant'::text, 'grant_access'::text, 'invite_access'::text, 'accept_invite'::text, 'revoke_grant'::text, 'revoke_invite'::text, 'rebind_attachment'::text, 'settle_remainder'::text, 'access_seen'::text, 'email_ai_consent_declined'::text, 'mark_personal'::text, 'decide_606'::text, 'receipt_upload'::text, 'receipt_review'::text, 'receipt_confirm'::text, 'approve_refund'::text, 'set_business_rnc'::text, 'resolve_duplicate'::text, 'change_role'::text, 'edit_current_note'::text, 'append_supporting_file'::text, 'reopen_draft'::text, 'set_business_legal_name'::text])) IS TRUE))),
    CONSTRAINT business_annotation_human_commands CHECK ((((command ->> 'action'::text) <> ALL (ARRAY['edit_current_note'::text, 'append_supporting_file'::text])) OR ((((actor ->> 'actor_kind'::text) = 'member'::text) AND (turn_key IS NULL) AND (action_index IS NULL)) IS TRUE))),
    CONSTRAINT business_dgii_human_commands CHECK ((((command ->> 'action'::text) <> ALL (ARRAY['approve_refund'::text, 'set_business_rnc'::text])) OR ((((actor ->> 'actor_kind'::text) = 'member'::text) AND (turn_key IS NULL) AND (action_index IS NULL)) IS TRUE))),
    CONSTRAINT business_legal_name_human_commands CHECK ((((command ->> 'action'::text) <> 'set_business_legal_name'::text) OR ((((actor ->> 'actor_kind'::text) = 'member'::text) AND (turn_key IS NULL) AND (action_index IS NULL)) IS TRUE))),
    CONSTRAINT business_membership_role_human CHECK ((((command ->> 'action'::text) IS DISTINCT FROM 'change_role'::text) OR ((actor ->> 'actor_kind'::text) = 'member'::text)))
);

CREATE TABLE public.business_ai_consents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    consenting_actor_id uuid NOT NULL,
    grant_id uuid NOT NULL,
    issuer_id uuid NOT NULL,
    scope_version integer NOT NULL,
    purpose text NOT NULL,
    disclosure text NOT NULL,
    route jsonb NOT NULL,
    route_hash text NOT NULL,
    idempotency_key text NOT NULL,
    input_hash text NOT NULL,
    consented_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    invalidated_by_transfer_id uuid,
    CONSTRAINT business_ai_consent_revocation_origin CHECK ((((revoked_at IS NULL) AND (revoked_by IS NULL) AND (invalidated_by_transfer_id IS NULL)) OR ((revoked_at IS NOT NULL) AND (((revoked_by = owner_id) AND (invalidated_by_transfer_id IS NULL)) OR ((revoked_by IS NULL) AND (invalidated_by_transfer_id IS NOT NULL)))))),
    CONSTRAINT business_ai_consents_check CHECK ((consenting_actor_id = owner_id)),
    CONSTRAINT business_ai_consents_check2 CHECK (((revoked_by IS NULL) OR (revoked_by = owner_id))),
    CONSTRAINT business_ai_consents_check3 CHECK (((revoked_at IS NULL) OR (revoked_at >= consented_at))),
    CONSTRAINT business_ai_consents_disclosure_check CHECK (((char_length(disclosure) >= 1) AND (char_length(disclosure) <= 4000))),
    CONSTRAINT business_ai_consents_idempotency_key_check CHECK (((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 80))),
    CONSTRAINT business_ai_consents_input_hash_check CHECK ((input_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT business_ai_consents_purpose_check CHECK ((purpose = 'business_ai_receipt_reading'::text)),
    CONSTRAINT business_ai_consents_route_check CHECK (((jsonb_typeof(route) = 'object'::text) AND (route <> '{}'::jsonb))),
    CONSTRAINT business_ai_consents_route_hash_check CHECK ((route_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT business_ai_consents_scope_version_check CHECK ((scope_version = 1))
);

COMMENT ON COLUMN public.business_ai_consents.invalidated_by_transfer_id IS 'Automatic invalidation by an accepted ownership transfer. revoked_by is NULL because no person issued a consent-revocation command. Original consenting actor remains unchanged.';

CREATE TABLE public.business_bank_accounts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    account_id uuid NOT NULL,
    currency text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_bank_accounts_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text))
);

COMMENT ON TABLE public.business_bank_accounts IS 'One bank account per Business space. Keep for 10 years. No delete API.';

CREATE TABLE public.business_bank_imports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    bank_account_id uuid NOT NULL,
    reader_id text NOT NULL,
    source_sha256 text NOT NULL,
    idempotency_key text NOT NULL,
    inserted_count integer NOT NULL,
    unchanged_count integer NOT NULL,
    imported_by uuid,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_bank_imports_idempotency_key_check CHECK (((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 128))),
    CONSTRAINT business_bank_imports_inserted_count_check CHECK ((inserted_count >= 0)),
    CONSTRAINT business_bank_imports_reader_id_check CHECK ((reader_id = ANY (ARRAY['pilot_bank'::text, 'banco_popular'::text, 'bhd'::text, 'mercury'::text, 'sandbox_csv'::text, 'mapped_csv'::text]))),
    CONSTRAINT business_bank_imports_source_sha256_check CHECK ((char_length(source_sha256) = 64)),
    CONSTRAINT business_bank_imports_unchanged_count_check CHECK ((unchanged_count >= 0))
);

COMMENT ON TABLE public.business_bank_imports IS 'One accepted statement upload. Keep for 10 years. No delete API.';

CREATE TABLE public.business_bank_line_outcomes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    line_id uuid NOT NULL,
    kind text NOT NULL,
    target_kind text,
    target_id uuid,
    reason text,
    prior_status text,
    prior_settled_on date,
    prior_payment_method text,
    applied_status text,
    applied_settled_on date,
    applied_payment_method text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    create_key text NOT NULL,
    ended_by uuid,
    ended_at timestamp with time zone,
    end_key text,
    CONSTRAINT business_bank_line_outcomes_applied_payment_method_check CHECK ((applied_payment_method = ANY (ARRAY['efectivo'::text, 'transferencia'::text, 'tarjeta'::text, 'credito'::text, 'otro'::text]))),
    CONSTRAINT business_bank_line_outcomes_applied_status_check CHECK ((applied_status = ANY (ARRAY['cobrado'::text, 'pagado'::text]))),
    CONSTRAINT business_bank_line_outcomes_check CHECK (((ended_at IS NULL) = (end_key IS NULL))),
    CONSTRAINT business_bank_line_outcomes_check1 CHECK ((((kind = 'match'::text) AND (target_kind IS NOT NULL) AND (target_id IS NOT NULL) AND (reason IS NULL) AND (((target_kind = 'receipt'::text) AND (applied_status = 'pagado'::text)) OR ((target_kind = 'venta'::text) AND (applied_status = 'cobrado'::text))) AND (applied_settled_on IS NOT NULL) AND (applied_payment_method IS NOT NULL) AND (((prior_status = 'pendiente'::text) AND (prior_settled_on IS NULL) AND (prior_payment_method IS NULL)) OR ((prior_status = ANY (ARRAY['cobrado'::text, 'pagado'::text])) AND (prior_settled_on IS NOT NULL) AND (prior_payment_method IS NOT NULL)))) OR ((kind = 'no_receipt'::text) AND (reason IS NOT NULL) AND (target_kind IS NULL) AND (target_id IS NULL) AND (prior_status IS NULL) AND (prior_settled_on IS NULL) AND (prior_payment_method IS NULL) AND (applied_status IS NULL) AND (applied_settled_on IS NULL) AND (applied_payment_method IS NULL)))),
    CONSTRAINT business_bank_line_outcomes_create_key_check CHECK (((char_length(create_key) >= 1) AND (char_length(create_key) <= 128))),
    CONSTRAINT business_bank_line_outcomes_end_key_check CHECK (((char_length(end_key) >= 1) AND (char_length(end_key) <= 128))),
    CONSTRAINT business_bank_line_outcomes_kind_check CHECK ((kind = ANY (ARRAY['match'::text, 'no_receipt'::text]))),
    CONSTRAINT business_bank_line_outcomes_prior_payment_method_check CHECK ((prior_payment_method = ANY (ARRAY['efectivo'::text, 'transferencia'::text, 'tarjeta'::text, 'credito'::text, 'otro'::text]))),
    CONSTRAINT business_bank_line_outcomes_prior_status_check CHECK ((prior_status = ANY (ARRAY['pendiente'::text, 'cobrado'::text, 'pagado'::text]))),
    CONSTRAINT business_bank_line_outcomes_reason_check CHECK ((reason = ANY (ARRAY['cargo_banco'::text, 'entre_cuentas'::text, 'compra_informal'::text, 'personal'::text]))),
    CONSTRAINT business_bank_line_outcomes_target_kind_check CHECK ((target_kind = ANY (ARRAY['receipt'::text, 'venta'::text])))
);

COMMENT ON TABLE public.business_bank_line_outcomes IS 'One live outcome per bank line and one live match per document. Ending an outcome keeps the row. Keep with the Business record. No delete API.';

COMMENT ON COLUMN public.business_bank_line_outcomes.prior_status IS 'The document settlement before this match. Undoing the match writes it back.';

COMMENT ON COLUMN public.business_bank_line_outcomes.applied_status IS 'The settlement this match wrote. It stays the settlement while the match is live.';

CREATE TABLE public.business_bank_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    bank_account_id uuid NOT NULL,
    first_import_id uuid NOT NULL,
    occurred_on date NOT NULL,
    description text NOT NULL,
    normalized_description text NOT NULL,
    amount numeric(20,4) NOT NULL,
    currency text NOT NULL,
    raw_line jsonb NOT NULL,
    line_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_bank_lines_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT business_bank_lines_line_hash_check CHECK ((char_length(line_hash) = 64)),
    CONSTRAINT business_bank_lines_raw_line_check CHECK ((jsonb_typeof(raw_line) = 'object'::text))
);

COMMENT ON TABLE public.business_bank_lines IS 'Immutable raw statement lines. Keep for 10 years. No delete API. Re-import inserts or returns the existing row.';

COMMENT ON COLUMN public.business_bank_lines.raw_line IS 'The cells from the source row. Updates are refused.';

COMMENT ON COLUMN public.business_bank_lines.line_hash IS 'Hash of the raw cells plus the occurrence of that exact row in the file.';

CREATE TABLE public.business_bank_suggestions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    line_id uuid NOT NULL,
    target_kind text NOT NULL,
    target_id text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    amount_score numeric(4,3) NOT NULL,
    date_score numeric(4,3) NOT NULL,
    merchant_score numeric(4,3) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    decided_by uuid,
    decision_key text,
    CONSTRAINT business_bank_suggestions_amount_score_check CHECK (((amount_score >= (0)::numeric) AND (amount_score <= (1)::numeric))),
    CONSTRAINT business_bank_suggestions_check CHECK ((((status = 'pending'::text) AND (decided_at IS NULL) AND (decision_key IS NULL)) OR ((status = ANY (ARRAY['confirmed'::text, 'declined'::text])) AND (decided_at IS NOT NULL) AND (decision_key IS NOT NULL)))),
    CONSTRAINT business_bank_suggestions_date_score_check CHECK (((date_score >= (0)::numeric) AND (date_score <= (1)::numeric))),
    CONSTRAINT business_bank_suggestions_merchant_score_check CHECK (((merchant_score >= (0)::numeric) AND (merchant_score <= (1)::numeric))),
    CONSTRAINT business_bank_suggestions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'declined'::text]))),
    CONSTRAINT business_bank_suggestions_target_id_check CHECK (((char_length(target_id) >= 1) AND (char_length(target_id) <= 80))),
    CONSTRAINT business_bank_suggestions_target_kind_check CHECK ((target_kind = ANY (ARRAY['receipt'::text, 'venta'::text])))
);

COMMENT ON TABLE public.business_bank_suggestions IS 'One offer per line and target. Pending or declined. A declined row keeps that pair out of later offers. Accepting an offer adds a live business_bank_line_outcomes match; the offer row does not change. Score parts are the historical offer. Keep 10 years.';

CREATE TABLE public.business_client_grants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    grantee_id uuid NOT NULL,
    issuer_id uuid NOT NULL,
    capabilities text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    revoked_at timestamp with time zone,
    historical_issuer_id uuid,
    business_role text NOT NULL,
    membership_version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT business_client_grants_capabilities_check CHECK (((cardinality(capabilities) > 0) AND (capabilities <@ ARRAY['read'::text, 'prepare'::text, 'approve'::text]) AND (array_position(capabilities, NULL::text) IS NULL))),
    CONSTRAINT business_client_grants_check CHECK (((expires_at IS NULL) OR (expires_at > created_at))),
    CONSTRAINT business_client_grants_check1 CHECK (((revoked_at IS NULL) OR (revoked_at >= created_at))),
    CONSTRAINT business_membership_role CHECK ((business_role = ANY (ARRAY['owner'::text, 'admin'::text, 'editor'::text, 'viewer'::text])))
);

COMMENT ON COLUMN public.business_client_grants.historical_issuer_id IS 'Anonymous former issuer. Operational issuer alone supplies present authority.';

COMMENT ON COLUMN public.business_client_grants.business_role IS 'Canonical accepted membership role. Capabilities are its legacy wire projection.';

CREATE TABLE public.business_close_mail_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    space_id uuid NOT NULL,
    closed_at timestamp with time zone NOT NULL,
    owner_id uuid NOT NULL,
    recipient_id uuid NOT NULL,
    recipient_email text NOT NULL,
    context jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    first_attempt_at timestamp with time zone,
    payload jsonb,
    sent_at timestamp with time zone,
    suppressed_at timestamp with time zone,
    uncertain_at timestamp with time zone,
    provider_receipt text,
    CONSTRAINT business_close_mail_outbox_check CHECK (((first_attempt_at IS NULL) = (payload IS NULL))),
    CONSTRAINT business_close_mail_outbox_check1 CHECK (((sent_at IS NULL) OR (first_attempt_at IS NOT NULL))),
    CONSTRAINT business_close_mail_outbox_context_check CHECK ((jsonb_typeof(context) = 'object'::text)),
    CONSTRAINT business_close_mail_outbox_kind_check CHECK ((kind = ANY (ARRAY['member_closed'::text, 'owner_closed'::text, 'purge_reminder'::text, 'member_reopened'::text])))
);

COMMENT ON TABLE public.business_close_mail_outbox IS 'Personal close-notification transport, atomically queued with closure, reopening or the day-23 sweep. One event per close instant, recipient and kind. Delete on person departure or custody detachment; Business purge cascades. Never retained Business history.';

COMMENT ON COLUMN public.business_close_mail_outbox.kind IS 'member_closed: approved member notice. owner_closed, purge_reminder (day 23, with the reopen path) and member_reopened wait unsent, with no payload, until their copy is approved.';

CREATE TABLE public.business_consent_acceptances (
    user_id uuid NOT NULL,
    space_id uuid NOT NULL,
    copy_version text NOT NULL,
    accepted_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_consent_acceptances_copy_version_check CHECK ((copy_version ~ '^[0-9a-f]{16}$'::text))
);

CREATE TABLE public.business_customers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    data jsonb NOT NULL,
    archived boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_customers_data_check CHECK ((octet_length((data)::text) <= 16384)),
    CONSTRAINT business_customers_version_check CHECK ((version > 0))
);

CREATE TABLE public.business_dgii_export_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    activity_id uuid NOT NULL,
    form text NOT NULL,
    period text NOT NULL,
    actor_id uuid,
    exported_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_dgii_export_lines_form_check CHECK ((form = ANY (ARRAY['606'::text, '607'::text]))),
    CONSTRAINT business_dgii_export_lines_period_check CHECK ((period ~ '^[0-9]{6}$'::text))
);

CREATE TABLE public.business_document_settlement_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    activity_id uuid NOT NULL,
    actor_id uuid,
    previous_status text NOT NULL,
    previous_settled_on date,
    previous_payment_method text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_document_settlement_revi_previous_payment_method_check CHECK (((previous_payment_method IS NULL) OR (previous_payment_method = ANY (ARRAY['efectivo'::text, 'transferencia'::text, 'tarjeta'::text, 'credito'::text, 'otro'::text])))),
    CONSTRAINT business_document_settlement_revisions_check CHECK ((((previous_status = 'pendiente'::text) AND (previous_settled_on IS NULL) AND (previous_payment_method IS NULL)) OR ((previous_status = ANY (ARRAY['cobrado'::text, 'pagado'::text])) AND (previous_settled_on IS NOT NULL) AND (previous_payment_method IS NOT NULL)))),
    CONSTRAINT business_document_settlement_revisions_previous_status_check CHECK ((previous_status = ANY (ARRAY['pendiente'::text, 'cobrado'::text, 'pagado'::text])))
);

CREATE TABLE public.business_document_settlements (
    space_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    activity_id uuid NOT NULL,
    document_kind text NOT NULL,
    status text NOT NULL,
    settled_on date,
    payment_method text,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_document_settlements_check CHECK ((((document_kind = 'invoice'::text) AND (status = ANY (ARRAY['pendiente'::text, 'cobrado'::text]))) OR ((document_kind = 'receipt'::text) AND (status = ANY (ARRAY['pendiente'::text, 'pagado'::text]))))),
    CONSTRAINT business_document_settlements_check1 CHECK ((((status = 'pendiente'::text) AND (settled_on IS NULL) AND (payment_method IS NULL)) OR ((status = ANY (ARRAY['cobrado'::text, 'pagado'::text])) AND (settled_on IS NOT NULL) AND (payment_method IS NOT NULL)))),
    CONSTRAINT business_document_settlements_document_kind_check CHECK ((document_kind = ANY (ARRAY['invoice'::text, 'receipt'::text]))),
    CONSTRAINT business_document_settlements_payment_method_check CHECK (((payment_method IS NULL) OR (payment_method = ANY (ARRAY['efectivo'::text, 'transferencia'::text, 'tarjeta'::text, 'credito'::text, 'otro'::text])))),
    CONSTRAINT business_document_settlements_status_check CHECK ((status = ANY (ARRAY['pendiente'::text, 'cobrado'::text, 'pagado'::text])))
);

CREATE TABLE public.business_draft_revisions (
    space_id uuid NOT NULL,
    draft_id uuid NOT NULL,
    version integer NOT NULL,
    actor jsonb NOT NULL,
    before_facts jsonb,
    after_facts jsonb NOT NULL,
    source_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    turn_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    before_dgii jsonb,
    after_dgii jsonb,
    before_due_on date,
    after_due_on date,
    before_current_note text,
    after_current_note text,
    CONSTRAINT business_dgii_snapshot_objects CHECK ((((before_dgii IS NULL) OR (jsonb_typeof(before_dgii) = 'object'::text)) AND ((after_dgii IS NULL) OR (jsonb_typeof(after_dgii) = 'object'::text)))),
    CONSTRAINT business_draft_revisions_actor_check CHECK (((jsonb_typeof(actor) = 'object'::text) AND (actor ?& ARRAY['actor_id'::text, 'actor_kind'::text, 'display_name'::text, 'grant_id'::text, 'issuer_id'::text, 'issuer_display_name'::text]))),
    CONSTRAINT business_draft_revisions_after_facts_check CHECK ((jsonb_typeof(after_facts) = 'object'::text)),
    CONSTRAINT business_draft_revisions_before_facts_check CHECK ((jsonb_typeof(before_facts) = 'object'::text)),
    CONSTRAINT business_draft_revisions_current_note_length CHECK (((after_current_note IS NULL) OR (char_length(after_current_note) <= 500))),
    CONSTRAINT business_draft_revisions_version_check CHECK ((version >= 1))
);

COMMENT ON COLUMN public.business_draft_revisions.after_current_note IS 'Current-note replacement in Unicode code points. Null means no note edit; empty text explicitly clears. Financial facts remain unchanged.';

CREATE TABLE public.business_draft_sources (
    space_id uuid NOT NULL,
    draft_id uuid NOT NULL,
    source_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.business_email_address_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    actor_id uuid,
    event_type text NOT NULL,
    old_address text,
    new_address text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_email_address_events_event_type_check CHECK ((event_type = ANY (ARRAY['address_stopped'::text, 'address_changed'::text, 'sender_authorized'::text, 'sender_removed'::text, 'sender_blocked'::text]))),
    CONSTRAINT business_email_address_events_new_address_check CHECK (((new_address IS NULL) OR ((new_address = lower(new_address)) AND (length(new_address) <= 254)))),
    CONSTRAINT business_email_address_events_old_address_check CHECK (((old_address IS NULL) OR ((old_address = lower(old_address)) AND (length(old_address) <= 254))))
);

CREATE TABLE public.business_email_daily_usage (
    route_id uuid NOT NULL,
    day date NOT NULL,
    messages bigint DEFAULT 0 NOT NULL,
    bytes_used bigint DEFAULT 0 NOT NULL,
    CONSTRAINT business_email_daily_usage_bytes_used_check CHECK ((bytes_used >= 0)),
    CONSTRAINT business_email_daily_usage_messages_check CHECK ((messages >= 0))
);

CREATE TABLE public.business_email_deliveries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text NOT NULL,
    external_id text NOT NULL,
    recipients jsonb DEFAULT '[]'::jsonb NOT NULL,
    route_id uuid,
    space_id uuid,
    principal_id uuid,
    state text DEFAULT 'received'::text NOT NULL,
    original_document_id uuid,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_until timestamp with time zone,
    lease_token uuid,
    attempts integer DEFAULT 0 NOT NULL,
    error_code text,
    subject text,
    sender text,
    sent_at text,
    text_body text,
    budget_message_day date,
    budget_message_lease uuid,
    budget_fetch_day date,
    budget_fetch_token uuid,
    inbox_group text,
    auth_result text,
    review_note text,
    first_scan boolean DEFAULT false NOT NULL,
    approved boolean DEFAULT false NOT NULL,
    bounce_text text,
    cap_exempt boolean DEFAULT false NOT NULL,
    CONSTRAINT business_email_deliveries_auth_result CHECK (((auth_result IS NULL) OR (auth_result = ANY (ARRAY['aligned'::text, 'failed'::text, 'unknown'::text, 'ambiguous'::text, 'no_result'::text, 'none'::text])))),
    CONSTRAINT business_email_deliveries_check CHECK (((space_id IS NULL) = (principal_id IS NULL))),
    CONSTRAINT business_email_deliveries_check1 CHECK (((route_id IS NULL) OR (space_id IS NOT NULL))),
    CONSTRAINT business_email_deliveries_inbox_group CHECK (((inbox_group IS NULL) OR (inbox_group = ANY (ARRAY['bandeja'::text, 'remitentes_nuevos'::text])))),
    CONSTRAINT business_email_deliveries_not_approved CHECK ((approved = false)),
    CONSTRAINT business_email_deliveries_provider_check CHECK ((provider = 'resend'::text)),
    CONSTRAINT business_email_deliveries_state_check CHECK ((state = ANY (ARRAY['received'::text, 'processing'::text, 'partial'::text, 'captured'::text, 'rejected'::text])))
);

CREATE TABLE public.business_email_parts (
    delivery_id uuid NOT NULL,
    id text NOT NULL,
    filename text NOT NULL,
    media_type text NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    document_id uuid,
    error_code text,
    CONSTRAINT business_email_parts_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'captured'::text, 'rejected'::text])))
);

CREATE TABLE public.business_email_retired_aliases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    route_id uuid,
    alias_normalized text,
    recipient text NOT NULL,
    retired_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_email_retired_aliases_alias_normalized_check CHECK (((alias_normalized IS NULL) OR (alias_normalized ~ '^[a-z0-9-]{3,32}$'::text))),
    CONSTRAINT business_email_retired_aliases_recipient_check CHECK (((recipient = lower(recipient)) AND (length(recipient) <= 254)))
);

CREATE TABLE public.business_email_routes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    recipient text NOT NULL,
    space_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    granted_by uuid NOT NULL,
    grant_id uuid NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    alias text,
    alias_normalized text,
    review_required boolean DEFAULT false NOT NULL,
    CONSTRAINT business_email_routes_alias_shape CHECK (((alias IS NULL) OR ((alias = lower(alias)) AND (alias = alias_normalized) AND (alias ~ '^[a-z0-9-]{3,32}$'::text)))),
    CONSTRAINT business_email_routes_recipient_check CHECK (((recipient = lower(recipient)) AND (length(recipient) <= 254)))
);

CREATE TABLE public.business_email_senders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    kind text NOT NULL,
    value text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    first_scan_at timestamp with time zone,
    last_auth_result text,
    last_seen_at timestamp with time zone,
    CONSTRAINT business_email_senders_kind_check CHECK ((kind = ANY (ARRAY['address'::text, 'domain'::text]))),
    CONSTRAINT business_email_senders_last_auth_result CHECK (((last_auth_result IS NULL) OR (last_auth_result = ANY (ARRAY['aligned'::text, 'failed'::text, 'unknown'::text, 'ambiguous'::text, 'no_result'::text, 'none'::text])))),
    CONSTRAINT business_email_senders_status CHECK ((status = ANY (ARRAY['authorized'::text, 'blocked'::text, 'pending'::text]))),
    CONSTRAINT business_email_senders_value_check CHECK (((value = lower(value)) AND ((length(value) >= 3) AND (length(value) <= 254))))
);

CREATE TABLE public.business_fiscal_observations (
    id bigint NOT NULL,
    space_id uuid,
    operation_id uuid,
    event_digest text NOT NULL,
    source text NOT NULL,
    disposition text NOT NULL,
    evidence jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_fiscal_observations_check CHECK (((operation_id IS NULL) = (space_id IS NULL))),
    CONSTRAINT business_fiscal_observations_check1 CHECK (((operation_id IS NULL) = (disposition = 'quarantined'::text))),
    CONSTRAINT business_fiscal_observations_disposition_check CHECK ((disposition = ANY (ARRAY['applied'::text, 'quarantined'::text]))),
    CONSTRAINT business_fiscal_observations_event_digest_check CHECK ((event_digest ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT business_fiscal_observations_evidence_check CHECK ((octet_length((evidence)::text) <= 16384)),
    CONSTRAINT business_fiscal_observations_source_check CHECK ((source = ANY (ARRAY['response'::text, 'callback'::text, 'poll'::text, 'artifact'::text, 'unknown'::text, 'conflict'::text])))
);

COMMENT ON TABLE public.business_fiscal_observations IS 'Server-only bounded semantic evidence. Authenticated unmatched callbacks remain quarantined. Private artifact locators never reach API output. No raw callback or free-text diagnostic payload.';

ALTER TABLE public.business_fiscal_observations ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.business_fiscal_observations_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.business_fiscal_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    environment text DEFAULT 'sandbox'::text NOT NULL,
    document_key text NOT NULL,
    account_key text NOT NULL,
    company_id text NOT NULL,
    issuer text NOT NULL,
    kind text NOT NULL,
    number text NOT NULL,
    case_data jsonb NOT NULL,
    payload_digest text NOT NULL,
    prepared_actor jsonb NOT NULL,
    approved_actor jsonb,
    contact_token uuid,
    contacted_at timestamp with time zone,
    provider_id text,
    attempts integer DEFAULT 0 NOT NULL,
    next_check timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    lease_token uuid,
    lease_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_fiscal_operations_attempts_check CHECK (((attempts >= 0) AND (attempts <= 20))),
    CONSTRAINT business_fiscal_operations_case_data_check CHECK ((octet_length((case_data)::text) <= 65536)),
    CONSTRAINT business_fiscal_operations_check CHECK (((contact_token IS NULL) = (contacted_at IS NULL))),
    CONSTRAINT business_fiscal_operations_check1 CHECK (((contact_token IS NULL) = (approved_actor IS NULL))),
    CONSTRAINT business_fiscal_operations_check2 CHECK (((provider_id IS NULL) OR (contact_token IS NOT NULL))),
    CONSTRAINT business_fiscal_operations_environment_check CHECK ((environment = 'sandbox'::text)),
    CONSTRAINT business_fiscal_operations_kind_check CHECK ((kind = ANY (ARRAY['E31'::text, 'E32'::text]))),
    CONSTRAINT business_fiscal_operations_number_check CHECK ((number ~ '^E3[12][0-9]{10}$'::text)),
    CONSTRAINT business_fiscal_operations_payload_digest_check CHECK ((payload_digest ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT business_fiscal_operations_provider_id_check CHECK ((length(provider_id) <= 120))
);

COMMENT ON TABLE public.business_fiscal_operations IS 'Synthetic sandbox intent only. Committed contact is permanent; unknown never authorizes create. No financial ledger effect. Business purge cascades; actor provenance follows audited custody.';

CREATE TABLE public.business_guide_dismissals (
    user_id uuid NOT NULL,
    card_id text NOT NULL,
    dismissed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_guide_dismissals_card_id_check CHECK ((card_id ~ '^[a-z0-9-]{1,64}$'::text))
);

CREATE TABLE public.business_invoice_commands (
    space_id uuid NOT NULL,
    command_key text NOT NULL,
    request_digest text NOT NULL,
    result jsonb NOT NULL,
    CONSTRAINT business_invoice_commands_command_key_check CHECK (((length(command_key) >= 1) AND (length(command_key) <= 128))),
    CONSTRAINT business_invoice_commands_request_digest_check CHECK ((request_digest ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT business_invoice_commands_result_check CHECK ((octet_length((result)::text) <= 131072))
);

CREATE TABLE public.business_invoice_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    version integer NOT NULL,
    customer_id uuid,
    amounts jsonb,
    data jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_invoice_revisions_data_check CHECK ((octet_length((data)::text) <= 65536)),
    CONSTRAINT business_invoice_revisions_version_check CHECK ((version > 0))
);

CREATE TABLE public.business_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    operation_id uuid,
    issue_snapshot jsonb,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_invoices_check CHECK (((operation_id IS NULL) = (issue_snapshot IS NULL))),
    CONSTRAINT business_invoices_version_check CHECK ((version > 0))
);

CREATE TABLE public.business_lifecycle_commands (
    space_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    action text NOT NULL,
    confirmation text,
    result_closed_at timestamp with time zone,
    result_name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_lifecycle_action_check CHECK ((((action = 'close'::text) AND (confirmation IS NOT NULL) AND (confirmation = result_name) AND (result_closed_at IS NOT NULL)) OR ((action = 'reopen'::text) AND (confirmation IS NULL) AND (result_closed_at IS NULL)))),
    CONSTRAINT business_lifecycle_commands_result_name_check CHECK (((char_length(result_name) >= 1) AND (char_length(result_name) <= 80))),
    CONSTRAINT business_lifecycle_key_check CHECK ((((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 200)) AND (char_length(btrim(idempotency_key)) > 0)))
);

COMMENT ON TABLE public.business_lifecycle_commands IS 'Original owner close/reopen command results for scoped idempotency. Current state remains spaces.closed_at; grants remain unchanged. Retained until the owning Business is deleted.';

CREATE TABLE public.business_logos (
    space_id uuid NOT NULL,
    sha256 text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_logos_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text))
);

COMMENT ON TABLE public.business_logos IS 'The Business has a logo at business/{space_id}/256.webp in the private profile-images bucket; served as signed URLs by the API.';

CREATE TABLE public.business_notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    recipient_user_id uuid NOT NULL,
    kind text NOT NULL,
    subject_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    read_at timestamp with time zone,
    resolved_at timestamp with time zone,
    CONSTRAINT business_notifications_kind_check CHECK ((kind = ANY (ARRAY['invitation_received'::text, 'new_sender_waiting'::text])))
);

CREATE TABLE public.business_ownership_transfers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    target_id uuid NOT NULL,
    target_grant_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    confirmation text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    resolved_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT business_ownership_transfers_check CHECK ((owner_id <> target_id)),
    CONSTRAINT business_ownership_transfers_check1 CHECK (((status = 'pending'::text) = (resolved_at IS NULL))),
    CONSTRAINT business_ownership_transfers_confirmation_check CHECK (((char_length(confirmation) >= 1) AND (char_length(confirmation) <= 80))),
    CONSTRAINT business_ownership_transfers_idempotency_key_check CHECK ((((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 200)) AND (char_length(btrim(idempotency_key)) > 0))),
    CONSTRAINT business_ownership_transfers_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'cancelled'::text, 'declined'::text, 'expired'::text]))),
    CONSTRAINT business_transfer_seven_days CHECK ((expires_at = (created_at + '168:00:00'::interval)))
);

COMMENT ON TABLE public.business_ownership_transfers IS 'Server-only pending and terminal ownership commands. Historical actor IDs require deletion anonymization before account deletion can be enabled.';

COMMENT ON COLUMN public.business_ownership_transfers.expires_at IS 'Immutable deadline exactly 168 hours after created_at. GET computes expiry without writing. No expiry mail.';

CREATE TABLE public.business_questions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    draft_id uuid NOT NULL,
    field text NOT NULL,
    asked_of text NOT NULL,
    channel text NOT NULL,
    state text NOT NULL,
    prompt text NOT NULL,
    allowed_answers text[] NOT NULL,
    answer_source_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_questions_allowed_answers_check CHECK (((cardinality(allowed_answers) > 0) AND (allowed_answers <@ ARRAY['known'::text, 'owner_does_not_know'::text]) AND (array_position(allowed_answers, NULL::text) IS NULL))),
    CONSTRAINT business_questions_asked_of_check CHECK ((asked_of = ANY (ARRAY['owner'::text, 'accountant'::text]))),
    CONSTRAINT business_questions_channel_check CHECK ((channel = ANY (ARRAY['web'::text, 'whatsapp'::text]))),
    CONSTRAINT business_questions_check CHECK (((state <> ALL (ARRAY['answered'::text, 'owner_does_not_know'::text])) OR (answer_source_id IS NOT NULL))),
    CONSTRAINT business_questions_check1 CHECK (((state <> 'owner_does_not_know'::text) OR (asked_of = 'accountant'::text))),
    CONSTRAINT business_questions_field_check CHECK ((field = ANY (ARRAY['kind'::text, 'amount'::text, 'currency'::text, 'occurred_on'::text, 'counterparty'::text, 'funding'::text, 'business_share'::text, 'receipt_state'::text, 'category_id'::text]))),
    CONSTRAINT business_questions_prompt_check CHECK (((char_length(prompt) >= 1) AND (char_length(prompt) <= 500))),
    CONSTRAINT business_questions_state_check CHECK ((state = ANY (ARRAY['open'::text, 'answered'::text, 'owner_does_not_know'::text, 'waiting_for_window'::text, 'withdrawn'::text])))
);

CREATE TABLE public.business_read_daily_usage (
    business_id uuid NOT NULL,
    day date NOT NULL,
    reads integer DEFAULT 0 NOT NULL,
    CONSTRAINT business_read_daily_usage_reads_check CHECK ((reads >= 0))
);

CREATE TABLE public.business_receipt_activity_baseline (
    singleton boolean DEFAULT true NOT NULL,
    established_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_receipt_activity_baseline_singleton_check CHECK (singleton)
);

CREATE TABLE public.business_receipt_consent_commands (
    space_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT business_receipt_consent_commands_idempotency_key_check CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 80))),
    CONSTRAINT business_receipt_consent_commands_request_hash_check CHECK ((length(request_hash) = 64))
);

