    revoked_at timestamp with time zone,
    CONSTRAINT business_receipt_reading_consents_check CHECK (((revoked_at IS NULL) OR (revoked_at >= consented_at))),
    CONSTRAINT business_receipt_reading_consents_disclosure_check CHECK (((length(disclosure) >= 1) AND (length(disclosure) <= 2000))),
    CONSTRAINT business_receipt_reading_consents_idempotency_key_check CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 80))),
    CONSTRAINT business_receipt_reading_consents_request_hash_check CHECK ((length(request_hash) = 64)),
    CONSTRAINT business_receipt_reading_consents_scope_version_check CHECK ((scope_version = ANY (ARRAY[1, 2, 3])))
);

