    CONSTRAINT business_sender_leases_sender_hash_check CHECK ((sender_hash ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE public.business_sources (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    space_id uuid NOT NULL,
    kind text NOT NULL,
    channel text NOT NULL,
    source_key text NOT NULL,
    text_content text,
    connection_id uuid,
    received_at timestamp with time zone NOT NULL,
    origin text DEFAULT 'direct'::text NOT NULL,
    CONSTRAINT business_sources_channel_check CHECK ((channel = ANY (ARRAY['web'::text, 'whatsapp'::text]))),
    CONSTRAINT business_sources_check CHECK (((kind <> 'web_action'::text) OR (channel = 'web'::text))),
    CONSTRAINT business_sources_check1 CHECK ((((kind = 'attachment'::text) AND (connection_id IS NOT NULL) AND (text_content IS NULL)) OR (((kind = ANY (ARRAY['message'::text, 'agent_proposal'::text, 'web_action'::text])) AND (connection_id IS NULL) AND ((char_length(text_content) >= 1) AND (char_length(text_content) <= 20000))) IS TRUE))),
    CONSTRAINT business_sources_kind_check CHECK ((kind = ANY (ARRAY['message'::text, 'attachment'::text, 'agent_proposal'::text, 'web_action'::text]))),
    CONSTRAINT business_sources_origin_check CHECK ((origin = ANY (ARRAY['email'::text, 'direct'::text]))),
    CONSTRAINT business_sources_source_key_check CHECK (((char_length(source_key) >= 1) AND (char_length(source_key) <= 200)))
);

CREATE TABLE public.business_transfer_mail_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    transfer_id uuid NOT NULL,
    variant text NOT NULL,
    recipient_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    target_id uuid NOT NULL,
    recipient_email text NOT NULL,
    context jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    first_attempt_at timestamp with time zone,
    payload jsonb,
    sent_at timestamp with time zone,
    suppressed_at timestamp with time zone,
    uncertain_at timestamp with time zone,
    provider_receipt text,
    CONSTRAINT business_transfer_mail_outbox_check CHECK (((first_attempt_at IS NULL) = (payload IS NULL))),
    CONSTRAINT business_transfer_mail_outbox_check1 CHECK (((sent_at IS NULL) OR (first_attempt_at IS NOT NULL))),
    CONSTRAINT business_transfer_mail_outbox_context_check CHECK ((jsonb_typeof(context) = 'object'::text)),
    CONSTRAINT business_transfer_mail_outbox_variant_check CHECK ((variant = ANY (ARRAY['requested'::text, 'declined'::text, 'acceptedOwner'::text, 'acceptedTarget'::text, 'withdrawn'::text])))
);

COMMENT ON TABLE public.business_transfer_mail_outbox IS 'Server-only personal notification transport. Delete for outgoing actors before custody anonymization; never canonical Business history. One event per recipient. First attempt and frozen payload survive provider ambiguity.';

CREATE TABLE public.business_turns (
    turn_key text NOT NULL,
    space_id uuid NOT NULL,
    sender_hash text NOT NULL,
    actor_id uuid NOT NULL,
    arrival_sequence bigint NOT NULL,
    phase text DEFAULT 'captured'::text NOT NULL,
    model_state text DEFAULT 'not_started'::text NOT NULL,
    plan jsonb,
    plan_actor jsonb,
    lease_fence bigint,
    reply_text text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_turns_check CHECK (((model_state = 'completed'::text) = (plan IS NOT NULL))),
    CONSTRAINT business_turns_check1 CHECK (((plan IS NULL) = (plan_actor IS NULL))),
    CONSTRAINT business_turns_check2 CHECK (((plan_actor IS NULL) OR (((jsonb_typeof(plan_actor) = 'object'::text) AND ((plan_actor ->> 'actor_id'::text) = (actor_id)::text) AND ((plan_actor ->> 'actor_kind'::text) = ANY (ARRAY['owner_via_agent'::text, 'member'::text, 'extractor'::text])) AND (jsonb_typeof((plan_actor -> 'display_name'::text)) = 'string'::text) AND (jsonb_typeof((plan_actor -> 'grant_id'::text)) = 'string'::text) AND (jsonb_typeof((plan_actor -> 'issuer_id'::text)) = 'string'::text) AND (jsonb_typeof((plan_actor -> 'issuer_display_name'::text)) = 'string'::text)) IS TRUE))),
    CONSTRAINT business_turns_check3 CHECK (((phase <> ALL (ARRAY['turn_done'::text, 'reply_pending'::text, 'reply_sent'::text, 'reply_unknown'::text])) OR (plan IS NOT NULL))),
    CONSTRAINT business_turns_lease_fence_check CHECK ((lease_fence >= 1)),
    CONSTRAINT business_turns_model_state_check CHECK ((model_state = ANY (ARRAY['not_started'::text, 'running'::text, 'completed'::text, 'unknown'::text]))),
    CONSTRAINT business_turns_phase_check CHECK ((phase = ANY (ARRAY['captured'::text, 'turn_running'::text, 'turn_done'::text, 'reply_pending'::text, 'reply_sent'::text, 'reply_unknown'::text]))),
    CONSTRAINT business_turns_plan_check CHECK (((plan IS NULL) OR (((jsonb_typeof(plan) = 'object'::text) AND ((plan ->> 'schema_version'::text) = '1'::text) AND (jsonb_typeof((plan -> 'actions'::text)) = 'array'::text) AND (jsonb_array_length((plan -> 'actions'::text)) <= 8)) IS TRUE))),
    CONSTRAINT business_turns_sender_hash_check CHECK ((sender_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT business_turns_turn_key_check CHECK (((char_length(turn_key) >= 1) AND (char_length(turn_key) <= 200)))
);

ALTER TABLE public.business_turns ALTER COLUMN arrival_sequence ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.business_turns_arrival_sequence_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.business_whatsapp_ai_consents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sender_link_id uuid NOT NULL,
    space_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    sender_hash bytea NOT NULL,
    consenting_actor_id uuid NOT NULL,
    grant_id uuid NOT NULL,
    issuer_id uuid NOT NULL,
    scope_version integer NOT NULL,
    purpose text NOT NULL,
    disclosure text NOT NULL,
    route jsonb NOT NULL,
    route_hash text NOT NULL,
    idempotency_key text NOT NULL,
    input_hash text NOT NULL,
    consented_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    CONSTRAINT business_whatsapp_ai_consents_check1 CHECK (((revoked_at IS NULL) = (revoked_by IS NULL))),
    CONSTRAINT business_whatsapp_ai_consents_check3 CHECK (((revoked_at IS NULL) OR (revoked_at >= consented_at))),
    CONSTRAINT business_whatsapp_ai_consents_disclosure_check CHECK (((char_length(disclosure) >= 1) AND (char_length(disclosure) <= 4000))),
    CONSTRAINT business_whatsapp_ai_consents_idempotency_key_check CHECK (((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 80))),
    CONSTRAINT business_whatsapp_ai_consents_input_hash_check CHECK ((input_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT business_whatsapp_ai_consents_route_check CHECK (((jsonb_typeof(route) = 'object'::text) AND (route <> '{}'::jsonb))),
    CONSTRAINT business_whatsapp_ai_consents_route_hash_check CHECK ((route_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT business_whatsapp_ai_consents_sender_hash_check CHECK ((octet_length(sender_hash) = 32)),
    CONSTRAINT business_whatsapp_consent_purpose_allowed CHECK ((purpose = ANY (ARRAY['business_whatsapp_draft_assistance'::text, 'business_whatsapp_receipt_reading'::text]))),
    CONSTRAINT business_whatsapp_consent_scope_allowed CHECK ((scope_version = ANY (ARRAY[1, 2]))),
    CONSTRAINT business_whatsapp_consent_scope_purpose_pair CHECK ((((scope_version = 1) AND (purpose = 'business_whatsapp_draft_assistance'::text)) OR ((scope_version = 2) AND (purpose = 'business_whatsapp_receipt_reading'::text)))),
    CONSTRAINT business_whatsapp_historical_actor CHECK (argus_private.business_custody_asset_actor(owner_id, consenting_actor_id)),
    CONSTRAINT business_whatsapp_historical_revoker CHECK (((revoked_by IS NULL) OR argus_private.business_custody_asset_actor(owner_id, revoked_by)))
);

CREATE TABLE public.chat_turn_lifecycles (
    turn_id uuid NOT NULL,
    user_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    assistant_message_id uuid,
    request_id text NOT NULL,
    status text DEFAULT 'accepted'::text NOT NULL,
    reconciled_outcome text,
    failure_code text,
    retryable boolean DEFAULT false NOT NULL,
    accepted_at timestamp with time zone DEFAULT now() NOT NULL,
    running_at timestamp with time zone,
    terminal_at timestamp with time zone,
    reconciled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chat_turn_lifecycles_abandoned_shape_check CHECK (((status <> 'abandoned'::text) OR ((assistant_message_id IS NULL) AND (failure_code = 'turn_abandoned'::text) AND (retryable = true)))),
    CONSTRAINT chat_turn_lifecycles_reconciled_outcome_check CHECK ((((status = 'reconciled'::text) AND (reconciled_outcome = ANY (ARRAY['completed'::text, 'recoverable_failed'::text]))) OR ((status <> 'reconciled'::text) AND (reconciled_outcome IS NULL)))),
    CONSTRAINT chat_turn_lifecycles_request_id_check CHECK ((NULLIF(btrim(request_id), ''::text) IS NOT NULL)),
    CONSTRAINT chat_turn_lifecycles_status_check CHECK ((status = ANY (ARRAY['accepted'::text, 'running'::text, 'completed'::text, 'recoverable_failed'::text, 'abandoned'::text, 'reconciled'::text]))),
    CONSTRAINT chat_turn_lifecycles_timestamp_shape_check CHECK ((((status = 'accepted'::text) AND (running_at IS NULL) AND (terminal_at IS NULL) AND (reconciled_at IS NULL)) OR ((status = 'running'::text) AND (running_at IS NOT NULL) AND (terminal_at IS NULL) AND (reconciled_at IS NULL)) OR ((status = ANY (ARRAY['completed'::text, 'recoverable_failed'::text, 'abandoned'::text])) AND (terminal_at IS NOT NULL) AND (reconciled_at IS NULL)) OR ((status = 'reconciled'::text) AND (terminal_at IS NOT NULL) AND (reconciled_at IS NOT NULL))))
);

