    upstream_id text,
    usage_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    input_tokens integer,
    output_tokens integer,
    total_tokens integer,
    billable_unit text DEFAULT 'unknown'::text NOT NULL,
    billable_quantity numeric(20,6),
    cost_amount numeric(18,8),
    cost_currency text DEFAULT 'USD'::text NOT NULL,
