    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT cost_ledger_entries_billable_quantity_check CHECK (((billable_quantity IS NULL) OR (billable_quantity >= (0)::numeric))),
    CONSTRAINT cost_ledger_entries_billable_unit_check CHECK ((billable_unit = ANY (ARRAY['token'::text, 'request'::text, 'compute_second'::text, 'audio_second'::text, 'storage_byte'::text, 'row'::text, 'unknown'::text]))),
    CONSTRAINT cost_ledger_entries_cost_amount_check CHECK (((cost_amount IS NULL) OR (cost_amount >= (0)::numeric))),
    CONSTRAINT cost_ledger_entries_cost_source_check CHECK ((cost_source = ANY (ARRAY['provider_reported'::text, 'estimated'::text, 'derived'::text, 'reconciled'::text, 'unavailable'::text]))),
    CONSTRAINT cost_ledger_entries_input_tokens_check CHECK (((input_tokens IS NULL) OR (input_tokens >= 0))),
    CONSTRAINT cost_ledger_entries_latency_ms_check CHECK (((latency_ms IS NULL) OR (latency_ms >= 0))),
    CONSTRAINT cost_ledger_entries_output_tokens_check CHECK (((output_tokens IS NULL) OR (output_tokens >= 0))),
    CONSTRAINT cost_ledger_entries_source_check CHECK ((source = ANY (ARRAY['api_turn'::text, 'render_workflow'::text, 'eval_harness'::text, 'manual_reconciliation'::text, 'runtime_compute'::text, 'storage'::text, 'market_data'::text, 'stt'::text, 'research'::text]))),
    CONSTRAINT cost_ledger_entries_status_check CHECK ((status = ANY (ARRAY['succeeded'::text, 'failed'::text, 'skipped'::text, 'estimated'::text, 'reconciled'::text]))),
    CONSTRAINT cost_ledger_entries_status_required CHECK (((status IS NOT NULL) OR ((source = 'research'::text) AND (feature_area = 'research_rail'::text)))),
    CONSTRAINT cost_ledger_entries_total_tokens_check CHECK (((total_tokens IS NULL) OR (total_tokens >= 0)))
);

