CREATE TABLE public.financial_document_extractions (
    connection_id uuid NOT NULL,
    user_id uuid NOT NULL,
    batch jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    source_bytes bytea,
    draft jsonb,
    source_bucket text,
    source_path text,
    source_media_type text,
    source_size_bytes integer,
    source_sha256 text,
    preparation_job jsonb,
    preparation_binding jsonb,
    rebuilt_bucket text,
    rebuilt_path text,
    rebuilt_media_type text,
    rebuilt_size_bytes integer,
    rebuilt_sha256 text,
    CONSTRAINT financial_document_extractions_batch_check CHECK ((jsonb_typeof(batch) = 'object'::text)),
    CONSTRAINT financial_document_extractions_draft_check CHECK ((jsonb_typeof(draft) = 'object'::text)),
    CONSTRAINT financial_document_extractions_not_empty CHECK (((batch IS NOT NULL) OR (draft IS NOT NULL))),
    CONSTRAINT financial_document_extractions_one_source CHECK (((source_bytes IS NULL) OR (source_path IS NULL))),
    CONSTRAINT financial_document_extractions_preparation_job_check CHECK (((preparation_job IS NULL) OR (jsonb_typeof(preparation_job) = 'object'::text))),
    CONSTRAINT financial_document_extractions_rebuilt_object CHECK ((num_nulls(rebuilt_bucket, rebuilt_path, rebuilt_media_type, rebuilt_size_bytes, rebuilt_sha256) = ANY (ARRAY[0, 5]))),
    CONSTRAINT financial_document_extractions_rebuilt_path CHECK (((rebuilt_path IS NULL) OR ((rebuilt_bucket = 'financial-document-sources'::text) AND (rebuilt_sha256 ~ '^[0-9a-f]{64}$'::text) AND (draft IS NOT NULL) AND ((draft ->> 'sha256'::text) IS NOT NULL) AND ((draft ->> 'sha256'::text) ~ '^[0-9a-f]{64}$'::text) AND (rebuilt_path = ((('rebuilt/'::text || (user_id)::text) || '/'::text) || (draft ->> 'sha256'::text))) AND (rebuilt_media_type = ANY (ARRAY['application/pdf'::text, 'image/jpeg'::text, 'image/png'::text, 'text/plain'::text, 'text/csv'::text, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'::text, 'application/xml'::text, 'text/xml'::text, 'message/rfc822'::text])) AND ((rebuilt_size_bytes >= 1) AND (rebuilt_size_bytes <= 10485760))))),
    CONSTRAINT financial_document_extractions_source_bytes_check CHECK (((octet_length(source_bytes) >= 1) AND (octet_length(source_bytes) <= 10485760))),
    CONSTRAINT financial_document_extractions_source_has_draft CHECK ((((source_bytes IS NULL) AND (source_path IS NULL)) OR (draft IS NOT NULL))),
    CONSTRAINT financial_document_extractions_source_object CHECK ((num_nulls(source_bucket, source_path, source_media_type, source_size_bytes, source_sha256) = ANY (ARRAY[0, 5]))),
    CONSTRAINT financial_document_extractions_source_object_path CHECK (((source_path IS NULL) OR ((source_bucket = 'financial-document-sources'::text) AND (source_sha256 ~ '^[0-9a-f]{64}$'::text) AND ((source_path = (((((user_id)::text || '/'::text) || (connection_id)::text) || '/'::text) || source_sha256)) OR (source_path = ((('sealed/'::text || (user_id)::text) || '/'::text) || source_sha256))) AND (source_media_type = ANY (ARRAY['application/pdf'::text, 'image/jpeg'::text, 'image/png'::text, 'text/plain'::text, 'text/csv'::text, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'::text, 'application/xml'::text, 'text/xml'::text, 'message/rfc822'::text])) AND ((source_size_bytes >= 1) AND (source_size_bytes <= 10485760))))),
    CONSTRAINT financial_document_preparation_binding_shape CHECK (((preparation_binding IS NULL) OR (((jsonb_typeof(preparation_binding) = 'object'::text) AND ((preparation_binding -> 'schema_version'::text) = '1'::jsonb) AND (preparation_binding ?& ARRAY['binding_id'::text, 'space_id'::text, 'owner_id'::text, 'connection_id'::text, 'source_sha256'::text, 'actor'::text, 'target'::text, 'consent'::text, 'captured_at'::text]) AND (jsonb_typeof((preparation_binding -> 'binding_id'::text)) = 'string'::text) AND (jsonb_typeof((preparation_binding -> 'captured_at'::text)) = 'string'::text) AND (jsonb_typeof((preparation_binding -> 'source_sha256'::text)) = 'string'::text) AND ((preparation_binding ->> 'connection_id'::text) = (connection_id)::text) AND ((preparation_binding ->> 'owner_id'::text) = (user_id)::text) AND ((preparation_binding ->> 'source_sha256'::text) ~ '^[0-9a-f]{64}$'::text) AND ((preparation_binding -> 'consent'::text) = 'true'::jsonb) AND (jsonb_typeof((preparation_binding -> 'actor'::text)) = 'object'::text) AND (((preparation_binding -> 'actor'::text) ->> 'actor_kind'::text) = 'extractor'::text) AND (jsonb_typeof(((preparation_binding -> 'actor'::text) -> 'display_name'::text)) = 'string'::text) AND (jsonb_typeof(((preparation_binding -> 'actor'::text) -> 'issuer_display_name'::text)) = 'string'::text) AND (((preparation_binding -> 'target'::text) = 'null'::jsonb) OR ((jsonb_typeof((preparation_binding -> 'target'::text)) = 'object'::text) AND ((preparation_binding -> 'target'::text) ?& ARRAY['draft_id'::text, 'version'::text]) AND (jsonb_typeof(((preparation_binding -> 'target'::text) -> 'version'::text)) = 'number'::text) AND (((preparation_binding -> 'target'::text) ->> 'version'::text) ~ '^[1-9][0-9]*$'::text)))) IS TRUE)))
);

COMMENT ON TABLE public.financial_document_extractions IS 'Private document draft, preparation checkpoint and Storage reference to the retained source; erased on disconnect/deletion.';

COMMENT ON COLUMN public.financial_document_extractions.source_bytes IS 'Legacy retained source from before 20261008100000. Read only; never written.';

COMMENT ON COLUMN public.financial_document_extractions.source_path IS 'Sealed original at sealed/{user_id}/{original_sha256}; legacy unprefixed objects stay in place.';

COMMENT ON COLUMN public.financial_document_extractions.rebuilt_path IS 'User-readable copy at rebuilt/{user_id}/{original_sha256}; absent until a rebuilt producer writes it.';

COMMENT ON COLUMN public.financial_document_extractions.rebuilt_sha256 IS 'Digest of rebuilt bytes, independently verified when read. The object name uses the original digest.';

