CREATE TABLE public.financial_import_events (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    state text NOT NULL,
    evidence text NOT NULL,
    anchor_on date,
    attention text,
    attention_detail jsonb,
    possible_duplicates uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    resolution jsonb DEFAULT '{}'::jsonb NOT NULL,
    activity_id uuid,
    accept_key text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version integer NOT NULL,
    owner_space_id uuid,
    business_kind text GENERATED ALWAYS AS (((((resolution -> 'business'::text) -> 'facts'::text) -> 'kind'::text) ->> 'value'::text)) STORED,
    business_rnc text GENERATED ALWAYS AS (argus_private.business_rnc_digits((((((resolution -> 'business'::text) -> 'facts'::text) -> 'fiscal'::text) -> 'rnc'::text) ->> 'value'::text))) STORED,
    business_fiscal_number text GENERATED ALWAYS AS (argus_private.business_fiscal_number((((((resolution -> 'business'::text) -> 'facts'::text) -> 'fiscal'::text) -> 'ecf'::text) ->> 'value'::text), (((((resolution -> 'business'::text) -> 'facts'::text) -> 'fiscal'::text) -> 'ncf'::text) ->> 'value'::text))) STORED,
    CONSTRAINT financial_import_events_accept_key_check CHECK (((accept_key IS NULL) OR ((char_length(accept_key) >= 1) AND (char_length(accept_key) <= 80)))),
    CONSTRAINT financial_import_events_activity_matches_state CHECK (((state = 'accepted'::text) = (activity_id IS NOT NULL))),
    CONSTRAINT financial_import_events_attention_check CHECK (((attention IS NULL) OR (attention = ANY (ARRAY['source_changed'::text, 'source_removed'::text, 'possible_duplicate'::text, 'ambiguous_match'::text])))),
    CONSTRAINT financial_import_events_business_resolution_check CHECK (((NOT (resolution ? 'business'::text)) OR (((owner_space_id IS NOT NULL) AND (jsonb_typeof((resolution -> 'business'::text)) = 'object'::text) AND (((resolution -> 'business'::text) ->> 'schema_version'::text) = '1'::text) AND (jsonb_typeof(((resolution -> 'business'::text) -> 'facts'::text)) = 'object'::text)) IS TRUE))),
    CONSTRAINT financial_import_events_evidence_check CHECK ((evidence = ANY (ARRAY['transaction'::text, 'balance'::text, 'statement_period'::text, 'due_notice'::text, 'payment_notice'::text, 'unclassified'::text]))),
    CONSTRAINT financial_import_events_state_check CHECK ((state = ANY (ARRAY['open'::text, 'accepting'::text, 'accepted'::text, 'dismissed'::text]))),
    CONSTRAINT financial_import_events_version_check CHECK ((version >= 1))
);

COMMENT ON COLUMN public.financial_import_events.owner_space_id IS 'Copy of the space of every observation''s connection, set when the event is created; null means Personal. import_observation_same_space keeps the copies equal.';

