    CONSTRAINT financial_plan_definition_revisions_revision_check CHECK ((revision > 0))
);

CREATE TABLE public.financial_plan_links (
    user_id uuid NOT NULL,
    occurrence_id uuid,
    expectation_id uuid,
    activity_id uuid NOT NULL,
    activity_revision integer NOT NULL,
    snapshot jsonb NOT NULL,
    claim_id uuid DEFAULT gen_random_uuid() NOT NULL,
    goal_id uuid,
    attribution jsonb,
    debt_plan_id uuid,
    activity_owner_id uuid NOT NULL,
    binding_id uuid,
    contributor_membership_id uuid,
    purpose text,
    released_at timestamp with time zone,
    budget_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT financial_plan_claim_purpose CHECK ((((binding_id IS NULL) AND (contributor_membership_id IS NULL) AND (purpose IS NULL) AND (budget_id IS NULL) AND (activity_owner_id = user_id) AND (((expectation_id IS NOT NULL) AND (goal_id IS NULL) AND (debt_plan_id IS NULL) AND (occurrence_id IS NOT NULL) AND (attribution IS NULL)) OR ((expectation_id IS NULL) AND (goal_id IS NOT NULL) AND (debt_plan_id IS NULL) AND (attribution IS NOT NULL) AND (COALESCE(((attribution ->> 'counting'::text))::boolean, false) OR (occurrence_id IS NOT NULL))) OR ((expectation_id IS NULL) AND (goal_id IS NULL) AND (debt_plan_id IS NOT NULL) AND (attribution IS NOT NULL)))) OR ((binding_id IS NOT NULL) AND (contributor_membership_id IS NOT NULL) AND (purpose IS NOT NULL) AND (attribution IS NOT NULL) AND (num_nonnulls(budget_id, expectation_id, goal_id, debt_plan_id) = 1)))),
    CONSTRAINT financial_plan_links_purpose_check CHECK ((purpose = ANY (ARRAY['funding'::text, 'spending'::text, 'bill_payment'::text, 'goal_saving'::text, 'debt_payment'::text])))
);

