    schedule_id uuid,
    agreed_date date,
    CONSTRAINT financial_plan_responsibilities_amount_minor_check CHECK ((amount_minor >= 0)),
    CONSTRAINT financial_plan_responsibilities_check CHECK ((num_nonnulls(period, occurrence_id, schedule_id, agreed_date) = 1)),
    CONSTRAINT financial_plan_responsibilities_period_check CHECK (((period IS NULL) OR (period ~ '^\d{4}-\d{2}$'::text)))
);

