CREATE TABLE public.financial_record_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    record_id uuid NOT NULL,
    user_id uuid NOT NULL,
    revision integer NOT NULL,
    amount_minor bigint NOT NULL,
    as_of timestamp with time zone NOT NULL,
    as_of_zone text NOT NULL,
    reason text,
    capture_method text DEFAULT 'manual'::text NOT NULL,
    recorded_by uuid,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    purchase_activity_id uuid GENERATED ALWAYS AS (((details ->> 'purchase_activity_id'::text))::uuid) STORED,
    purchase_revision integer GENERATED ALWAYS AS (((details ->> 'purchase_revision'::text))::integer) STORED,
    reversal_of_activity_id uuid GENERATED ALWAYS AS (((details ->> 'reversal_of_activity_id'::text))::uuid) STORED,
    reversal_of_revision integer GENERATED ALWAYS AS (((details ->> 'reversal_of_revision'::text))::integer) STORED,
    reversal_of_owner_id uuid GENERATED ALWAYS AS (
CASE
    WHEN ((details ->> 'reversal_of_activity_id'::text) IS NOT NULL) THEN COALESCE(((details ->> 'reversal_of_owner_id'::text))::uuid, user_id)
    ELSE NULL::uuid
END) STORED,
    CONSTRAINT financial_payment_return_revision_pair CHECK (((reversal_of_activity_id IS NULL) = (reversal_of_revision IS NULL))),
    CONSTRAINT financial_purchase_revision_pair CHECK (((purchase_activity_id IS NULL) = (purchase_revision IS NULL))),
    CONSTRAINT financial_record_revisions_capture_method_check CHECK ((capture_method = 'manual'::text)),
    CONSTRAINT financial_record_revisions_reason_check CHECK (((reason IS NULL) OR ((char_length(reason) >= 1) AND (char_length(reason) <= 200)))),
    CONSTRAINT financial_record_revisions_revision_check CHECK ((revision >= 1))
);

CREATE TABLE public.financial_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
