    owner_space_id uuid,
    funding text,
    currency text,
    CONSTRAINT financial_records_current_revision_check CHECK ((current_revision >= 1)),
    CONSTRAINT financial_records_funding_shape CHECK ((((account_id IS NOT NULL) AND (owner_space_id IS NULL) AND (funding IS NULL) AND (currency IS NULL)) OR ((account_id IS NULL) AND (owner_space_id IS NOT NULL) AND (currency IS NOT NULL) AND (currency ~ '^[A-Z]{3}$'::text) AND (((record_kind = 'expense'::text) AND ((funding IS NULL) OR (funding = 'owner_funds'::text))) OR ((record_kind = 'income'::text) AND (funding IS NULL)))))),
    CONSTRAINT financial_records_record_kind_check CHECK ((record_kind = ANY (ARRAY['opening_balance'::text, 'balance_check'::text, 'expense'::text, 'income'::text, 'transfer'::text, 'card_payment'::text, 'refund'::text, 'debt_payment'::text, 'payment_reversal'::text])))
);

