    external_ref text NOT NULL,
    sync_cursor text,
    secret_ciphertext bytea,
    last_success_at timestamp with time zone,
    last_attempt_at timestamp with time zone,
    last_error_code text,
    attention_code text,
    attention_at timestamp with time zone,
    lease_holder text,
    lease_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    disconnected_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    secret_key_fingerprint text,
    owner_space_id uuid,
    CONSTRAINT financial_source_connections_attention_code_check CHECK (((attention_code IS NULL) OR (attention_code ~ '^[a-z0-9_]{1,64}$'::text))),
    CONSTRAINT financial_source_connections_disconnected_is_empty CHECK (((status <> 'disconnected'::text) OR ((secret_ciphertext IS NULL) AND (sync_cursor IS NULL) AND (attention_code IS NULL) AND (lease_holder IS NULL) AND (disconnected_at IS NOT NULL)))),
    CONSTRAINT financial_source_connections_external_ref_check CHECK (((char_length(external_ref) >= 1) AND (char_length(external_ref) <= 200))),
    CONSTRAINT financial_source_connections_fingerprint_needs_secret CHECK (((secret_ciphertext IS NOT NULL) OR (secret_key_fingerprint IS NULL))),
    CONSTRAINT financial_source_connections_label_check CHECK (((label IS NULL) OR ((char_length(label) >= 1) AND (char_length(label) <= 80)))),
    CONSTRAINT financial_source_connections_last_error_code_check CHECK (((last_error_code IS NULL) OR (last_error_code ~ '^[a-z0-9_]{1,64}$'::text))),
    CONSTRAINT financial_source_connections_lease_holder_check CHECK (((lease_holder IS NULL) OR (char_length(lease_holder) <= 64))),
    CONSTRAINT financial_source_connections_secret_key_fingerprint_check CHECK ((secret_key_fingerprint ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT financial_source_connections_source_check CHECK ((source = ANY (ARRAY['plaid'::text, 'gmail'::text, 'shortcuts'::text, 'statement'::text]))),
    CONSTRAINT financial_source_connections_status_check CHECK ((status = ANY (ARRAY['active'::text, 'needs_reauth'::text, 'error'::text, 'disconnected'::text]))),
    CONSTRAINT financial_source_connections_sync_cursor_check CHECK (((sync_cursor IS NULL) OR (char_length(sync_cursor) <= 4096))),
    CONSTRAINT financial_source_connections_version_check CHECK ((version >= 1))
);

COMMENT ON COLUMN public.financial_source_connections.owner_space_id IS 'The Business space this connection belongs to; null means Personal. Pinned to user_id. Not client-readable.';

