COMMENT ON TABLE public.guest_funnel_milestones IS 'Once-per-subject funnel milestone claims. Not FK-bound: the subject is a visitor, not a profile.';

CREATE TABLE public.guest_workspace_handoffs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    secret_hash text NOT NULL,
    source_user_id uuid NOT NULL,
    destination_user_id uuid,
    source_conversation_id uuid NOT NULL,
    pending_action jsonb,
    status text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '00:10:00'::interval) NOT NULL,
    consumed_at timestamp with time zone,
    destination_email_hash text NOT NULL,
    handoff_kind text DEFAULT 'existing_account'::text NOT NULL,
    CONSTRAINT guest_workspace_handoff_consumption_state CHECK ((((status = 'consumed'::text) AND (consumed_at IS NOT NULL)) OR ((status <> 'consumed'::text) AND (consumed_at IS NULL)))),
    CONSTRAINT guest_workspace_handoff_destination_email_hash CHECK ((destination_email_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT guest_workspace_handoff_fixed_expiry CHECK ((((handoff_kind = 'existing_account'::text) AND (expires_at = (created_at + '00:10:00'::interval))) OR ((handoff_kind = 'new_account_signup'::text) AND (expires_at > created_at) AND (expires_at <= (created_at + '7 days'::interval))))),
    CONSTRAINT guest_workspace_handoff_pending_action_valid CHECK (((pending_action IS NULL) OR argus_private.valid_guest_pending_action(pending_action, source_conversation_id))),
    CONSTRAINT guest_workspace_handoffs_handoff_kind_check CHECK ((handoff_kind = ANY (ARRAY['existing_account'::text, 'new_account_signup'::text]))),
    CONSTRAINT guest_workspace_handoffs_secret_hash_check CHECK ((secret_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT guest_workspace_handoffs_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'consumed'::text, 'revoked'::text])))
);

