    CONSTRAINT household_plan_bindings_check1 CHECK ((((kind = 'budget'::text) = (budget_id IS NOT NULL)) AND ((kind = 'bill'::text) = (expectation_id IS NOT NULL)) AND ((kind = 'goal'::text) = (goal_id IS NOT NULL)) AND ((kind = 'debt'::text) = (debt_plan_id IS NOT NULL)))),
    CONSTRAINT household_plan_bindings_check2 CHECK (((departed_at IS NULL) = (retained_revision IS NULL))),
    CONSTRAINT household_plan_bindings_kind_check CHECK ((kind = ANY (ARRAY['budget'::text, 'bill'::text, 'goal'::text, 'debt'::text])))
