CREATE TABLE public.memory_candidates (
    id text NOT NULL,
    owner_id uuid NOT NULL,
    category text NOT NULL,
    source_label text NOT NULL,
    source_value text NOT NULL,
    future_benefit text NOT NULL,
    trigger text NOT NULL,
    proposed_context text NOT NULL,
    opt_in_scope text[] DEFAULT '{}'::text[] NOT NULL,
    sensitivity_status text NOT NULL,
    sensitivity_flags text[] DEFAULT '{}'::text[] NOT NULL,
    sensitivity_policy_version text NOT NULL,
    sensitivity_content_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT memory_candidates_category_check CHECK ((category = ANY (ARRAY['personalization_preference'::text, 'workflow_preference'::text, 'explicit_decision_note'::text, 'past_session_anchor'::text]))),
    CONSTRAINT memory_candidates_future_benefit_check CHECK (((length(future_benefit) >= 1) AND (length(future_benefit) <= 512))),
    CONSTRAINT memory_candidates_id_check CHECK (((length(id) >= 1) AND (length(id) <= 128))),
    CONSTRAINT memory_candidates_opt_in_scope_check CHECK (argus_private.memory_categories_are_valid(opt_in_scope, false)),
    CONSTRAINT memory_candidates_proposed_context_check CHECK ((proposed_context = ANY (ARRAY['ordinary'::text, 'broker'::text, 'export'::text, 'restricted_financial'::text]))),
    CONSTRAINT memory_candidates_sensitivity_content_digest_check CHECK ((sensitivity_content_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT memory_candidates_sensitivity_flags_check CHECK (argus_private.memory_sensitivity_flags_are_valid(sensitivity_flags)),
    CONSTRAINT memory_candidates_sensitivity_policy_version_check CHECK ((sensitivity_policy_version = 'argus.memory-sensitivity/v1'::text)),
    CONSTRAINT memory_candidates_sensitivity_status_check CHECK ((sensitivity_status = ANY (ARRAY['unassessed'::text, 'clear'::text, 'restricted'::text]))),
    CONSTRAINT memory_candidates_source_label_check CHECK (((length(btrim(source_label)) >= 1) AND (length(btrim(source_label)) <= 120))),
    CONSTRAINT memory_candidates_source_value_check CHECK (((length(source_value) >= 1) AND (length(source_value) <= 4096))),
    CONSTRAINT memory_candidates_trigger_check CHECK ((trigger = ANY (ARRAY['saved_decision'::text, 'explicit_request'::text, 'assisted_stable_preference'::text]))),
    CONSTRAINT sensitivity_flags_require_restricted CHECK (((sensitivity_flags = '{}'::text[]) OR (sensitivity_status = 'restricted'::text)))
);

ALTER TABLE ONLY public.memory_candidates FORCE ROW LEVEL SECURITY;

CREATE TABLE public.memory_consent_actions (
    id text NOT NULL,
    owner_id uuid NOT NULL,
    schema_version text DEFAULT 'argus.memory-consent/v1'::text NOT NULL,
    policy_version text DEFAULT 'argus.memory-policy/v1'::text NOT NULL,
    action text NOT NULL,
    candidate_id text,
    requested_scope text[] NOT NULL,
    granted_scope text[] NOT NULL,
    effective_scope text[] NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    idempotency_key text NOT NULL,
    CONSTRAINT memory_consent_action_candidate_shape CHECK ((((action = 'direct_enable'::text) AND (candidate_id IS NULL) AND (cardinality(requested_scope) > 0) AND (cardinality(granted_scope) > 0)) OR ((action = 'candidate_confirmation'::text) AND (candidate_id IS NOT NULL)))),
    CONSTRAINT memory_consent_actions_action_check CHECK ((action = ANY (ARRAY['direct_enable'::text, 'candidate_confirmation'::text]))),
    CONSTRAINT memory_consent_actions_candidate_id_check CHECK (((candidate_id IS NULL) OR ((length(candidate_id) >= 1) AND (length(candidate_id) <= 128)))),
    CONSTRAINT memory_consent_actions_id_check CHECK (((length(id) >= 1) AND (length(id) <= 128))),
    CONSTRAINT memory_consent_actions_idempotency_key_check CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 128))),
    CONSTRAINT memory_consent_actions_policy_version_check CHECK ((policy_version = 'argus.memory-policy/v1'::text)),
    CONSTRAINT memory_consent_actions_schema_version_check CHECK ((schema_version = 'argus.memory-consent/v1'::text)),
    CONSTRAINT memory_consent_effective_scope_valid CHECK (argus_private.memory_categories_are_valid(effective_scope, true)),
    CONSTRAINT memory_consent_granted_is_requested CHECK ((granted_scope <@ requested_scope)),
    CONSTRAINT memory_consent_granted_scope_valid CHECK (argus_private.memory_categories_are_valid(granted_scope, false)),
    CONSTRAINT memory_consent_requested_is_effective CHECK ((requested_scope <@ effective_scope)),
    CONSTRAINT memory_consent_requested_scope_valid CHECK (argus_private.memory_categories_are_valid(requested_scope, false))
);

ALTER TABLE ONLY public.memory_consent_actions FORCE ROW LEVEL SECURITY;

