    CONSTRAINT memory_prompt_history_has_event CHECK (((last_proactive_prompt_at IS NOT NULL) OR (last_declined_at IS NOT NULL))),
    CONSTRAINT memory_prompt_history_update_order CHECK ((((last_proactive_prompt_at IS NULL) OR (updated_at >= last_proactive_prompt_at)) AND ((last_declined_at IS NULL) OR (updated_at >= last_declined_at))))
);

ALTER TABLE ONLY public.memory_prompt_history FORCE ROW LEVEL SECURITY;

