    CONSTRAINT memory_provenance_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT memory_provenance_source_id_check CHECK (((length(source_id) >= 1) AND (length(source_id) <= 512))),
    CONSTRAINT memory_provenance_source_kind_check CHECK ((source_kind = ANY (ARRAY['evidence_artifact'::text, 'decision_note'::text, 'idea'::text, 'idea_version'::text, 'conversation'::text, 'message'::text]))),
    CONSTRAINT memory_provenance_source_version_check CHECK (((length(source_version) >= 1) AND (length(source_version) <= 512)))
);

ALTER TABLE ONLY public.memory_provenance FORCE ROW LEVEL SECURITY;

