    CONSTRAINT memory_provider_cleanup_generation_check CHECK ((generation >= 1)),
    CONSTRAINT memory_provider_cleanup_provider_ref_check CHECK (((length(provider_ref) >= 1) AND (length(provider_ref) <= 1024))),
    CONSTRAINT memory_provider_cleanup_record_id_check CHECK (((length(record_id) >= 1) AND (length(record_id) <= 128))),
    CONSTRAINT memory_provider_cleanup_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'resolved'::text]))),
    CONSTRAINT memory_provider_cleanup_terminal_shape CHECK ((((status = 'pending'::text) AND (resolved_at IS NULL)) OR ((status = 'resolved'::text) AND (resolved_at IS NOT NULL))))
);

ALTER TABLE ONLY public.memory_provider_cleanup FORCE ROW LEVEL SECURITY;

