ALTER TABLE ONLY public.memory_provider_projections FORCE ROW LEVEL SECURITY;

CREATE TABLE public.memory_reconciliations (
    owner_id uuid NOT NULL,
    record_id text NOT NULL,
    generation bigint NOT NULL,
    operation text NOT NULL,
    status text NOT NULL,
    claim_token text,
    lease_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT memory_reconciliations_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT memory_reconciliations_claim_token_check CHECK (((claim_token IS NULL) OR ((length(claim_token) >= 1) AND (length(claim_token) <= 128)))),
    CONSTRAINT memory_reconciliations_error_code_check CHECK (((error_code IS NULL) OR ((length(error_code) >= 1) AND (length(error_code) <= 128)))),
    CONSTRAINT memory_reconciliations_generation_check CHECK ((generation >= 1)),
    CONSTRAINT memory_reconciliations_operation_check CHECK ((operation = ANY (ARRAY['create'::text, 'update'::text, 'delete'::text, 'reset'::text]))),
    CONSTRAINT memory_reconciliations_operation_record_shape CHECK ((((operation = 'reset'::text) AND (record_id = ''::text)) OR ((operation = ANY (ARRAY['create'::text, 'update'::text, 'delete'::text])) AND ((length(record_id) >= 1) AND (length(record_id) <= 128))))),
    CONSTRAINT memory_reconciliations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'succeeded'::text, 'failed'::text]))),
    CONSTRAINT memory_reconciliations_terminal_shape CHECK ((((status = 'pending'::text) AND (claim_token IS NULL) AND (lease_expires_at IS NULL) AND (attempt_count = 0) AND (error_code IS NULL) AND (completed_at IS NULL)) OR ((status = 'running'::text) AND (claim_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (attempt_count >= 1) AND (error_code IS NULL) AND (completed_at IS NULL)) OR ((status = 'succeeded'::text) AND (claim_token IS NULL) AND (lease_expires_at IS NULL) AND (attempt_count >= 1) AND (error_code IS NULL) AND (completed_at IS NOT NULL)) OR ((status = 'failed'::text) AND (claim_token IS NULL) AND (lease_expires_at IS NULL) AND (attempt_count >= 1) AND (error_code IS NOT NULL) AND (completed_at IS NOT NULL))))
);

ALTER TABLE ONLY public.memory_reconciliations FORCE ROW LEVEL SECURITY;

