    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT messages_role_check CHECK ((role = ANY (ARRAY['user'::text, 'assistant'::text, 'system'::text, 'tool'::text])))
);

CREATE TABLE public.private_alpha_access_welcome_claims (
    recipient_email text NOT NULL,
    language text NOT NULL,
    content_version text NOT NULL,
    subject text NOT NULL,
    claim_token uuid DEFAULT gen_random_uuid() NOT NULL,
    claimed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT private_alpha_access_welcome_claims_content_version_check CHECK ((content_version = 'private-alpha-access-welcome/v1'::text)),
    CONSTRAINT private_alpha_access_welcome_claims_language_check CHECK ((language = ANY (ARRAY['en'::text, 'es-419'::text]))),
    CONSTRAINT private_alpha_access_welcome_claims_recipient_email_check CHECK ((recipient_email = lower(btrim(recipient_email)))),
    CONSTRAINT private_alpha_access_welcome_claims_subject_check CHECK (((char_length(subject) >= 1) AND (char_length(subject) <= 200)))
);

CREATE TABLE public.private_alpha_access_welcome_deliveries (
    recipient_email text NOT NULL,
    language text NOT NULL,
    content_version text NOT NULL,
    subject text NOT NULL,
    provider_receipt text NOT NULL,
    sent_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT private_alpha_access_welcome_deliveries_content_version_check CHECK ((content_version = 'private-alpha-access-welcome/v1'::text)),
    CONSTRAINT private_alpha_access_welcome_deliveries_language_check CHECK ((language = ANY (ARRAY['en'::text, 'es-419'::text]))),
    CONSTRAINT private_alpha_access_welcome_deliveries_provider_receipt_check CHECK (((char_length(provider_receipt) >= 1) AND (char_length(provider_receipt) <= 256))),
    CONSTRAINT private_alpha_access_welcome_deliveries_recipient_email_check CHECK ((recipient_email = lower(btrim(recipient_email)))),
    CONSTRAINT private_alpha_access_welcome_deliveries_subject_check CHECK (((char_length(subject) >= 1) AND (char_length(subject) <= 200)))
);

CREATE TABLE public.private_alpha_allowlist (
    email text NOT NULL,
    role text DEFAULT 'user'::text NOT NULL,
    disabled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    language text DEFAULT 'en'::text NOT NULL,
    CONSTRAINT private_alpha_allowlist_email_check CHECK ((email = lower(TRIM(BOTH FROM email)))),
    CONSTRAINT private_alpha_allowlist_language_check CHECK ((language = ANY (ARRAY['en'::text, 'es-419'::text]))),
    CONSTRAINT private_alpha_allowlist_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'developer'::text, 'user'::text, 'requested'::text])))
);

CREATE TABLE public.profile_photos (
    user_id uuid NOT NULL,
    sha256 text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT profile_photos_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text))
);

COMMENT ON TABLE public.profile_photos IS 'The person has a photo at people/{user_id}/256.webp in the private profile-images bucket; served as signed URLs by the API.';

CREATE TABLE public.profiles (
    id uuid NOT NULL,
    email text,
    username text,
    display_name text,
    language text DEFAULT 'en'::text NOT NULL,
    locale text DEFAULT 'en-US'::text NOT NULL,
    is_admin boolean DEFAULT false NOT NULL,
    onboarding jsonb DEFAULT '{"stage": "language_selection", "completed": false, "primary_goal": null, "language_confirmed": false}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    avatar_theme public.avatar_theme DEFAULT 'ocean'::public.avatar_theme NOT NULL,
    preferred_name text,
    country text,
    currency_override text,
    name_initialization_closed boolean DEFAULT false NOT NULL,
    age_confirmed_at timestamp with time zone,
    table_density text DEFAULT 'normal'::text NOT NULL,
    CONSTRAINT profiles_country_shape CHECK (((country IS NULL) OR (country ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT profiles_currency_override_shape CHECK (((currency_override IS NULL) OR (currency_override ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT profiles_language_check CHECK ((language = ANY (ARRAY['en'::text, 'es-419'::text]))),
    CONSTRAINT profiles_locale_check CHECK ((locale = ANY (ARRAY['en-US'::text, 'es-419'::text]))),
    CONSTRAINT profiles_preferred_name_length CHECK (((preferred_name IS NULL) OR ((char_length(preferred_name) >= 1) AND (char_length(preferred_name) <= 40)))),
    CONSTRAINT profiles_table_density_check CHECK ((table_density = ANY (ARRAY['compacto'::text, 'normal'::text, 'amplio'::text])))
);

COMMENT ON COLUMN public.profiles.age_confirmed_at IS 'First client 18+ attestation instant, not verified age. No birthday or raw age range.';

COMMENT ON COLUMN public.profiles.table_density IS 'Row height for dense tables: compacto 40px, normal 48px, amplio 56px. Type size does not change.';

CREATE TABLE public.public_excerpt_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    public_id text NOT NULL,
    owner_id uuid NOT NULL,
    evidence_artifact_id uuid,
    source_conversation_id uuid,
    source_run_id uuid,
    title text NOT NULL,
    payload jsonb NOT NULL,
    payload_digest text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revocation_reason text,
    kind text DEFAULT 'backtest'::text NOT NULL,
    source_message_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    source_run_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    source_artifact_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    selection_key text,
    CONSTRAINT public_excerpt_revocation_is_complete CHECK (((revoked_at IS NULL) = (revocation_reason IS NULL))),
    CONSTRAINT public_excerpt_selection_bounds CHECK ((((selection_key IS NULL) AND (cardinality(source_message_ids) = 0)) OR ((selection_key IS NOT NULL) AND (cardinality(source_message_ids) >= 1)))),
    CONSTRAINT public_excerpt_snapshots_kind_check CHECK ((kind = ANY (ARRAY['backtest'::text, 'research_answer'::text, 'calculation'::text, 'answer'::text, 'mixed'::text]))),
    CONSTRAINT public_excerpt_snapshots_payload_digest_check CHECK ((payload_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT public_excerpt_snapshots_public_id_check CHECK ((public_id ~ '^[A-Za-z0-9_-]{22,64}$'::text)),
    CONSTRAINT public_excerpt_snapshots_revocation_reason_check CHECK ((revocation_reason = ANY (ARRAY['owner_revoked'::text, 'source_deleted'::text, 'removed_by_argus'::text]))),
    CONSTRAINT public_excerpt_snapshots_selection_key_check CHECK ((selection_key ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE public.route_receipts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    conversation_id uuid,
    run_id uuid,
    message_id uuid,
    task text NOT NULL,
    tier text NOT NULL,
    model text,
    fallback_model text,
    mode text NOT NULL,
    schema_name text,
    latency_ms integer DEFAULT 0 NOT NULL,
    outcome text NOT NULL,
    failure_mode text,
    fallback_used boolean DEFAULT false NOT NULL,
    token_usage jsonb,
    context_packet_ids text[] DEFAULT '{}'::text[] NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT route_receipts_mode_check CHECK ((mode = ANY (ARRAY['json_schema'::text, 'chat_model'::text]))),
    CONSTRAINT route_receipts_outcome_check CHECK ((outcome = ANY (ARRAY['succeeded'::text, 'failed'::text, 'skipped'::text]))),
    CONSTRAINT route_receipts_tier_check CHECK ((tier = ANY (ARRAY['utility'::text, 'chat'::text, 'structured'::text, 'context'::text, 'readout'::text, 'vision'::text])))
);

CREATE TABLE public.run_context_packets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    run_id uuid NOT NULL,
    context_packet_id uuid NOT NULL,
    explanation_id text,
    attached_at timestamp with time zone DEFAULT now() NOT NULL,
    immutable_snapshot boolean DEFAULT true NOT NULL
);

CREATE TABLE public.spaces (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    name text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    business_name_prompt_seen_at timestamp with time zone,
    business_rnc text,
    business_tax_id_type text,
    country text DEFAULT 'DO'::text NOT NULL,
    currency text DEFAULT 'DOP'::text NOT NULL,
    current_owner_id uuid,
    membership_revision bigint DEFAULT 0 NOT NULL,
    business_legacy_default boolean DEFAULT true NOT NULL,
    business_workspace_revision bigint DEFAULT 0 NOT NULL,
    business_provided_details jsonb DEFAULT '{}'::jsonb NOT NULL,
    business_appearance jsonb DEFAULT '{"kind": "default"}'::jsonb NOT NULL,
    business_legal_name text,
    business_legal_name_confirmed_by uuid,
    business_legal_name_confirmed_at timestamp with time zone,
    CONSTRAINT business_country_known CHECK (((kind <> 'business'::text) OR (country = ANY (ARRAY['DO'::text, 'US'::text, 'CA'::text])))),
    CONSTRAINT business_currency_shape CHECK (((kind <> 'business'::text) OR (currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT business_legal_name_confirmed CHECK ((((business_legal_name IS NULL) AND (business_legal_name_confirmed_by IS NULL) AND (business_legal_name_confirmed_at IS NULL)) OR ((kind = 'business'::text) AND (business_rnc IS NOT NULL) AND ((length(btrim(business_legal_name)) >= 1) AND (length(btrim(business_legal_name)) <= 250)) AND (business_legal_name = btrim(business_legal_name)) AND (business_legal_name_confirmed_at IS NOT NULL)))),
    CONSTRAINT business_open_owner_required CHECK (((closed_at IS NOT NULL) OR (current_owner_id IS NOT NULL))),
    CONSTRAINT business_tax_id_pair CHECK ((((business_rnc IS NULL) AND (business_tax_id_type IS NULL)) OR ((kind = 'business'::text) AND (business_rnc !~ '^0+$'::text) AND (((business_tax_id_type = 'rnc'::text) AND (business_rnc ~ '^[0-9]{9}$'::text)) OR ((business_tax_id_type = 'cedula'::text) AND (business_rnc ~ '^[0-9]{11}$'::text)))))),
    CONSTRAINT spaces_business_appearance_check CHECK ((jsonb_typeof(business_appearance) = 'object'::text)),
    CONSTRAINT spaces_business_provided_details_check CHECK ((jsonb_typeof(business_provided_details) = 'object'::text)),
    CONSTRAINT spaces_business_workspace_revision_check CHECK ((business_workspace_revision >= 0)),
    CONSTRAINT spaces_kind_check CHECK ((kind = 'business'::text)),
    CONSTRAINT spaces_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 80)))
);

COMMENT ON TABLE public.spaces IS 'A Business space, owned by created_by. One open Business space per person. Rows that belong to it carry owner_space_id; null means Personal. #819 may add a Personal space per person and space_memberships backfilled from created_by, without re-keying any record.';

COMMENT ON COLUMN public.spaces.created_by IS 'Stable Business record custodian. Ownership transfer does not rekey financial records or originals.';

COMMENT ON COLUMN public.spaces.current_owner_id IS 'Legacy default Business and transfer anchor; not membership authority. Record custody remains created_by.';

COMMENT ON COLUMN public.spaces.membership_revision IS 'Serialization version for membership changes, including repeatable-read transactions.';

COMMENT ON COLUMN public.spaces.business_legacy_default IS 'Legacy bootstrap and default resolver slot. Additional Businesses do not acquire this slot on read, sign-in or closure.';

COMMENT ON COLUMN public.spaces.business_provided_details IS 'Business-provided contact and presence fields. No verification or fiscal activation is implied.';

CREATE TABLE public.strategies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    conversation_id uuid,
    name text NOT NULL,
    name_source text DEFAULT 'system_default'::text NOT NULL,
    template text NOT NULL,
    asset_class text NOT NULL,
    symbols text[] NOT NULL,
    parameters jsonb DEFAULT '{}'::jsonb NOT NULL,
    metrics_preferences text[] DEFAULT ARRAY['total_return_pct'::text, 'win_rate'::text, 'max_drawdown_pct'::text] NOT NULL,
    benchmark_symbol text NOT NULL,
    pinned boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT strategies_asset_class_check CHECK ((asset_class = ANY (ARRAY['equity'::text, 'crypto'::text, 'currency_pair'::text]))),
    CONSTRAINT strategies_name_source_check CHECK ((name_source = ANY (ARRAY['system_default'::text, 'ai_generated'::text, 'user_renamed'::text]))),
    CONSTRAINT strategies_symbols_check CHECK (((array_length(symbols, 1) >= 1) AND (array_length(symbols, 1) <= 5)))
);

CREATE TABLE public.usage_counters (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    resource text NOT NULL,
    period text NOT NULL,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    used_count integer DEFAULT 0 NOT NULL,
    limit_count integer NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT usage_counters_period_check CHECK ((period = ANY (ARRAY['hour'::text, 'day'::text, 'guest_session'::text]))),
    CONSTRAINT usage_counters_resource_check CHECK ((resource = ANY (ARRAY['chat_messages'::text, 'backtest_runs'::text, 'backtest_jobs'::text, 'feedback'::text])))
);

CREATE TABLE public.visitor_usage_counters (
    visitor_key text NOT NULL,
    resource text NOT NULL,
    period text NOT NULL,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    used_count integer DEFAULT 0 NOT NULL,
    limit_count integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.visitor_usage_counters IS 'Allowances for callers with no durable account. Not FK-bound: the subject is a visitor, not a profile. A fresh guest session mints a new user_id, so account-keyed guest allowances reset with it; visitor keys do not.';

CREATE TABLE public.whatsapp_inbound_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider_message_key bytea NOT NULL,
    sender_hash bytea NOT NULL,
    destination_owner_id uuid,
    status text NOT NULL,
    connection_id uuid,
    error_code text,
    claim_until timestamp with time zone,
    received_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    arrival_sequence bigint NOT NULL,
    sender_link_id uuid,
    destination_space_id uuid,
    sent_at timestamp with time zone,
    transport_envelope bytea,
    transport_key_id text,
    composition_state text DEFAULT 'not_started'::text NOT NULL,
    ai_consent_id uuid,
    claim_envelope bytea,
    recovery_attempts smallint DEFAULT 0 NOT NULL,
    CONSTRAINT whatsapp_inbound_ai_consent_shape CHECK (((ai_consent_id IS NULL) OR (transport_envelope IS NOT NULL))),
    CONSTRAINT whatsapp_inbound_capture_shape CHECK (((status <> 'captured'::text) OR (connection_id IS NOT NULL) OR (transport_envelope IS NOT NULL))),
    CONSTRAINT whatsapp_inbound_claim_envelope_shape CHECK (((claim_envelope IS NULL) OR ((status = ANY (ARRAY['received'::text, 'failed'::text])) AND (octet_length(claim_envelope) > 29) AND (get_byte(claim_envelope, 0) = 1)))),
    CONSTRAINT whatsapp_inbound_envelope_shape CHECK ((((transport_envelope IS NULL) AND (transport_key_id IS NULL) AND (sender_link_id IS NULL) AND (destination_space_id IS NULL) AND (sent_at IS NULL)) OR ((transport_envelope IS NOT NULL) AND (octet_length(transport_envelope) > 29) AND (get_byte(transport_envelope, 0) = 1) AND (transport_key_id IS NOT NULL) AND (transport_key_id ~ '^[0-9a-f]{32}$'::text) AND (sender_link_id IS NOT NULL) AND (destination_space_id IS NOT NULL) AND (destination_owner_id IS NOT NULL) AND (sent_at IS NOT NULL) AND (connection_id IS NULL) AND (status = 'captured'::text)))),
    CONSTRAINT whatsapp_inbound_messages_check1 CHECK (((status <> ALL (ARRAY['captured'::text, 'linked'::text])) OR (destination_owner_id IS NOT NULL))),
    CONSTRAINT whatsapp_inbound_messages_composition_state_check CHECK ((composition_state = ANY (ARRAY['not_started'::text, 'started'::text, 'completed'::text, 'unknown'::text]))),
    CONSTRAINT whatsapp_inbound_messages_error_code_check CHECK (((error_code IS NULL) OR (char_length(error_code) <= 64))),
    CONSTRAINT whatsapp_inbound_messages_provider_message_key_check CHECK ((octet_length(provider_message_key) = 32)),
    CONSTRAINT whatsapp_inbound_messages_recovery_attempts_check CHECK (((recovery_attempts >= 0) AND (recovery_attempts <= 100))),
    CONSTRAINT whatsapp_inbound_messages_sender_hash_check CHECK ((octet_length(sender_hash) = 32)),
    CONSTRAINT whatsapp_inbound_messages_status_check CHECK ((status = ANY (ARRAY['received'::text, 'linked'::text, 'rejected'::text, 'captured'::text, 'failed'::text])))
);

ALTER TABLE public.whatsapp_inbound_messages ALTER COLUMN arrival_sequence ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.whatsapp_inbound_messages_arrival_sequence_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.whatsapp_link_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    destination_owner_id uuid NOT NULL,
    code_digest bytea NOT NULL,
    reply_language text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    CONSTRAINT whatsapp_link_codes_check CHECK ((expires_at > created_at)),
    CONSTRAINT whatsapp_link_codes_code_digest_check CHECK ((octet_length(code_digest) = 32)),
    CONSTRAINT whatsapp_link_codes_reply_language_check CHECK ((reply_language = ANY (ARRAY['es-419'::text, 'en'::text])))
);

CREATE TABLE public.whatsapp_outbox (
    provider_message_key bytea NOT NULL,
    reply_index integer NOT NULL,
    body text NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    attempted_at timestamp with time zone,
    sent_at timestamp with time zone,
    error_code text,
    CONSTRAINT whatsapp_outbox_body_check CHECK (((char_length(body) >= 1) AND (char_length(body) <= 4096))),
    CONSTRAINT whatsapp_outbox_check CHECK (((state = 'sent'::text) = (sent_at IS NOT NULL))),
    CONSTRAINT whatsapp_outbox_check1 CHECK (((state <> ALL (ARRAY['sending'::text, 'sent'::text, 'unknown'::text])) OR (attempted_at IS NOT NULL))),
    CONSTRAINT whatsapp_outbox_error_code_check CHECK (((error_code IS NULL) OR (char_length(error_code) <= 64))),
    CONSTRAINT whatsapp_outbox_reply_index_check CHECK ((reply_index >= 0)),
    CONSTRAINT whatsapp_outbox_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'sending'::text, 'sent'::text, 'unknown'::text, 'waiting_for_window'::text, 'suppressed'::text])))
);

CREATE TABLE public.whatsapp_reply_attempts (
    sender_hash bytea NOT NULL,
    token uuid NOT NULL,
    owner_id uuid NOT NULL,
    link_id uuid NOT NULL,
    day date NOT NULL,
    failed_count integer NOT NULL,
    samples jsonb NOT NULL,
    last_sent_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    retries integer NOT NULL,
    CONSTRAINT whatsapp_reply_attempts_failed_count_check CHECK ((failed_count > 0)),
    CONSTRAINT whatsapp_reply_attempts_retries_check CHECK ((retries >= 0)),
    CONSTRAINT whatsapp_reply_attempts_samples_check CHECK (((jsonb_typeof(samples) = 'array'::text) AND ((jsonb_array_length(samples) >= 1) AND (jsonb_array_length(samples) <= 3)))),
    CONSTRAINT whatsapp_reply_attempts_sender_hash_check CHECK ((octet_length(sender_hash) = 32))
);

CREATE TABLE public.whatsapp_reply_days (
    sender_hash bytea NOT NULL,
    day date NOT NULL,
    owner_id uuid NOT NULL,
    sent_count integer DEFAULT 0 NOT NULL,
    reserved_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT whatsapp_reply_days_reserved_count_check CHECK ((reserved_count >= 0)),
    CONSTRAINT whatsapp_reply_days_sender_hash_check CHECK ((octet_length(sender_hash) = 32)),
    CONSTRAINT whatsapp_reply_days_sent_count_check CHECK ((sent_count >= 0))
);

CREATE TABLE public.whatsapp_reply_groups (
    sender_hash bytea NOT NULL,
    owner_id uuid NOT NULL,
    link_id uuid NOT NULL,
    failed_count integer NOT NULL,
    samples jsonb NOT NULL,
    last_sent_at timestamp with time zone NOT NULL,
    send_after timestamp with time zone NOT NULL,
    retries integer DEFAULT 0 NOT NULL,
    CONSTRAINT whatsapp_reply_groups_failed_count_check CHECK ((failed_count > 0)),
    CONSTRAINT whatsapp_reply_groups_retries_check CHECK ((retries >= 0)),
    CONSTRAINT whatsapp_reply_groups_samples_check CHECK (((jsonb_typeof(samples) = 'array'::text) AND ((jsonb_array_length(samples) >= 1) AND (jsonb_array_length(samples) <= 3)))),
    CONSTRAINT whatsapp_reply_groups_sender_hash_check CHECK ((octet_length(sender_hash) = 32))
);

CREATE TABLE public.whatsapp_sender_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    destination_owner_id uuid NOT NULL,
    wa_id_hash bytea NOT NULL,
    last4 text NOT NULL,
    reply_language text NOT NULL,
    status text NOT NULL,
    linked_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    destination_space_id uuid NOT NULL,
    CONSTRAINT whatsapp_sender_links_check CHECK (((status = 'active'::text) = (revoked_at IS NULL))),
    CONSTRAINT whatsapp_sender_links_last4_check CHECK ((last4 ~ '^[0-9]{1,4}$'::text)),
    CONSTRAINT whatsapp_sender_links_reply_language_check CHECK ((reply_language = ANY (ARRAY['es-419'::text, 'en'::text]))),
    CONSTRAINT whatsapp_sender_links_status_check CHECK ((status = ANY (ARRAY['active'::text, 'revoked'::text]))),
    CONSTRAINT whatsapp_sender_links_wa_id_hash_check CHECK ((octet_length(wa_id_hash) = 32))
);

COMMENT ON TABLE public.whatsapp_sender_links IS 'A verified link from one sending WhatsApp number to one Business space. destination_owner_id is the person who owns that space, not a business principal; destination_space_id is the space captured receipts land in. Link codes and inbound messages keep only destination_owner_id.';

COMMENT ON COLUMN public.whatsapp_sender_links.destination_space_id IS 'The Business space captures land in. Filled from business_space_of (destination_owner_id) when the insert leaves it null; pinned to destination_owner_id.';

