CREATE POLICY backtest_jobs_guest_session_active ON public.backtest_jobs AS RESTRICTIVE FOR SELECT TO authenticated USING (((( SELECT (auth.jwt() ->> 'is_anonymous'::text)) IS DISTINCT FROM 'true'::text) OR (EXISTS ( SELECT 1
