   FROM public.guest_workspaces g
  WHERE ((g.user_id = messages.user_id) AND (g.status = 'active'::text) AND (g.expires_at > now())))))) WITH CHECK (((( SELECT (auth.jwt() ->> 'is_anonymous'::text)) IS DISTINCT FROM 'true'::text) OR (EXISTS ( SELECT 1
   FROM public.guest_workspaces g
  WHERE ((g.user_id = messages.user_id) AND (g.status = 'active'::text) AND (g.expires_at > now()))))));

