CREATE TRIGGER bind_guest_signup_handoff AFTER INSERT ON auth.users FOR EACH ROW WHEN (((COALESCE((new.raw_app_meta_data ->> 'placeholder'::text), ''::text) <> 'true'::text) AND ((COALESCE(new.email, ''::character varying))::text !~~ 'exmiembro+%@cuadrao.invalid'::text))) EXECUTE FUNCTION argus_private.bind_guest_signup_handoff();
CREATE TRIGGER business_auth_retention_guard BEFORE DELETE ON auth.users FOR EACH ROW EXECUTE FUNCTION argus_private.business_auth_retention_guard();
CREATE TRIGGER business_fiscal_actor_retained BEFORE DELETE ON auth.users FOR EACH ROW EXECUTE FUNCTION argus_private.business_fiscal_actor_retained();
CREATE TRIGGER business_invitation_auth_retention BEFORE DELETE ON auth.users FOR EACH ROW EXECUTE FUNCTION argus_private.business_invitation_auth_retention();
CREATE TRIGGER finalize_linked_guest_identity AFTER UPDATE OF email, is_anonymous ON auth.users FOR EACH ROW WHEN (((COALESCE((new.raw_app_meta_data ->> 'placeholder'::text), ''::text) <> 'true'::text) AND ((COALESCE(new.email, ''::character varying))::text !~~ 'exmiembro+%@cuadrao.invalid'::text))) EXECUTE FUNCTION argus_private.finalize_linked_guest_identity();
CREATE TRIGGER refuse_placeholder_email BEFORE INSERT OR UPDATE OF email ON auth.users FOR EACH ROW WHEN ((lower((COALESCE(new.email, ''::character varying))::text) ~~ '%@cuadrao.invalid'::text)) EXECUTE FUNCTION argus_private.refuse_placeholder_email();

create event trigger ensure_rls on ddl_command_end when tag in ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO') execute function public.rls_auto_enable();
